insert into public.themen (id, name, beschreibung) values
  (1, 'Arzttermine', 'Lange Wartezeiten und schwer erreichbare Praxen.'),
  (2, 'Miete', 'Hohe Mieten und schwierige Wohnungssuche.'),
  (3, 'Energiepreise', 'Hohe Kosten für Strom und Heizung.'),
  (4, 'Schule', 'Unterrichtsausfall, fehlende Lehrkräfte und marode Schulgebäude.'),
  (5, 'Arbeitsplätze', 'Unsichere Jobs, Stellenabbau und schwache Wirtschaft.'),
  (6, 'Zuwanderung und Integration', 'Probleme bei Aufnahme, Integration und Rückführung von Zugewanderten.'),
  (7, 'Rente', 'Niedrige Renten und Sorge um die Altersvorsorge.'),
  (8, 'Bus und Bahn', 'Seltene Verbindungen, Ausfälle, Verspätungen und teure Tickets.'),
  (9, 'Sicherheit', 'Opfer von Gewalt, Diebstahl oder Betrug werden – zu Hause, unterwegs oder im Internet – oder sich im Alltag unsicher fühlen.'),
  (10, 'Pflege', 'Pflegeplatz oder Pflegedienst finden, hohe Kosten, überlastete Angehörige.'),
  (11, 'Preise und Löhne', 'Lebensmittel und Dinge des Alltags sind teuer geworden, der Lohn reicht kaum.'),
  (12, 'Straßen und Brücken', 'Kaputte Straßen, gesperrte Brücken, lange Umwege und gefährliche Radwege.'),
  (13, 'Internet und Mobilfunk', 'Langsames Internet zu Hause und Funklöcher unterwegs.'),
  (14, 'Behördengänge', 'Lange Wartezeiten auf Termine und Bescheide, viel Papier, dieselben Angaben immer wieder.'),
  (15, 'Autofahren', 'Teures Tanken, wenige Lademöglichkeiten und teure Elektroautos.'),
  (16, 'Heizungstausch', 'Unsicherheit und hohe Kosten, wenn die Heizung erneuert werden muss oder soll.'),
  (17, 'Kita-Betreuung', 'Familien finden keinen passenden Betreuungsplatz oder erleben, dass die Betreuung zu wenig Personal hat, ausfällt oder zu viel kostet.'),
  (18, 'Hitze und Unwetter', 'Hitzewellen, Starkregen und Hochwasser belasten die Gesundheit und beschädigen Wohnungen und Eigentum.'),
  (19, 'Diskriminierung im Alltag', 'Menschen werden wegen zugeschriebener Herkunft, Religion, sexueller oder geschlechtlicher Identität bei der Wohnungs- und Arbeitssuche, in Behörden, Schulen und im öffentlichen Raum benachteiligt oder angefeindet.'),
  (20, 'Freizeitangebote und Treffpunkte für Jugendliche', 'Jugendliche finden vor Ort keine passenden Freizeitangebote oder Treffpunkte, können Aktivitäten nicht bezahlen oder verlieren Aufenthaltsorte durch Konflikte mit Anwohnenden und anderen Nutzenden.'),
  (21, 'Armut und Kinderarmut', 'Menschen haben zu wenig Geld für grundlegende Bedürfnisse und gesellschaftliche Teilhabe. Kinder wachsen unter finanziellen Einschränkungen auf, auch wenn ihre Familien Unterstützung erhalten.'),
  (22, 'Radikalisierung und Extremismus', 'Menschen erleben die Hinwendung zu extremistischen Gruppen und Einstellungen sowie politische Konflikte, in denen gegenseitige Abwertung und Gesprächsabbrüche den Austausch erschweren.'),
  (23, 'Mobbing und Druck in der Schule', 'Schülerinnen und Schüler erleben Mobbing, Cybermobbing, Ausgrenzung oder belastenden Leistungs- und Prüfungsdruck im Schulalltag.'),
  (24, 'Abwanderung aus strukturschwachen Regionen', 'In strukturschwachen Regionen in Ost und West fehlen Zukunftsperspektiven. Junge Menschen ziehen weg, die Bevölkerung wird älter und die Versorgung vor Ort gerät unter Druck.'),
  (25, 'Hass und Anfeindungen im Internet', 'Privatpersonen und politisch Aktive erleben online Hassnachrichten, Beleidigungen, Bedrohungen und Schikanen, etwa Cybermobbing oder das Veröffentlichen persönlicher Daten zur Einschüchterung.'),
  (26, 'Barrieren für Menschen mit Behinderung', 'Menschen mit Behinderung stoßen beim Wohnen, unterwegs, in Gebäuden, bei digitalen Angeboten, im Arbeitsleben und beim Zugang zu Teilhabeleistungen auf Hindernisse.'),
  (27, 'Arbeitsbelastung im Gesundheitswesen', 'Beschäftigte in Pflege, Medizin, Kliniken und Rettungsdienst erleben Zeitdruck, belastende Dienste, knappe Personalbesetzung, aufwendige Dokumentation und unzureichende Anerkennung ihrer Arbeit.'),
  (28, 'Sexismus und Benachteiligung von Frauen', 'Frauen erleben Benachteiligung im Beruf, ungleich verteilte Sorgearbeit, sexuelle Belästigung und widersprüchliche Erwartungen an ihre Lebensgestaltung.'),
  (29, 'Einsamkeit und psychische Belastung', 'Menschen aller Altersgruppen fühlen sich einsam oder psychisch belastet. Manche können ihre Gefühle schwer einordnen oder ausdrücken und finden nicht rechtzeitig passende Unterstützung.'),
  (30, 'Sucht und Glücksspiel', 'Alkohol, Tabak, Drogen, Medikamente oder Glücksspiel beeinträchtigen Gesundheit, Beziehungen und finanzielle Sicherheit. Betroffene erleben Kontrollverlust oder Schwierigkeiten, passende Hilfe zu erhalten.'),
  (31, 'Kosten von Studium und Ausbildung', 'Studierende und Auszubildende haben Schwierigkeiten, Lebenshaltung, Wohnen und Ausbildung zu finanzieren. Nebenjobs und spätere Darlehensrückzahlungen können zusätzlich belasten.'),
  (32, 'Räume für Kultur und Clubs', 'Clubs, Kulturorte, soziokulturelle Zentren, Freilichtbühnen und kulturell genutzte selbstverwaltete Hausprojekte verlieren Räume oder können sie wegen Kosten, Nutzungskonflikten und baulichen Hürden nur eingeschränkt nutzen.'),
  (33, 'Mediennutzung von Kindern und Jugendlichen', 'Kinder und Jugendliche verbringen länger als gewollt Zeit am Bildschirm oder in sozialen Medien. Familien erleben Schwierigkeiten beim Begrenzen sowie Sorgen um Schlaf, Konzentration und altersgerechte Nutzung.'),
  (34, 'Umgang der Polizei mit jungen Menschen', 'Junge Menschen erleben Polizeikontrollen oder Einsätze als belastend, unangemessen oder schwer nachvollziehbar und können mögliche Fehler nur schwer klären lassen.'),
  (35, 'Kosten für den Führerschein', 'Der Führerscheinerwerb ist teuer. Fahrschulpreise, Fahrstunden, Prüfungen und Wartezeiten können Kosten und Dauer schwer planbar machen.'),
  (36, 'Leerstand und Geschäftsschließungen in Innenstädten', 'In Innenstädten und Ortskernen schließen Geschäfte. Ladenflächen stehen leer, Einkaufsangebote verschwinden und manche Orte werden weniger besucht.'),
  (37, 'Finanzierung von Sportvereinen und Sportstätten', 'Breiten- und Amateursportvereinen fehlen finanzielle Spielräume oder geeignete Sportstätten, um Training und Wettkämpfe dauerhaft anzubieten.')
insert into public.ursachen (id, thema_id, beschreibung, quelle_url, ebene, alltag) values
  (101, 1, 'Zu wenige Hausarztpraxen, besonders auf dem Land: Viele Ärztinnen und Ärzte gehen bald in den Ruhestand, zu wenige lassen sich als Hausarzt nieder', 'https://idw-online.de/de/news769524', 'bund', 'Ich finde keine Hausarztpraxis in meiner Nähe, die noch neue Patienten nimmt'),
  (102, 1, 'Termine und Wege durch das Gesundheitssystem werden kaum gesteuert; knappes Personal wird nicht gezielt eingesetzt', 'https://www.svr-gesundheit.de/publikationen/gutachten-2024/', 'bund', 'Ich weiß nicht, wohin ich mich wenden soll, und lande bei Terminen und Wegen im Kreis'),
  (103, 1, 'Unterschiedliche Vergütung: Facharztpraxen vergeben Termine bevorzugt an Privatversicherte', 'https://idw-online.de/de/news750098', 'bund', 'Als Kassenpatient bekomme ich beim Facharzt viel später einen Termin als Privatversicherte'),
  (201, 2, 'Es werden weniger Wohnungen gebaut als gebraucht (Bedarf laut Prognose rund 320.000 pro Jahr)', 'https://www.bbsr.bund.de/BBSR/DE/presse/presseinformationen/2025/wohnungsbedarfsprognose.html', 'bund', 'Ich finde keine Wohnung, weil es zu wenige gibt'),
  (202, 2, 'Mieten bei Neuvermietung liegen rund 43 % über Bestandsmieten, in großen Städten besonders hoch', 'https://www.bbsr.bund.de/BBSR/DE/startseite/topmeldungen/entwicklung-wohnungsmieten-2025.html', 'bund', 'Für eine neue Wohnung soll ich viel mehr Miete zahlen als die Leute, die schon lange dort wohnen'),
  (203, 2, 'Stark gestiegene Baukosten: Wohngebäude wurden 2010 bis 2025 um 89 % teurer, mehr als doppelt so stark wie die Inflation', 'https://www.destatis.de/DE/Themen/Wirtschaft/Preise/Baupreise-Immobilienpreisindex/_inhalt.html', 'bund', 'Neubauwohnungen sind so teuer, dass sich kaum jemand die Miete leisten kann'),
  (204, 2, 'Mieten in laufenden Verträgen steigen weiter (Nettokaltmieten 2025 im Schnitt +2,1 %)', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/01/PD26_019_611.html', 'bund', 'Meine Miete steigt Jahr für Jahr, obwohl ich nicht umgezogen bin'),
  (205, 2, 'Die Nachfrage wächst vor allem in Großstädten: mehr Haushalte, getragen vor allem von Zuwanderung', 'https://www.iwkoeln.de/fileadmin/user_upload/Studien/Report/PDF/2026/IW-Report_2026-Migration-und-Wohnungsmarkt.pdf', 'bund', 'In meiner Stadt wollen so viele Menschen wohnen, dass es kaum freie Wohnungen gibt'),
  (206, 2, 'Jedes Jahr fallen mehr Sozialwohnungen aus der Bindung, als neue gefördert werden (2025: rund 27.000 neu gefördert, rund 55.000 fallen jährlich heraus)', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1200778', 'land', 'Es gibt immer weniger Sozialwohnungen, und ich bekomme keine bezahlbare Wohnung'),
  (301, 3, 'Hohe Netzentgelte für den Betrieb und Ausbau der Stromnetze', 'https://www.bundesnetzagentur.de/DE/Vportal/Energie/PreiseAbschlaege/Tarife-table.html', 'bund', 'Auf meiner Stromrechnung stecken hohe Gebühren für das Stromnetz'),
  (302, 3, 'Steuern, Abgaben und Umlagen machen einen großen Teil der Strom- und Gaspreise aus, beim Gas auch der CO₂-Preis', 'https://www.bundesnetzagentur.de/DE/Vportal/Energie/PreiseAbschlaege/Tarife-table.html', 'bund', 'Auf meiner Strom- und Gasrechnung stecken viele Steuern, Abgaben und der CO₂-Preis'),
  (303, 3, 'Rund 70 % der Energie wird importiert, vor allem Öl, Gas und Steinkohle', 'https://www.umweltbundesamt.de/daten/umweltzustand-trends/energie/primaerenergiegewinnung-importe', 'bund', 'Ich mache mir Sorgen, weil wir Öl und Gas aus dem Ausland brauchen und die Preise davon abhängen'),
  (304, 3, 'Der Strompreis an der Börse richtet sich nach dem teuersten noch benötigten Kraftwerk, heute oft einem Gaskraftwerk', 'https://www.bundestag.de/resource/blob/918822/abb4747668630cbe6d457512d42265c4/WD-5-121-22-pdf-data.pdf', 'bund', 'Strom wird teuer, weil teure Gaskraftwerke den Preis bestimmen, obwohl auch billiger Strom erzeugt wird'),
  (305, 3, 'Drei Viertel der Wohnungen wurden 2022 mit Gas oder Öl beheizt (Zensus); die Heizkosten hängen deshalb stark von deren Preisen ab', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/Zensus2022-Pressemitteilungen/PM_zenus2022_45.html', 'bund', 'Ich heize mit Gas oder Öl, und meine Heizkosten schwanken mit deren Preisen'),
  (401, 4, 'Zu wenige Lehrkräfte: Kurzfristig liegt das Angebot deutlich unter dem Einstellungsbedarf', 'https://www.kmk.org/downloads-dokumente/statistik/schulstatistik/lehrkraefteeinstellungsbedarf-und-angebot.html', 'land', 'Bei uns fällt Unterricht aus, weil Lehrkräfte fehlen'),
  (402, 4, 'Großer Sanierungsstau bei Schulgebäuden (rund 68 Mrd. Euro, größter Posten der Kommunen)', 'https://www.bundestag.de/resource/blob/1157306/KfW-Kommunalpanel-2025.pdf', 'land', 'Die Schule meines Kindes ist in schlechtem Zustand: marode Toiletten, undichte Dächer, alte Ausstattung'),
  (403, 4, 'Wachsende Lernrückstände: Ein Drittel der Neuntklässler verfehlt den Mindeststandard in Mathematik', 'https://www.iqb.hu-berlin.de/de/schule/sekundarstufe-i/bildungstrend/2024/', 'land', 'Mein Kind kommt beim Rechnen und Lesen nicht mit, und viele andere auch nicht'),
  (404, 4, 'Viele Kinder haben schon vor der Einschulung Sprachförderbedarf; die Länder erfassen und fördern das sehr unterschiedlich', 'https://www.bildungsbericht.de/de/bildungsberichte-seit-2006/bildungsbericht-2024/pdf-dateien-2024/bildungsbericht-2024-kapitel-c.pdf', 'land', 'Mein Kind spricht beim Schulstart zu wenig Deutsch und bekommt zu wenig Förderung'),
  (405, 4, 'Der Schulerfolg hängt stark von der sozialen Herkunft ab; sozial benachteiligte Jugendliche fallen seit 2018 weiter zurück', 'https://www.iqb.hu-berlin.de/de/schule/sekundarstufe-i/bildungstrend/2024/', 'land', 'Die Chancen meines Kindes in der Schule hängen davon ab, was die Eltern verdienen und gelernt haben'),
  (501, 5, 'Die Industrie verliert an Wettbewerbsfähigkeit: überdurchschnittlich gestiegene Energiepreise und Lohnstückkosten, dazu hohe wirtschaftspolitische Unsicherheit und geopolitische Veränderungen', 'https://www.sachverstaendigenrat-wirtschaft.de/fileadmin/dateiablage/gutachten/jg202526/JG202526_Kurzfassung.pdf', 'bund', 'Ich mache mir Sorgen um meinen Arbeitsplatz, weil die Firmen im Land mit der Konkurrenz nicht mehr mithalten'),
  (502, 5, 'Strukturwandel: Die Industrie baut Stellen ab, neue Jobs entstehen vor allem in anderen Branchen', 'https://iab.de/presseinfo/iab-prognose-fuer-2026-2027-erwerbstaetigkeit-schrumpft-trotz-besserer-konjunktur/', 'bund', 'In meiner Branche werden Stellen abgebaut, und ich weiß nicht, wo ich neue Arbeit finde'),
  (503, 5, 'Löhne in Ostdeutschland liegen weiterhin deutlich unter denen im Westen', 'https://www.destatis.de/DE/Themen/Querschnitt/35-Jahre-Deutsche-Einheit/Vermoegen-Einkommen/Textbausteine/01_verdienstunterschiede.html', 'bund', 'Ich verdiene im Osten deutlich weniger als Kollegen im Westen für dieselbe Arbeit'),
  (504, 5, 'Zu wenig Investitionen: Für Verkehr, Bildung, Kommunen und Klimaschutz fehlen über zehn Jahre rund 600 Mrd. Euro zusätzliche öffentliche Investitionen', 'https://www.iwkoeln.de/fileadmin/user_upload/Studien/policy_papers/PDF/2024/IW-Policy-Paper_2024-Investitionsbedarfe.pdf', 'bund', 'In meiner Gegend sind Straßen, Schulen und Bahnen in schlechtem Zustand, weil nicht genug investiert wird'),
  (505, 5, 'Hohe Bürokratiekosten: Unternehmen tragen jährlich rund 64 Mrd. Euro Kosten für Berichts- und Informationspflichten', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'bund', 'Betriebe ersticken in Papierkram, und das kostet Arbeitsplätze'),
  (506, 5, 'Mehr zu arbeiten lohnt sich für Menschen im Bürgergeld oft kaum, weil der Hinzuverdienst größtenteils angerechnet wird', 'https://www.bmas.de/DE/Service/Publikationen/Forschungsberichte/fb-629-erwerbstaetigenfreibetraege.html', 'bund', 'Wenn ich mehr arbeite, bleibt mir vom Verdienst kaum etwas, weil das Bürgergeld gekürzt wird'),
  (507, 5, 'Nur knapp die Hälfte der Beschäftigten (49 %) arbeitet in einem tarifgebundenen Betrieb', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/03/PD25_109_623.html', 'bund', 'Mein Betrieb zahlt keinen Tariflohn, und ich verdiene weniger als in tarifgebundenen Betrieben'),
  (601, 6, 'Zahl der Neuankommenden und Kapazitäten vor Ort passen vielerorts nicht zusammen: Unterbringung bleibt für die meisten Kommunen herausfordernd, Ausländerbehörden sind besonders stark belastet', 'https://mediendienst-integration.de/fileadmin/Dateien/EXPERTISE_FLUECHTLINGSAUFNAHME_IN_DEN_KOMMUNEN_MEDIENDIENST_INTEGRATION_NOV_2025_FINAL.pdf', 'land', 'In meiner Stadt oder Gemeinde fehlen Unterkünfte und Personal, um die Neuankommenden zu versorgen'),
  (602, 6, 'Asyl- und Gerichtsverfahren dauern lange (im Schnitt rund anderthalb Jahre bis zur rechtskräftigen Entscheidung)', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1145824', 'bund', 'Asylverfahren dauern bei uns viel zu lange, bis klar ist, ob jemand bleiben darf'),
  (603, 6, 'Sprachkurse, Anerkennung von Abschlüssen und Zugang zum Arbeitsmarkt dauern lange', 'https://iab-forum.de/10-jahre-fluchtmigration-2015-was-integration-foerdert-und-was-sie-bremst/', 'bund', 'Zugewanderte finden schwer Arbeit, weil Sprachkurse und Anerkennung ihrer Abschlüsse so lange dauern'),
  (604, 6, 'Viele Ausreisepflichtige werden nicht zurückgeführt, etwa wegen fehlender Papiere', 'https://mediendienst-integration.de/fluechtlinge/abschiebungen/warum-werden-ausreisepflichtige-personen-nicht-abgeschoben/', 'bund', 'Menschen, die ausreisen müssen, bleiben trotzdem hier'),
  (605, 6, 'Die EU-Zuständigkeitsregeln (Dublin) greifen kaum: 2025 wurde nur rund jede siebte von Deutschland beantragte Überstellung vollzogen', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1161094', 'bund', 'Wer in einem anderen EU-Land Asyl beantragt haben müsste, bleibt trotzdem hier'),
  (606, 6, 'Viele Menschen leben jahrelang nur geduldet: Rund 41 % der gut 180.000 Geduldeten sind seit mehr als fünf Jahren in Deutschland', 'https://mediendienst-integration.de/fluechtlinge/duldung/wie-viele-personen-haben-eine-duldung/', 'bund', 'Menschen leben jahrelang in Deutschland, ohne zu wissen, ob sie bleiben dürfen'),
  (701, 7, 'Immer weniger Beitragszahlende je Rentner: Nach geltendem Recht steigt der Beitrag bis 2039 auf 21,2 %, und das Rentenniveau sinkt auf 46,3 %', 'https://www.bundesregierung.de/breg-de/aktuelles/rentenbericht-2025-2394260', 'bund', 'Ich mache mir Sorgen, dass die Rente nicht reicht und die Beiträge steigen, weil auf einen Rentner immer weniger Beitragszahlende kommen'),
  (702, 7, 'Niedrige Löhne und Lücken im Erwerbsleben (z. B. Arbeitslosigkeit) führen zu niedrigen Rentenansprüchen', 'https://www.diw.de/sixcms/detail.php?id=diw_01.c.402060.de', 'bund', 'Ich werde nur eine kleine Rente bekommen, weil ich wenig verdiene oder nicht durchgehend gearbeitet habe'),
  (703, 7, 'Betriebliche und private Zusatzvorsorge erreicht Geringverdienende, Menschen mit Erwerbsunterbrechungen und Beschäftigte kleiner Betriebe deutlich seltener', 'https://www.diw.de/de/diw_01.c.1005367.de/publikationen/wochenberichte/2026_16_1/private_und_betriebliche_altersvorsoge_ist_zwischen_den_einkommensgruppen_ungleich_verbreitet.html', 'bund', 'Ich kann nicht zusätzlich privat für das Alter vorsorgen, weil mein Einkommen zu knapp ist oder es im Betrieb nichts gibt'),
  (801, 8, 'Rund 21 Millionen Menschen fehlt ein gutes Grundangebot an Bus und Bahn, besonders auf dem Land', 'https://www.agora-verkehrswende.de/aktuelles/oev-atlas-zeigt-grosse-unterschiede-beim-bus-und-bahnangebot', 'land', 'Bei mir fährt kaum ein Bus oder eine Bahn, ohne Auto komme ich nirgends hin'),
  (802, 8, 'Marodes, überaltertes Schienennetz; laut Bundesrechnungshof steuert der Bund seine Mittel für den Erhalt kaum wirksam', 'https://www.bundesrechnungshof.de/fileadmin/import/SharedDocs/Downloads/DE/Berichte/2025/evaluation-luf-3_volltext-evaluation-luf-3_volltext.pdf', 'bund', 'Meine Bahn ist unpünktlich oder fällt aus, weil Gleise und Technik marode sind'),
  (803, 8, 'Zu wenige Bus- und Straßenbahnfahrerinnen und -fahrer; in den nächsten zehn Jahren gehen rund vier von zehn Beschäftigten in Verkehrsberufen in den Ruhestand', 'https://www.kofa.de/daten-und-fakten/studien/fachkraeftereport-juni-2025/', 'land', 'Busse und Bahnen fahren nicht, weil Fahrerinnen und Fahrer fehlen'),
  (804, 8, 'Tickets werden teurer: Das Deutschlandticket kostet seit Januar 2026 63 Euro im Monat; den Preis legen die Länder fest, Bund und Länder zahlen je 1,5 Milliarden Euro im Jahr zu', 'https://www.bundesregierung.de/breg-de/aktuelles/deutschlandticket-2134074', 'land', 'Die Fahrkarten für Bus und Bahn werden immer teurer'),
  (901, 9, 'Nachts fühlen sich viele an bestimmten Orten unsicher: 2024 fühlten sich an Bahnhöfen nur 27 % und in Parks nur 23 % sicher', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'land', 'Nachts fühle ich mich an Bahnhöfen, in Parks oder auf dem Heimweg unsicher'),
  (902, 9, 'Viele Straftaten haben keine oder späte Folgen: 2025 blieben 42 % unaufgeklärt; Ende 2024 waren 950.900 Ermittlungsverfahren offen, so viele wie nie seit 2014', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/10/PD25_360_2421.html', 'land', 'Straftaten bleiben ohne Folgen: Die Polizei klärt sie nicht auf, oder es dauert ewig'),
  (903, 9, 'Junge Menschen werden häufiger Opfer von Gewalt: 2024 wurden 8,5 % der 16- und 17-Jährigen Opfer einer Körperverletzung (2020: 3,1 %); 2025 mehr tatverdächtige Kinder bei Gewaltdelikten', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'land', 'Ich mache mir Sorgen, weil Jugendliche immer öfter Gewalt erleben'),
  (904, 9, 'Gewalt in Partnerschaft und Familie auf Höchststand: 2024 rund 266.000 Opfer häuslicher Gewalt (+17,8 % in fünf Jahren), 70 % Frauen; Partnerschaftsgewalt wird zu weniger als 5 % angezeigt', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2025/Presse2025/251121_PM_BLB_HG_StraftatengegenFrauen2024.html', 'land', 'Ich erlebe oder kenne jemanden, der in der Partnerschaft oder Familie Gewalt erlebt'),
  (905, 9, 'Nichtdeutsche sind bei Gewaltdelikten als Tatverdächtige überrepräsentiert (2025: 42,9 %); Gründe laut Forschung: Alter, Geschlecht, Wohnort, Aufenthaltsperspektive, Zuzug 2015/16 – Gewicht umstritten', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'bund', 'Ich frage mich, warum bei Gewalttaten so viele Tatverdächtige keinen deutschen Pass haben'),
  (906, 9, 'Betrug und Datenmissbrauch im Internet treffen viele und werden selten angezeigt: 2023 war fast jede fünfte Person betroffen; 2025 kamen zwei Drittel der Fälle aus dem Ausland oder von unbekanntem Ort', 'https://skid.bka.de/Wichtige_Ergebnisse.html', 'bund', 'Ich bin im Internet betrogen worden oder meine Daten wurden missbraucht'),
  (907, 9, 'Politisch und religiös motivierte Kriminalität auf Höchststand: 2025 rund 85.800 Straftaten, so viele wie nie, darunter rund 4.200 Gewaltdelikte', 'https://www.bka.de/DE/UnsereAufgaben/Deliktsbereiche/PMK/PMKZahlen/PMKZahlen_node.html', 'bund', 'Ich mache mir Sorgen wegen politisch oder religiös motivierter Gewalt'),
  (908, 9, 'Sexualisierte Gewalt: Die Polizei erfasst deutlich mehr Vergewaltigungen (2025: +9,0 %, seit 2018 rund +72 %), angezeigt werden aber nur rund 6 %', 'https://www.bka.de/DE/Presse/Listenseite_Pressemitteilungen/2026/Presse2026/260420_PM_PKS_SKiD.html', 'land', 'Ich habe Angst vor sexualisierter Gewalt oder habe sie selbst erlebt'),
  (909, 9, 'Zugewanderte werden stärker mit Kriminalität verbunden, als es die Daten zeigen: Nennen Fernsehen und Zeitungen bei Gewalttaten die Herkunft, geht es zu über 90 % um ausländische Tatverdächtige (2025)', 'https://mediendienst-integration.de/news/auslaendische-tatverdaechtige-in-deutschen-leitmedien-ueberrepraesentiert/', 'land', 'Ich habe den Eindruck, dass Zugewanderte in den Medien stärker mit Kriminalität verbunden werden, als es stimmt'),
  (911, 9, 'Unbehandelte schwere psychische Erkrankungen und Suchterkrankungen erhöhen das Risiko für Gewalttaten, besonders zusammen; die meisten Gewalttaten gehen aber nicht darauf zurück', 'https://journals.plos.org/plosmedicine/article?id=10.1371/journal.pmed.1000120', 'bund', 'Ich habe Angst vor Gewalt durch Menschen mit schweren psychischen Erkrankungen oder Suchtproblemen, die keine Hilfe bekommen'),
  (1001, 10, 'Zu wenige Pflegekräfte; bis 2049 fehlen je nach Szenario 280.000 bis 690.000', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2024/01/PD24_033_23_12.html', 'bund', 'In der Pflege fehlen Leute, und es bleibt zu wenig Zeit für die Menschen'),
  (1002, 10, 'Steigende Eigenanteile im Heim für Pflege, Ausbildung, Unterkunft und Verpflegung (mit Investitionskosten im ersten Jahr im Schnitt 3.364 Euro im Monat)', 'https://www.vdek.com/presse/pressemitteilungen/2026/stationaere-pflege-eigenanteile-juli-2026.html', 'bund', 'Der Eigenanteil fürs Pflegeheim ist so hoch, dass wir ihn kaum bezahlen können'),
  (1003, 10, 'Die Zahl der Pflegebedürftigen steigt stärker als durch die Alterung allein, auch wegen des 2017 weiter gefassten Pflegebedürftigkeitsbegriffs', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2024/12/PD24_478_224.html', 'bund', 'Es gibt immer mehr Pflegebedürftige, und ich weiß nicht, wie das bezahlt und geleistet werden soll'),
  (1004, 10, 'Pflegende Angehörige tragen die Hauptlast; Entlastungsangebote werden wenig genutzt', 'https://www.zqp.de/thema/entlastung-pflegende/', 'bund', 'Ich pflege einen Angehörigen zu Hause und bin am Limit, Entlastung kommt bei mir nicht an'),
  (1005, 10, 'Die Länder fördern die Investitionskosten der Heime kaum; Bewohner zahlen dafür im Schnitt über 500 Euro im Monat', 'https://www.iges.com/kunden/gesundheit/forschungsergebnisse/2024/investitionskosten-von-pflegeeinrichtungen/index_ger.html', 'land', 'Im Pflegeheim zahle ich über 500 Euro im Monat allein für Gebäude und Ausstattung'),
  (1101, 11, 'Lebensmittelpreise hängen stark an den Energiekosten in Landwirtschaft, Transport, Lagerung und Dünger; nach dem Preisschub ab 2021 steigen sie mit dem Energiepreisschock 2026 voraussichtlich erneut', 'https://publikationen.bundesbank.de/publikationen-de/berichte-studien/monatsberichte/monatsbericht-juni-2026-998608?article=deutschland-prognose-energiepreisschock-treibt-teuerung-an-und-bremst-die-konjunkturerholung-998836', 'bund', 'Lebensmittel werden teurer, weil Energie, Transport und Dünger teurer werden'),
  (1102, 11, 'Der Lebensmittelhandel ist stark konzentriert: Vier Handelsgruppen haben rund 87 % des Umsatzes, und die Preisaufschläge in der Lieferkette sind zeitgleich mit der Konzentration gestiegen', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Sondergutachten/Monopolkommission-Sondergutachten-84-2025-Wettbewerb-in-der-Lebensmittellieferkette.pdf#page=12', 'bund', 'Im Supermarkt zahle ich hohe Preise, und mir scheint, es gibt zu wenig Wettbewerb unter den Handelsketten'),
  (1103, 11, 'Die Löhne hielten mit den Preisen lange nicht mit: Die Reallöhne sanken von 2020 bis 2023 und erreichten 2025 erst wieder fast das Niveau von 2019', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/02/PD26_068_62321.html', 'bund', 'Mein Lohn ist seit Jahren kaum gestiegen, die Preise aber schon'),
  (1104, 11, 'Hohe Steuern und Sozialabgaben auf Arbeit: Bei einem alleinstehenden Durchschnittsverdiener gehen 49,3 % der Arbeitskosten an Staat und Sozialversicherung, der zweithöchste Wert in der OECD (2025)', 'https://www.oecd.org/content/dam/oecd/en/publications/reports/2026/04/taxing-wages-2026-country-notes_491a0e97/germany_649f0784/ca03c391-en.pdf', 'bund', 'Von meinem Bruttolohn bleibt mir wegen Steuern und Sozialabgaben zu wenig übrig'),
  (1105, 11, 'Rund 6,3 Millionen Jobs (16 %) liegen im Niedriglohnbereich, vor allem in Gastgewerbe, Landwirtschaft und Kultur (April 2025)', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/12/PD25_434_623.html', 'bund', 'Ich verdiene so wenig, dass ich mir den täglichen Bedarf kaum leisten kann'),
  (1201, 12, 'Viele Autobahnbrücken sind marode, ihre Modernisierung liegt weit hinter dem Plan: Bis Ende 2024 war nur 40 % des Vorgesehenen geschafft; der Autobahn GmbH fehlen Personal und Mittel', 'https://www.bundesrechnungshof.de/SharedDocs/Kurzmeldungen/DE/2025/brueckenmodernisierung/kurzmeldung.html', 'bund', 'Ich stehe im Stau, weil Autobahnbrücken gesperrt oder Baustellen ewig nicht fertig sind'),
  (1202, 12, 'Die Kommunen schieben bei Straßen und Verkehrswegen einen Sanierungsstau von rund 54 Mrd. Euro vor sich her', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land', 'Die Straßen und Wege in meiner Stadt oder Gemeinde sind voller Schlaglöcher'),
  (1203, 12, 'Bauvorhaben kommen schleppend voran: Kommunen setzen nur rund zwei Drittel ihrer geplanten Investitionen um; es fehlt Personal, Genehmigung und Vergabe sind aufwendig', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land', 'Bauarbeiten an Straßen und Wegen in meiner Stadt oder Gemeinde ziehen sich ewig hin'),
  (1204, 12, 'Radfahren ist gefährlicher geworden: 2025 starben 462 Radfahrende, 20,6 % mehr als 2015, vor allem Ältere auf Pedelecs; Unfallgegner ist meist ein Auto', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/04/PD26_N025_461.html', 'land', 'Ich fühle mich beim Radfahren im Verkehr nicht sicher'),
  (1301, 13, 'Glasfaser reicht erst zu rund 43 % der Haushalte (2025); wo sich der Ausbau nicht lohnt, vor allem auf dem Land, braucht es Förderung, die teuer ist und privaten Ausbau teils verdrängt', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'bund', 'Bei mir zu Hause ist das Internet langsam, und Glasfaser gibt es nicht'),
  (1302, 13, 'Rund 2 % der Fläche haben gar keinen Mobilfunk mit 4G oder 5G, vor allem in Wäldern, Höhenlagen, Schutz- und Grenzgebieten', 'https://bmds.bund.de/aktuelles/pressemitteilungen/detail/mobilfunkversorgung-uebersicht-zu-weissen-flecken', 'bund', 'Unterwegs oder bei uns auf dem Land habe ich kein Netz'),
  (1401, 14, 'Online-Angebote der Verwaltung sind schwer zu finden und oft nicht durchgängig digital: Digitale Anträge werden nicht schneller bearbeitet, nur 15 % sehen ihre Erwartungen erfüllt (2025)', 'https://initiatived21.de/presse/egovernment-monitor-2025-wie-die-digitale-verwaltung-helfen-kann-staatsvertrauen-zurueckzugewinnen', 'land', 'Ich finde Anträge im Netz nicht, oder sie müssen am Ende doch wieder auf Papier eingereicht werden'),
  (1402, 14, 'Der Verwaltung fehlt Personal: Bis 2030 geht fast ein Drittel der Beschäftigten im öffentlichen Dienst in den Ruhestand', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=35', 'land', 'Ich warte ewig auf einen Termin oder auf meinen Bescheid, weil beim Amt Personal fehlt'),
  (1403, 14, 'Behörden tauschen Daten kaum aus: Register sind nicht vernetzt, Menschen müssen dieselben Angaben und Nachweise immer wieder einreichen', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=55', 'bund', 'Ich muss dieselben Angaben und Nachweise bei jeder Behörde neu einreichen'),
  (1404, 14, 'Die Verwaltung ist mit Aufgaben und kleinteiligen Vorschriften überladen: Die Kommunen beklagen einen ungebremsten Aufgabenanstieg und zu viele Detailvorschriften', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5#page=49', 'bund', 'Beim Amt gibt es so viele Vorschriften und Formulare, dass alles kompliziert und langsam ist'),
  (1501, 15, 'Der Spritpreis hängt am Weltmarkt für Rohöl: Mit dem Krieg im Iran und der zeitweisen Sperrung der Straße von Hormus stiegen die Preise 2026 binnen Wochen teils um mehr als ein Drittel', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=2', 'bund', 'Der Sprit ist plötzlich viel teurer geworden'),
  (1502, 15, 'Steuern und Abgaben machen einen großen Teil des Spritpreises aus: Energiesteuer (65,45 Cent je Liter Benzin, 47,04 Cent Diesel), CO₂-Preis und Mehrwertsteuer', 'https://www.bundestag.de/resource/blob/834634/dfae7d2604f66510d0469c84eee9e6b5/WD-4-030-21-pdf-data.pdf', 'bund', 'Auf Benzin und Diesel liegen so viele Steuern und Abgaben, dass Tanken sehr teuer ist'),
  (1503, 15, 'Wenig Wettbewerb bei Raffinerien und Großhandel: Preissenkungen kommen nicht vollständig an der Zapfsäule an, in Deutschland stiegen die Preise 2026 besonders stark', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'bund', 'Ich habe den Eindruck, dass sinkende Rohölpreise an der Zapfsäule kaum ankommen'),
  (1504, 15, 'Elektroautos sind für viele noch zu teuer: Gut die Hälfte der Haushalte ohne Elektroauto nennt den Preis als Hindernis (2026: 52 %)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=23', 'bund', 'Ein Elektroauto ist mir zu teuer'),
  (1505, 15, 'Wer in einem Mehrparteienhaus wohnt, kann oft nicht zu Hause laden: Die rund 9 Millionen Stellplätze an 21 Millionen Wohnungen sind bisher nur unzureichend mit Lademöglichkeiten ausgestattet', 'https://www.bmv.de/SharedDocs/DE/Pressemitteilungen/2026/021-schnieder-500-millionen-foerderung-ladeinfrastruktur-mehrfamilienhaeuser.html', 'bund', 'Ich wohne zur Miete im Mehrfamilienhaus und kann mein Elektroauto zu Hause nicht laden'),
  (1601, 16, 'Viele halten den Umstieg für nicht lohnend oder können ihn nicht bezahlen: 43 % der Interessierten zweifeln an der Wirtschaftlichkeit einer Wärmepumpe, 32 % fehlt das Geld (2026)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=19', 'bund', 'Ein Heizungstausch lohnt sich für mich nicht oder ich kann ihn nicht bezahlen'),
  (1602, 16, 'Die Regeln für neue Heizungen wurden in wenigen Jahren mehrfach grundlegend geändert (zuletzt Gebäudemodernisierungsgesetz, Juli 2026), dazu kommt ab 2028 ein europäischer CO₂-Preis für Heizöl und Gas', 'https://www.bundesregierung.de/breg-de/aktuelles/neues-gebaeudemodernisierungsgesetz-2430284', 'bund', 'Ich weiß nicht, welche Heizung ich einbauen darf, weil sich die Regeln ständig ändern'),
  (1603, 16, 'Viele wissen noch nicht, ob Fernwärme oder ein Wärmenetz kommt: Erst 26 % der Gemeinden haben ihre Wärmeplanung abgeschlossen (Juni 2026)', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'land', 'Ich weiß nicht, ob in meiner Gemeinde Fernwärme kommt, und kann deshalb nicht planen'),
  (1604, 16, 'Mieterinnen und Mieter können über die Heizung nicht entscheiden, tragen aber die Heizkosten: Sie nutzen fast viermal seltener klimafreundliche Technik als Eigenheimbesitzer (15 % zu 59 %)', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf#page=5', 'bund', 'Als Mieter kann ich über die Heizung nicht entscheiden, zahle aber die Heizkosten'),
  (1701, 17, 'Der Betreuungsbedarf der Eltern übersteigt das Angebot bei unter Dreijährigen: 2025 wünschten 49,3 % einen Platz, 37,8 % nutzten ein Angebot (Lücke im Westen 12,7, im Osten 5,8 Prozentpunkte)', 'https://www.akjstat.tu-dortmund.de/themen/kindertagesbetreuung-bis-zum-schuleintritt/weiterhin-ungedeckte-platzbedarfe-kindertagesbetreuung-kompakt-ausbaustand-und-bedarf-2025-erschienen', 'land', 'Ich finde für mein Kind unter drei Jahren keinen Kitaplatz'),
  (1702, 17, 'Das Personal reicht oft nicht für die Kinderzahl: Mehr als jede zweite Kita-Leitung befürchtet, dass Personalmangel gute Betreuung erschwert, fast 80 % nennen Fehlzeiten als Einschränkung (2024)', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1677-gut-ausgebildet-und-gestresst.html', 'land', 'In der Kita meines Kindes sind zu wenige Erzieherinnen und Erzieher für die Kinder da'),
  (1703, 17, 'Der Personalschlüssel liegt oft unter wissenschaftlichen Empfehlungen: 2022 wurden in Ostdeutschland fast 90 % der Kita-Kinder in nicht kindgerecht besetzten Gruppen betreut (Westen: 62 %)', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2023/november/mehr-plaetze-und-bessere-qualitaet-in-kitas-bis-2030-wenn-jetzt-entschlossen-gehandelt-wird', 'land', 'In der Kita meines Kindes betreut eine Erzieherin zu viele Kinder auf einmal'),
  (1704, 17, 'Kitas schließen immer wieder ungeplant: 2023/24 erlebten 43 % der Familien mit Kita-Kindern unerwartete Schließtage, bei rund 13 % summierten sie sich auf mehr als eine Woche im Kita-Jahr', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1730-unerwartete-kita-schliessungen-gehen-mit-verstaerkten-zweifeln-an-der-qualitaet-einher.html', 'land', 'Die Kita meines Kindes schließt immer wieder kurzfristig, und ich muss Betreuung organisieren'),
  (1705, 17, 'Viele Eltern sehen bei den Kosten Verbesserungsbedarf: Bei unter Dreijährigen nennen 37 % „viel Bedarf“ bei den Elternbeiträgen, bei Älteren 24 % (Erhebung 2022)', 'https://doi.org/10.36189/DJI202606', 'land', 'Die Kita-Gebühren sind für mich zu hoch'),
  (1801, 18, 'Hitze nimmt zu: Die Zahl der Heißen Tage (mindestens 30 °C) hat sich im Mittel über Deutschland seit den 1950er-Jahren von etwa 4 auf durchschnittlich 12 pro Jahr verdreifacht', 'https://www.dwd.de/DE/klimaumwelt/klimawandel/klimawandel_node.html', 'bund', 'Es wird immer heißer, und ich komme mit der Hitze schlecht zurecht'),
  (1802, 18, 'Hitze fordert Todesopfer: Das RKI schätzt für die Sommer 2023 und 2024 jeweils rund 3.000 hitzebedingte Sterbefälle, vor allem bei Menschen über 75 Jahren', 'https://edoc.rki.de/handle/176904/12682', 'bund', 'Ich mache mir Sorgen, weil Hitze für ältere Menschen gefährlich ist'),
