  (3302, 33, 'Bildschirmnutzung zur Schlafenszeit hängt mit zu wenig Schlaf und Tagesmüdigkeit zusammen (Metaanalyse 2016, 20 Studien, 125.198 Kinder und Jugendliche)', 'https://europepmc.org/articles/PMC5380441', 'land', 'Mein Kind sitzt nachts am Handy und ist tagsüber müde'),
  (3303, 33, 'Eltern fällt die Begleitung der Mediennutzung schwer: Für 57,6 % war die passende tägliche Nutzungsdauer zumindest manchmal eine Sorge (niederländische Befragung 2015, Kinder 1 bis 9 Jahre)', 'https://www.ebi.ac.uk/europepmc/webservices/rest/PMC5932097/fullTextXML', 'land', 'Ich weiß nicht, wie viel Bildschirmzeit für mein Kind in Ordnung ist'),
  (3401, 34, 'Häufige Polizeikontrollen können Jugendliche psychisch belasten: In einer US-Längsschnittstudie (2013 bis 2015, 645 Jungen) hing die Zahl der Kontrollen mit späterer Belastung zusammen', 'https://europepmc.org/articles/PMC6486703', 'land', 'Ich werde als Jugendlicher ständig kontrolliert, und das belastet mich'),
  (3402, 34, 'Respektloses Verhalten bei Polizeikontakten ließ sich in einem US-Experiment (2017 bis 2020, 120 Orte) durch eine veränderte Einsatzpraxis beeinflussen', 'https://europepmc.org/articles/PMC9168920', 'land', 'Bei der Kontrolle wurde ich nicht angehört und nicht respektvoll behandelt'),
  (3403, 34, 'Verfahren wegen mutmaßlich übermäßiger Polizeigewalt werden von Staatsanwaltschaften häufig mangels hinreichenden Tatverdachts eingestellt (Fachbeitrag, 2019)', 'https://www.kriminologie.de/index.php/krimoj/article/view/25', 'land', 'Ich wurde bei einer Kontrolle unangemessen behandelt, aber eine Anzeige bringt nichts'),
  (3501, 35, 'Fahrschule und Führerscheingebühr wurden 2024 durchschnittlich um 5,8 % teurer als im Vorjahr; die Verbraucherpreise insgesamt stiegen um 2,2 %', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/Zahl-der-Woche/2025/PD25_15_p002.html?view=renderPrint', 'bund', 'Der Führerschein ist so teuer, dass ich ihn mir kaum leisten kann'),
  (3502, 35, 'Nicht bestandene Prüfungen führen zu Wiederholungskosten: 2025 wurden 828.324 von 2.042.050 theoretischen und 577.858 von 1.886.133 praktischen Prüfungen nicht bestanden', 'https://www.kba.de/DE/Statistik/Kraftfahrer/Fahrerlaubnisse/Fahrerlaubnispruefungen/fahrerlaubnispruefungen_node.html', 'bund', 'Ich bin durch die Prüfung gefallen und muss sie teuer wiederholen'),
  (3601, 36, 'Der zunehmende Onlinehandel wirkt sich laut BBSR-Projekt (2021 bis 2024) negativ auf den Geschäftsbesatz in den Zentren aus', 'https://www.bbsr.bund.de/BBSR/DE/forschung/programme/exwost/Studien/2021/innenstadt-online-handel/01-start.html', 'bund', 'Die Geschäfte in unserer Innenstadt schließen, weil alle online bestellen'),
  (3602, 36, 'Einzigartigkeit des Sortiments und Atmosphäre eines Geschäfts hängen signifikant mit Schließungen zusammen (Daten 2015 bis 2020, Bekleidung und Medien; Studie 2024)', 'https://publikationen.bibliothek.kit.edu/1000175106', 'land', 'In der Innenstadt gibt es immer dieselben Läden, und ich gehe lieber woanders hin'),
  (3603, 36, '26 % der Befragten im Osten und 32 % im Westen sahen 2026 beim Stadtbild und Aufenthalt im öffentlichen Raum großen Handlungsbedarf (Befragung von 5.079 Personen)', 'https://cimamonitor.de/', 'land', 'Unsere Innenstadt ist ungepflegt und lädt nicht zum Bleiben ein'),
  (3604, 36, 'Eine zugängliche Lage und günstige Öffnungszeiten hängen mit weniger Geschäftsschließungen zusammen (Daten 2015 bis 2020, Bekleidung und Medien; Studie 2024)', 'https://publikationen.bibliothek.kit.edu/1000175106', 'land', 'Ich komme nur umständlich in die Innenstadt, oder die Läden haben zu, wenn ich Zeit habe'),
  (3701, 37, 'Der geschätzte Investitionsrückstand der Kommunen bei Sportstätten stieg im Kommunalpanel 2026 um 6,0 Milliarden Euro gegenüber dem Vorjahr', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land', 'Unsere Sporthalle ist marode oder gesperrt'),
  (3702, 37, 'Im Sportbereich mussten laut Kommunalpanel 2026 60 % der Kommunen mit eigenen Betrieben zuletzt Verluste ausgleichen (beim ÖPNV 52 %)', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_897920.html', 'land', 'Hallenmiete und Nutzungsgebühren steigen, und der Verein kann sie kaum noch bezahlen'),
  (3703, 37, 'Der Problemdruck der Vereine durch den Zustand der Sportstätten (+3,7 %) und ihre finanzielle Situation (+2,5 %) ist im Sportentwicklungsbericht 2023 bis 2025 gegenüber 2020 gestiegen', 'https://www.bisp.de/SharedDocs/Downloads/Publikationen/Publikationssuche_SEB/SEB_23-25.pdf?__blob=publicationFile&v=1#page=55', 'land', 'Unserem Verein fehlt das Geld, und die Sportstätten sind in schlechtem Zustand')
insert into public.haltungen (id, frage, beschreibung, verwandte_themen) values
  (1, 'Soll es ein generelles Tempolimit auf Autobahnen geben?', 'Ob auf allen Autobahnen eine feste Höchstgeschwindigkeit gelten soll oder ob Tempolimits wie bisher nur dort gelten, wo Verkehr, Unfälle oder Lärm es verlangen.', '{15,12}'),
  (2, 'Soll Zuwanderung nach Deutschland stärker begrenzt werden?', 'Ob insgesamt weniger Menschen nach Deutschland kommen sollen als bisher – über Asyl, Familiennachzug oder Arbeit –, unabhängig davon, mit welchen Mitteln das geschähe.', '{6,2,5,9}'),
  (3, 'Soll der Staat Eltern, die ihr kleines Kind zu Hause statt in einer Kita betreuen, finanziell unterstützen?', 'Ob Eltern von Kleinkindern, die keinen Betreuungsplatz nutzen, dafür eine eigene Geldleistung bekommen sollen – zusätzlich zu Elterngeld und Kindergeld, die alle Eltern erhalten.', '{17}'),
  (4, 'Soll Deutschland den Ausbau der Windkraft an Land weiter vorantreiben?', 'Ob Bund und Länder den Ausbau der Windkraft an Land weiter mit dem Ziel eines wachsenden Anteils im Strommix fördern sollen oder ob dieser Ausbau begrenzt oder beendet werden soll.', '{3}'),
  (5, 'Soll Deutschland wieder Atomkraftwerke zur Stromerzeugung betreiben?', 'Ob Deutschland die Kernenergie zur Stromerzeugung wieder nutzen soll, also neue Anlagen bauen oder stillgelegte reaktivieren, oder ob es beim Atomausstieg bleibt.', '{3}'),
  (6, 'Soll Gendersprache in Behörden und Schulen verboten werden?', 'Ob staatliche Stellen und Schulen geschlechtergerechte Formen wie Genderstern, Doppelpunkt oder Doppelnennung per Verbot ausschließen sollen oder ob sie weiter frei oder nach eigenen Regeln gendern dürfen.', '{4}'),
  (7, 'Soll Deutschland die Ukraine weiter mit Waffen beliefern?', 'Ob Deutschland der Ukraine im Krieg gegen Russland weiter Waffen und Rüstungsgüter liefern oder finanzieren soll oder ob es diese Lieferungen beendet oder nicht mehr ausbaut.', '{3}'),
  (8, 'Soll der gemeinsame Unterricht von Kindern mit und ohne Behinderung an Regelschulen Vorrang vor Förderschulen haben?', 'Ob Kinder mit sonderpädagogischem Förderbedarf in der Regel gemeinsam mit anderen Kindern an allgemeinen Schulen lernen sollen oder ob Förderschulen als gleichwertiger Weg bestehen bleiben.', '{4}'),
  (9, 'Sollen die Düngeregeln für Landwirtschaftsbetriebe gelockert werden?', 'Ob die Vorgaben der Düngeverordnung für Landwirtschaftsbetriebe (etwa Mengengrenzen, Auflagen in nitratbelasteten Gebieten, Dokumentationspflichten) abgeschwächt werden sollen oder ob sie in ihrer jetzigen Form oder strenger bleiben.', '{11}'),
  (10, 'Soll eine Vermögensteuer eingeführt werden?', 'Ob große private Vermögen jährlich besteuert werden sollen, oder ob es bei der heutigen Besteuerung ohne laufende Vermögensteuer bleibt.', '{11}'),
  (11, 'Soll es in Deutschland einen verpflichtenden Wehrdienst für junge Menschen geben?', 'Ob junge Menschen in Deutschland zum Wehrdienst verpflichtet werden sollen oder ob die Bundeswehr ihr Personal allein über freiwillige Meldungen gewinnt.', '{9}'),
  (12, 'Soll es einen gesetzlichen Mindestlohn geben?', 'Ob der Staat eine Untergrenze für den Stundenlohn per Gesetz festlegt oder ob Löhne allein zwischen Arbeitgebern, Beschäftigten und Tarifparteien ausgehandelt werden.', '{11,5}'),
  (13, 'Soll die Schuldenbremse im Grundgesetz bestehen bleiben?', 'Ob die Kreditaufnahme des Staates weiter durch eine Schuldenregel im Grundgesetz begrenzt sein soll (auch in der 2025 gelockerten Form) oder ob die Regel abgeschafft oder durch eine großzügigere ersetzt werden soll.', '{5}'),
  (14, 'Soll das gesetzliche Renteneintrittsalter über 67 Jahre hinaus angehoben werden?', 'Ob die Regelaltersgrenze in der gesetzlichen Rente, die bis 2031 auf 67 Jahre steigt, weiter angehoben werden soll (etwa gekoppelt an die Lebenserwartung) oder ob sie bei 67 Jahren oder darunter bleiben soll.', '{7}'),
  (15, 'Soll es eine Steuer auf stark gezuckerte Getränke geben?', 'Ob der Staat Getränke mit hohem Zuckergehalt zusätzlich besteuern soll, um Konsum und Zuckeraufnahme zu senken, oder ob es bei den bisherigen Steuern und freiwilligen Maßnahmen bleibt.', '{1}'),
  (16, 'Soll Deutschland Mitglied der NATO bleiben?', 'Ob Deutschland im Nordatlantikbündnis bleibt oder aus dem Bündnis austritt und seine Sicherheit anders organisiert.', '{9}'),
  (17, 'Soll die Zahlung der historisch begründeten Staatsleistungen an die Kirchen beendet werden?', 'Ob die jährlichen Staatsleistungen der Länder an die Kirchen, die auf Ereignisse wie die Säkularisation von 1803 zurückgehen, durch eine Ablösung nach Art. 140 GG und Art. 138 WRV enden sollen oder ob sie bis auf Weiteres weiterlaufen (die Kirchensteuer ist nicht gemeint).', '{11}'),
  (18, 'Soll Deutschland wieder Erdgas aus Russland beziehen?', 'Ob Deutschland Erdgas aus Russland wieder importieren soll, etwa per Pipeline oder als Flüssigerdgas, oder ob es weiter darauf verzichtet und andere Lieferländer nutzt.', '{3}'),
  (19, 'Soll Deutschland den Euro als Währung behalten?', 'Ob Deutschland Mitglied der Währungsunion bleibt und weiter mit dem Euro zahlt oder ob es austritt und wieder eine eigene Währung einführt.', '{5}'),
  (20, 'Sollen Solaranlagen auf Ackerflächen gebaut werden dürfen?', 'Ob Freiflächen-Photovoltaik auf landwirtschaftlich genutzten Flächen wie Äckern zulässig sein soll oder ob solche Flächen der Landwirtschaft vorbehalten bleiben und Solaranlagen auf anderen Flächen gebaut werden.', '{3}'),
  (21, 'Soll es für gut integrierte Geduldete ein dauerhaftes Bleiberecht geben?', 'Ob Menschen mit Duldung, die gut integriert sind, nach festen Kriterien dauerhaft in Deutschland bleiben dürfen oder ob für sie weiter die Ausreisepflicht und nur befristete Einzelfallregeln gelten.', '{6}'),
  (22, 'Soll Kirchenasyl in Deutschland weiterhin möglich sein?', 'Ob Kirchengemeinden Menschen, denen die Abschiebung oder Überstellung droht, weiter zeitlich begrenzt aufnehmen können und die Behörden dies nach der Vereinbarung zwischen Kirchen und BAMF weiter hinnehmen, oder ob diese Praxis enden soll.', '{6}'),
  (23, 'Soll Eltern erlaubt werden, ihre Kinder zu Hause statt in der Schule zu unterrichten?', 'Ob Kinder in Deutschland wie bisher die Schule besuchen müssen oder ob Eltern sie stattdessen zu Hause unterrichten dürfen.', '{4}'),
  (24, 'Soll Deutschland Mitglied der EU bleiben?', 'Ob Deutschland weiter Mitglied der EU sein soll oder ob es austreten und seine Beziehungen zu den anderen Staaten neu regeln soll.', '{5}'),
  (25, 'Soll die Erbschaftsteuer abgeschafft werden?', 'Ob Erbschaften und Schenkungen in Deutschland weiter besteuert werden sollen oder ob die Erbschaft- und Schenkungsteuer ersatzlos entfällt.', '{11}'),
  (26, 'Soll ein Schwangerschaftsabbruch in den ersten zwölf Wochen nach Beratung rechtmäßig sein?', 'Ob ein Abbruch in den ersten zwölf Wochen nach Beratung rechtmäßig werden soll oder ob er wie bisher grundsätzlich rechtswidrig, aber unter Bedingungen straffrei bleibt (§§ 218, 218a StGB).', '{1}'),
  (27, 'Soll der Staat eine höhere Geburtenrate gezielt fördern?', 'Ob der Staat mit seiner Politik ausdrücklich das Ziel verfolgen soll, dass mehr Kinder geboren werden, oder ob er Familien nur unterstützt, ohne die Geburtenrate als Ziel zu setzen.', '{7,17}'),
  (28, 'Soll der vorübergehende Schutz für Geflüchtete aus der Ukraine enden, sobald die Sicherheitslage in ihrer Herkunftsregion es zulässt?', 'Ob der vorübergehende Schutz (EU-Richtlinie 2001/55/EG, § 24 AufenthG) für Menschen aus der Ukraine enden soll, sobald ihre Herkunftsregion als sicher gilt, oder ob ein Bleiberecht unabhängig von der Sicherheitslage möglich bleiben soll.', '{6}'),
  (29, 'Sollen Anwohner und Gemeinden über den Bau von Windrädern vor Ort verbindlich mitentscheiden?', 'Ob Anwohner und Gemeinden bei einzelnen Windrad-Projekten ein verbindliches Mitentscheidungsrecht bekommen, etwa über Bürgerentscheide oder ein Vetorecht, oder ob Land und Bund die Flächen weiter vorgeben und Betroffene nur angehört und beteiligt werden.', '{3}'),
  (30, 'Soll es Studiengebühren an staatlichen Hochschulen geben?', 'Ob Studierende an staatlichen Hochschulen für ihr Studium Gebühren zahlen sollen oder ob das Studium wie bisher gebührenfrei bleibt.', '{4}'),
  (31, 'Soll der Bund Projekte zur Demokratieförderung weiter finanziell fördern?', 'Ob der Bund Projekte, die Demokratie stärken und Extremismus vorbeugen (wie das Bundesprogramm „Demokratie leben!“), weiter aus Steuermitteln fördert oder diese Förderung beendet.', '{9}'),
  (32, 'Soll Deutschland seine Verteidigungsausgaben erhöhen?', 'Ob Deutschland mehr Geld für seine militärische Verteidigung bereitstellen soll oder nicht, wobei ein bloßer Inflationsausgleich nicht als Erhöhung zählt.', '{9}'),
  (33, 'Sollen Leistungen der Grundsicherung für Arbeitsuchende gekürzt werden, wenn zumutbare Arbeit ohne wichtigen Grund abgelehnt wird?', 'Ob die Ablehnung eines zumutbaren Arbeitsangebots ohne wichtigen Grund zu einer Leistungskürzung führen soll oder ob die Leistungen deswegen ungekürzt bleiben sollen.', '{5,11}'),
  (34, 'Sollen trockengelegte Moore wieder vernässt werden?', 'Es geht darum, ob entwässerte Moorflächen wieder höhere Wasserstände erhalten sollen oder ob ihre Entwässerung bestehen bleiben soll.', '{18}'),
  (35, 'Soll in Deutschland die kommerzielle Erdgasförderung durch unkonventionelles Fracking erlaubt werden?', 'Ob Erdgas aus Schiefer-, Mergel-, Ton- und Kohleflözgestein durch Fracking kommerziell gefördert werden darf oder das bestehende Verbot bestehen bleiben soll.', '{3}'),
  (36, 'Soll der Staat die Ansiedlung und den Ausbau von Rüstungsunternehmen in Deutschland fördern?', 'Ob Bund und Länder Rüstungsunternehmen gezielt unterstützen sollen, damit sie sich in Deutschland ansiedeln und ihre Produktion ausbauen, oder ob der Staat auf eine solche Förderung verzichten soll.', '{5}'),
  (37, 'Sollen in Deutschland weitreichende US-Raketen stationiert werden?', 'Ob in Deutschland landgestützte Raketen und Marschflugkörper der USA mit großer Reichweite (etwa Tomahawk, SM-6, Hyperschallwaffen) stationiert werden sollen oder ob Deutschland auf solche US-Waffen verzichtet.', '{9}'),
  (38, 'Soll Deutschland an der nuklearen Teilhabe der NATO festhalten?', 'Ob in Deutschland weiter US-Atomwaffen lagern, die im Ernstfall Flugzeuge der Bundeswehr einsetzen könnten, oder ob Deutschland aus diesem Teil der NATO-Abschreckung aussteigt.', '{9}'),
  (39, 'Sollen die Wirtschaftssanktionen gegen Russland gelockert werden?', 'Ob Deutschland und die EU die Handels- und Finanzsanktionen gegen Russland lockern oder aufheben sollen oder ob sie beibehalten bzw. verschärft werden.', '{3,5}'),
  (40, 'Soll an staatlichen Hochschulen auch für militärische Zwecke geforscht werden dürfen?', 'Ob staatliche Hochschulen auch für militärische Zwecke forschen und dafür etwa mit der Bundeswehr zusammenarbeiten dürfen oder ob sie sich durch eine Zivilklausel auf zivile Forschung beschränken sollen.', '{31}'),
  (41, 'Soll Deutschland bis spätestens 2045 klimaneutral werden?', 'Es geht darum, ob Deutschland am gesetzlichen Ziel festhält, bis 2045 netto keine Treibhausgase mehr auszustoßen, oder ob es das Ziel verschiebt, etwa auf das EU-Ziel 2050, oder ganz aufgibt.', '{3,18}'),
  (42, 'Soll der gesetzlich beschlossene Ausstieg aus der Kohleverstromung aufgehoben oder zeitlich verschoben werden?', 'Ob Kohlekraftwerke über die gesetzlichen Fristen hinaus Strom erzeugen dürfen oder ob Deutschland den Ausstieg wie beschlossen bis spätestens 2038 umsetzt oder ihn sogar vorzieht.', '{3,5,24}'),
  (43, 'Soll der Staat beim Bundesverfassungsgericht das Verbot von Parteien beantragen, die er für verfassungsfeindlich hält?', 'Es geht darum, ob Bundestag, Bundesrat oder Bundesregierung gegen Parteien, die sie für verfassungsfeindlich halten, ein Verbot nach Art. 21 Abs. 2 GG beantragen sollen oder ob sie auf solche Anträge verzichten und die Auseinandersetzung politisch führen.', '{22}'),
  (44, 'Soll die Fünf-Prozent-Hürde bei Bundestagswahlen beibehalten werden?', 'Es geht darum, ob bei Bundestagswahlen weiter nur Parteien mit mindestens fünf Prozent der Zweitstimmen Sitze erhalten oder ob diese Sperrklausel gesenkt, abgemildert oder abgeschafft wird.', '{22}'),
  (45, 'Soll das Wahlalter für Bundestagswahlen auf 16 Jahre gesenkt werden?', 'Ob Jugendliche schon ab 16 Jahren den Bundestag mitwählen dürfen oder ob das Wahlrecht für Bundestagswahlen weiter erst ab 18 Jahren gilt.', '{22,20}'),
  (46, 'Sollen arbeitsfähige Menschen ohne Arbeit, die Grundsicherung beziehen, grundsätzlich zu gemeinnütziger Arbeit verpflichtet werden?', 'Ob arbeitsfähige Leistungsbeziehende ohne Arbeit in der Regel gemeinnützige Arbeit leisten müssen oder ob solche Arbeit wie bisher nur im Einzelfall und nachrangig vom Jobcenter zugewiesen wird.', '{5,21}'),
  (47, 'Soll die Polizei große Datenmengen mit Software automatisiert auswerten dürfen?', 'Ob die Polizei ihre gespeicherten Daten aus verschiedenen Quellen mit Software, auch mit KI, automatisiert zusammenführen und auswerten darf oder ob sie bei der Einzelabfrage und der Auswertung von Hand bleibt.', '{9}'),
  (48, 'Sollen Kinder länger gemeinsam lernen und erst später als heute auf verschiedene Schulformen aufgeteilt werden?', 'Ob alle Kinder über die Grundschule hinaus länger in derselben Schule lernen sollen, etwa in einer sechsjährigen Grundschule oder einer Gemeinschaftsschule bis Klasse 10, oder ob sie wie bisher meist nach Klasse 4 auf Gymnasium und andere Schulformen aufgeteilt werden.', '{4}'),
  (49, 'Soll sexuelle und geschlechtliche Vielfalt im Schulunterricht behandelt werden?', 'Ob Schulen verschiedene sexuelle Orientierungen und Geschlechtsidentitäten zum Unterrichtsinhalt machen sollen oder ob dieses Thema in der Schule zurücktreten und vor allem den Eltern überlassen bleiben soll.', '{4,19}'),
  (50, 'Soll innerorts auf mehr Straßen Tempo 30 statt Tempo 50 gelten?', 'Ob Tempo 30 in Städten und Dörfern auf mehr Straßen gelten soll, bis hin zur Regelgeschwindigkeit, oder ob 50 km/h die Regel bleibt und Tempo 30 auf Zonen und besondere Stellen beschränkt ist.', '{12,9}'),
  (51, 'Sollen die gesetzlichen Vorgaben für die Haltung von Nutztieren in der Landwirtschaft gelockert werden?', 'Ob Betriebe mit Nutztieren weniger Vorgaben zu Ställen, Haltungsform, Kennzeichnung und Nachweisen erfüllen müssen oder ob diese Vorgaben bleiben oder strenger werden. Düngeregeln gehören nicht dazu.', '{11}'),
  (52, 'Soll die Masern-Impfpflicht für Kinder in Kita und Schule beibehalten werden?', 'Es geht darum, ob Kinder in Kita, Kindertagespflege und Schule weiter einen Masernschutz nachweisen müssen oder ob die Masernimpfung wieder freiwillig wird.', '{17}'),
  (53, 'Soll der öffentlich-rechtliche Rundfunk weiterhin über den Rundfunkbeitrag finanziert werden?', 'Ob ARD, ZDF und Deutschlandradio weiter über einen Pflichtbeitrag je Wohnung finanziert werden sollen oder ob dieser Beitrag wegfallen soll, etwa zugunsten von Steuermitteln, freiwilligen Bezahlmodellen oder eines kleineren beziehungsweise gar keinen öffentlich-rechtlichen Angebots.', '{11}')
insert into public.haltung_zielkonflikte (haltung_id, seite, text, quelle_url) values
  (1, 'ja', 'Wer ein Tempolimit will, nennt weniger schwere Unfälle: Mit Tempo 120 gab es auf Autobahnabschnitten gut ein Drittel weniger Unfälle mit Toten.', 'https://doi.org/10.1016/j.tra.2025.104616'),
  (1, 'ja', 'Wer ein Tempolimit will, nennt außerdem den Klimaschutz: Tempo 120 auf Autobahnen spart nach Berechnungen des Umweltbundesamts jährlich rund 6,7 Millionen Tonnen Treibhausgase.', 'https://www.umweltbundesamt.de/themen/tempolimits-koennten-mehr-treibhausgase-sparen-als'),
  (1, 'nein', 'Wer es ablehnt, nennt längere Fahrzeiten: Auf Abschnitten ohne Limit fuhren rund drei von zehn Fahrzeugen schneller als 130 km/h.', 'https://doi.org/10.1515/pwp-2021-0023'),
  (1, 'nein', 'Wer es ablehnt, will Tempolimits nur dort, wo Verkehr, Unfälle oder Lärm sie verlangen – so gilt es heute auf knapp drei von zehn Kilometern Autobahn.', 'https://www.bast.de/DE/Publikationen/BerichteBASt/Fachveroeffentlichungen/Verkehrstechnik/Downloads/V1-BAB-Tempolimit-2015.pdf?__blob=publicationFile&v=1'),
  (2, 'ja', 'Wer Zuwanderung stärker begrenzen will, nennt die Belastung der Kommunen: Die Unterbringung bleibt für die meisten herausfordernd, Ausländerbehörden sind besonders stark belastet.', 'https://mediendienst-integration.de/fileadmin/Dateien/EXPERTISE_FLUECHTLINGSAUFNAHME_IN_DEN_KOMMUNEN_MEDIENDIENST_INTEGRATION_NOV_2025_FINAL.pdf'),
  (2, 'ja', 'Wer Zuwanderung stärker begrenzen will, nennt außerdem den Wohnungsmarkt: In Großstädten wächst die Nachfrage vor allem durch Zuwanderung.', 'https://www.iwkoeln.de/fileadmin/user_upload/Studien/Report/PDF/2026/IW-Report_2026-Migration-und-Wohnungsmarkt.pdf'),
  (2, 'nein', 'Wer das ablehnt, nennt den Bedarf an Arbeitskräften: Ohne Zuwanderung sänke das Arbeitskräfteangebot bis 2060 um 16 Millionen, gleich bliebe es nur mit netto rund 400.000 Zuwandernden im Jahr.', 'https://doku.iab.de/kurzber/2021/kb2021-25.pdf'),
  (2, 'nein', 'Wer das ablehnt, nennt außerdem den Schutz politisch Verfolgter, den das Grundgesetz als Recht auf Asyl garantiert.', 'https://www.gesetze-im-internet.de/gg/art_16a.html'),
  (3, 'ja', 'Wer das will, nennt die Wahlfreiheit der Eltern: Rund die Hälfte der Eltern von unter Dreijährigen wünscht sich keinen Betreuungsplatz.', 'https://www.akjstat.tu-dortmund.de/themen/kindertagesbetreuung-bis-zum-schuleintritt/weiterhin-ungedeckte-platzbedarfe-kindertagesbetreuung-kompakt-ausbaustand-und-bedarf-2025-erschienen'),
  (3, 'nein', 'Wer das ablehnt, nennt frühe Förderung in der Kita: Mit einem Betreuungsgeld in Thüringen gingen Zweijährige um 8 Prozentpunkte seltener in die Kita.', 'https://docs.iza.org/dp10813.pdf'),
  (4, 'ja', 'Wer den Ausbau vorantreiben will, nennt Stromversorgung und Klimaziele: Das gesetzliche Ziel von 115 Gigawatt bis 2030 erfordert laut Bundesnetzagentur im Schnitt 9,4 Gigawatt Zubau pro Jahr; 2025 waren es 4,6 Gigawatt.', 'https://www.bundesnetzagentur.de/SharedDocs/Pressemitteilungen/DE/2026/20260108_EEG.html'),
  (4, 'nein', 'Wer den Ausbau begrenzen oder stoppen will, nennt die Netzkosten: Die Kosten für das Netzengpassmanagement stiegen laut Bundesnetzagentur (SMARD) im dritten Quartal 2025 auf rund 667 Mio. Euro (Vorjahresquartal: 608 Mio. Euro).', 'https://www.smard.de/page/home/topic-article/444/219200/volumen-und-kosten-gestiegen'),
  (5, 'ja', 'Wer Atomkraftwerke wieder betreiben will, nennt die geringen Treibhausgasemissionen der Kernenergie: Das Umweltbundesamt beziffert sie über den gesamten Lebenszyklus auf 5 bis 15 Gramm CO₂-Äquivalente je Kilowattstunde.', 'https://www.umweltbundesamt.de/themen/klima-energie/energieversorgung/kernenergie'),
  (5, 'ja', 'Wer Atomkraftwerke wieder betreiben will, nennt außerdem die Versorgungssicherheit und den Gasverbrauch: 2025 stieg die Stromerzeugung aus Erdgas um 10,2 % auf 70,6 Milliarden Kilowattstunden, ein Höchstwert.', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/03/PD26_073_43312.html'),
  (5, 'nein', 'Wer die Rückkehr zur Atomkraft ablehnt, nennt die Kosten: Laut Umweltbundesamt kostete Strom aus neuen Kernkraftwerken in Europa 2020 etwa 15,0 bis 19,2 Cent je Kilowattstunde, Onshore-Wind 3,6 Cent und Solar 5,3 Cent; das Amt nennt zudem Bauzeiten von etwa acht Jahren.', 'https://www.umweltbundesamt.de/themen/klima-energie/energieversorgung/kernenergie'),
  (6, 'ja', 'Wer ein Verbot will, nennt einheitliche Regeln und Rechtssicherheit: Der Rat für deutsche Rechtschreibung zählt Wortbinnenzeichen nicht zum Kernbestand der Orthografie und verlangt von Texten, dass sie verständlich, vorlesbar und in der Verwaltung rechtssicher sind (Stellungnahme 2023).', 'https://www.rechtschreibrat.com/geschlechtergerechte-schreibung-erlaeuterungen-begruendung-und-kriterien-vom-15-12-2023/'),
  (6, 'nein', 'Wer ein Verbot ablehnt, nennt die Wirkung der Sprache auf Kinder: In zwei Experimenten mit 591 Kindern (Social Psychology 2015) trauten sich Kinder nach geschlechtergerechten Berufsbezeichnungen eher einen typisch männlichen Beruf zu, hielten ihn aber für weniger wichtig und schlechter bezahlt.', 'https://www.fu-berlin.de/presse/informationen/fup/2015/fup_15_223-einfluss-geschlechtergerechte-sprache/index.html'),
  (6, 'nein', 'Wer ein Verbot ablehnt, nennt außerdem die Freiheitsrechte: Die Antidiskriminierungsstelle des Bundes sieht in einem Gutachten (Mai 2024) bei Verboten in Schulen Risiken für die Meinungsfreiheit und die allgemeine Handlungsfreiheit von Lehrkräften und Lernenden.', 'https://www.antidiskriminierungsstelle.gov.de/SharedDocs/pressemitteilungen/DE/2024/20240513_gutachten_genderverbote.html'),
  (7, 'ja', 'Wer weiter liefern will, nennt die Verteidigungsfähigkeit der Ukraine gegen den russischen Angriff: Laut Kiel Institut stellte Deutschland im März und April 2026 Militärhilfe von 4,2 Milliarden Euro bereit, vor allem für Luftabwehr und Drohnen.', 'https://www.kielinstitut.de/de/publikationen/aktuelles/ukraine-support-tracker-militaerhilfe-bleibt-stabil-fokus-verlagert-sich-auf-drohnen/'),
  (7, 'nein', 'Wer weitere Lieferungen ablehnt, nennt die Folgen für die eigene Verteidigung: Die Wehrbeauftragte stellte im Jahresbericht 2022 fest, dass die Bundeswehr Waffen und Munition aus eigenen Beständen abgegeben hatte, und mahnte eine viel schnellere Nachbeschaffung an.', 'https://www.bundestag.de/dokumente/textarchiv/2024/kw03-de-wehrbericht-2022-983206'),
  (7, 'nein', 'Wer weitere Lieferungen ablehnt, nennt das Risiko einer Ausweitung des Krieges: Laut Stiftung Wissenschaft und Politik (2022) ist ein russischer Atomwaffeneinsatz als Reaktion auf Militärhilfe unwahrscheinlich, doch eine russische Niederlage könnte akutere Eskalationsrisiken bergen.', 'https://www.swp-berlin.org/publikation/russlands-diffuse-nuklearrhetorik-im-krieg-gegen-die-ukraine'),
  (8, 'ja', 'Wer Vorrang für Regelschulen will, nennt bessere Lernergebnisse: Eine Studie mit Daten des IQB-Ländervergleichs 2011 fand bei Kindern mit Förderbedarf an Grundschulen „signifikant höhere Kompetenzwerte im Lesen, Zuhören und in Mathematik“ als bei vergleichbaren Kindern an Förderschulen (2014).', 'https://link.springer.com/article/10.1007/s11577-014-0253-x'),
  (8, 'ja', 'Wer Vorrang für Regelschulen will, nennt außerdem die UN-Behindertenrechtskonvention: Im Schuljahr 2022/23 besuchten 55,6 Prozent der Kinder mit Förderbedarf eine Förderschule; die Exklusionsquote lag bei 4,2 Prozent, laut Bertelsmann Stiftung der zentrale Indikator für die Umsetzung der Konvention.', 'https://www.bertelsmann-stiftung.de/de/unsere-projekte/schulische-bildung/projektnachrichten/auf-dem-weg-zum-inklusiven-schulsystem-aktuelle-zahlen-zur-inklusion-an-schulen'),
  (8, 'nein', 'Wer Förderschulen erhalten will, nennt fehlende Ausstattung und Ausbildung an Regelschulen: Die Bertelsmann Stiftung stellte 2015 fest, gemeinsames Lernen scheitere „zu oft … an mangelhafter Infrastruktur und unzureichender Ausbildung der Lehrer“.', 'https://www.bertelsmann-stiftung.de/de/presse/pressemitteilungen/pressemitteilung/pid/inklusion-bleibt-an-vielen-weiterfuehrenden-schulen-ein-fremdwort'),
  (9, 'ja', 'Wer die Düngeregeln lockern will, nennt Planungssicherheit für die Betriebe und eine produktive Bewirtschaftung, die sich mit Gewässerschutz vereinbaren lasse (Sachverständige aus Landwirtschaft und Bauernverband in der Bundestagsanhörung zum Düngegesetz, 8. September 2026).', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1210980'),
  (9, 'nein', 'Wer die Regeln beibehalten oder verschärfen will, nennt die Nitratbelastung des Grundwassers: Laut Umweltbundesamt lagen 2020 bis 2022 im EU-Nitratmessnetz 26 % der Messstellen in landwirtschaftlich geprägten Gebieten über 50 mg/l; die Aufbereitung könnte Trinkwasserpreise um 32 bis 45 % erhöhen.', 'https://www.umweltbundesamt.de/themen/wasser/grundwasser/nutzung-belastungen/faqs-zu-nitrat-im-grund-trinkwasser'),
  (9, 'nein', 'Wer an den Regeln festhalten will, nennt außerdem die EU-Nitratrichtlinie: Die Kommission stellte das Vertragsverletzungsverfahren gegen Deutschland im Juni 2023 ein, weil die von Bund und Ländern erlassenen Regeln den Vorgaben der Richtlinie entsprächen.', 'https://germany.representation.ec.europa.eu/news/nitratrichtlinie-kommission-schliesst-verfahren-gegen-deutschland-2023-06-01_de'),
  (10, 'ja', 'Wer eine Vermögensteuer will, nennt die ungleiche Verteilung: Laut DIW (Wochenbericht 2021) hat die untere Hälfte der Bevölkerung keine nennenswerten Vermögen, die reichsten zehn Prozent besitzen 67 Prozent.', 'https://www.diw.de/de/diw_01.c.831678.de/publikationen/wochenberichte/2021_50_1/grunderbe_und_vermoegensteuern_koennen_die_vermoegensungleichheit_verringern.html'),
  (10, 'nein', 'Wer eine Vermögensteuer ablehnt, nennt Ausweichreaktionen: Laut Wirtschaftsdienst (2026) wird ein Minderaufkommen von bis zu 30 Prozent erwartet; für das Wachstum werden Einbußen von 0,2 bis 0,5 Prozentpunkten jährlich genannt.', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2026/heft/1/beitrag/fuer-und-wider-der-wiederbelebung-der-vermoegensteuer.html'),
  (11, 'ja', 'Wer einen verpflichtenden Wehrdienst will, nennt den Personalbedarf der Bundeswehr: Sie soll auf 260.000 aktive Soldaten und 200.000 Reservisten wachsen. Sachverständige bezweifelten 2025 in einer Anhörung des Bundestags, dass Freiwilligkeit dafür reicht.', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1125922'),
  (11, 'nein', 'Wer einen verpflichtenden Wehrdienst ablehnt, nennt die Kosten: Das ifo Institut rechnete 2024 vor, dass bei Einzug eines ganzen Jahrgangs die Wirtschaftsleistung um 1,6 Prozent (knapp 70 Mrd. Euro) sänke, bei höherer Bezahlung Freiwilliger um etwa 37 Mrd. Euro.', 'https://www.ifo.de/en/press-release/2024-07-10/reintroducing-military-conscription'),
  (12, 'ja', 'Wer einen gesetzlichen Mindestlohn will, nennt den Schutz vor sehr niedrigen Löhnen: Von der Erhöhung auf 13,90 Euro zum 1. Januar 2026 waren laut Statistischem Bundesamt bis zu 4,8 Millionen Jobs betroffen.', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/01/PD26_025_62.html'),
  (12, 'ja', 'Wer ihn will, verweist zudem darauf, dass nach der Erhöhung auf 12 Euro im Oktober 2022 laut IAB-Betriebsbefragung nur 2,4 % aller Betriebe Entlassungen meldeten.', 'https://iab-forum.de/mindestlohnerhoehung-auf-12-euro-nur-wenige-betriebe-reagierten-eigenen-angaben-zufolge-mit-entlassungen/'),
  (12, 'nein', 'Wer einen gesetzlichen Mindestlohn ablehnt, nennt das Risiko für Arbeitsplätze: Bei 14 Euro erwarteten laut IAB-Befragung (2024) rund 19 % der Betriebe weniger Beschäftigung, bei Betrieben mit Löhnen nahe dem damaligen Mindestlohn fast ein Drittel.', 'https://iab.de/presseinfo/bei-14-euro-mindestlohn-erwartet-ein-fuenftel-der-betriebe-einen-beschaeftigungsrueckgang/'),
  (13, 'ja', 'Wer die Schuldenbremse behalten will, nennt Haushaltsdisziplin und die wachsende Zinslast: Nach der Finanzplanung der Bundesregierung steigen die Zinsausgaben des Bundes von 41,9 Mrd. Euro (2027) auf 80,7 Mrd. Euro (2030), wegen des höheren Schuldenstands und gestiegener Renditen.', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1205514'),
  (13, 'nein', 'Wer die Schuldenbremse abschaffen oder weiter lockern will, nennt den Investitionsbedarf: IMK und IW beziffern ihn auf zusätzlich 600 Mrd. Euro über zehn Jahre (Studie 2024) und schlagen vor, Investitionen von der Kreditgrenze auszunehmen (Goldene Regel) oder einen Fonds einzurichten.', 'https://www.boeckler.de/de/pressemitteilungen-2675-600-milliarden-euro-staatliche-extra-investitionen-60422.htm'),
  (14, 'ja', 'Wer eine weitere Anhebung will, nennt die Finanzierung der Rentenversicherung: Laut Bundesbank (Monatsbericht Juni 2022) könnte der Beitragssatz bis 2070 auf etwa 29 Prozent steigen, mit einer Kopplung des Rentenalters an die Lebenserwartung auf etwa 27 Prozent.', 'https://www.bundesbank.de/de/aufgaben/themen/monatsbericht-wie-rentenreformen-wirken-koennten--892950'),
  (14, 'nein', 'Wer eine weitere Anhebung ablehnt, nennt die ungleiche Lebenserwartung: Nach dem Wirtschaftsdienst (Heft 5/2026) unterschied sie sich im Alter 65 (Daten 2019) zwischen niedrigster und höchster Einkommensgruppe bei Männern um 6,6, bei Frauen um 3,7 Jahre.', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2026/heft/5/beitrag/kopplung-des-gesetzlichen-renteneintrittsalters-an-die-lebenserwartung-worauf-es-ankommt.html'),
  (15, 'ja', 'Wer eine Steuer auf stark gezuckerte Getränke will, nennt den Gesundheitsschutz: Eine Auswertung von Studien aus mehreren Ländern (2019) fand, dass solche Steuern Käufe und Aufnahme gezuckerter Getränke gesenkt haben.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9285619/'),
  (15, 'ja', 'Wer die Steuer befürwortet, nennt zudem den Anreiz für Hersteller, Rezepturen zu ändern: In Großbritannien ging der durchschnittliche Zuckergehalt von Softdrinks laut einer Fachperson im Science Media Center (2026) um gut 30 Prozent zurück.', 'https://www.sciencemediacenter.de/angebote/steuer-fuer-getraenke-mit-zucker-oder-suessstoffen-26213'),
  (15, 'nein', 'Wer die Steuer ablehnt, nennt die Belastung der Haushalte: Eine Übersichtsarbeit (2016) fand die Steuer durchgehend regressiv, wenn auch in geringem Maß: Haushalte mit niedrigem Einkommen zahlten 0,10 bis 1,0 Prozent des Jahreseinkommens, mit hohem 0,03 bis 0,60 Prozent.', 'https://www.cambridge.org/core/journals/public-health-nutrition/article/impact-of-a-tax-on-sugarsweetened-beverages-according-to-socioeconomic-position-a-systematic-review-of-the-evidence/587CFDC392441741771A93E7F652E222'),
  (16, 'ja', 'Wer im Bündnis bleiben will, nennt den Schutz, den die Mitgliedschaft bietet, und die Lücken bei einer Verteidigung ohne die USA. Bruegel schätzt (2025), dass Europa ohne die USA etwa 300.000 zusätzliche Soldaten und mindestens 250 Milliarden Euro Mehrausgaben pro Jahr bräuchte.', 'https://www.bruegel.org/analysis/defending-europe-without-us-first-estimates-what-needed'),
  (16, 'nein', 'Wer austreten will, nennt die wachsenden Kosten der Mitgliedschaft: Die deutschen Militärausgaben stiegen laut SIPRI 2025 um 24 Prozent auf 114 Milliarden US-Dollar.', 'https://www.sipri.org/media/press-release/2026/global-military-spending-rise-continues-european-and-asian-expenditures-surge'),
  (17, 'ja', 'Wer die Staatsleistungen beenden will, nennt den Verfassungsauftrag zur Ablösung seit 1919 und die staatliche Neutralität in religiösen Fragen. Sachverständige im Bundestag sahen 2021 in finanziellen Dauerleistungen des Staates an die Kirchen einen Gegensatz zu dieser Neutralität.', 'https://www.bundestag.de/dokumente/textarchiv/2021/kw15-pa-innen-staatsleistungen-829020'),
  (17, 'nein', 'Wer die Zahlungen nicht beenden will, nennt die Kosten der Ablösung: Sie bräuchte eine Entschädigung, deren Wertbestimmung ein Sachverständiger 2021 das gravierendste Problem nannte; die Entwürfe im Bundestag rechneten mit etwa 3 bis mindestens 20 Milliarden Euro.', 'https://www.bundestag.de/dokumente/textarchiv/2021/kw15-pa-innen-staatsleistungen-829020'),
  (18, 'ja', 'Wer wieder russisches Gas beziehen will, nennt die wirtschaftlichen Kosten eines Wegfalls: Die Gemeinschaftsdiagnose rechnete 2022 für einen abrupten Lieferstopp mit einem aufgelaufenen Produktionsverlust von 220 Milliarden Euro bis Ende 2023.', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9120345/'),
  (18, 'nein', 'Wer weiter auf russisches Gas verzichten will, nennt die Abhängigkeit: Russland lieferte 2021 laut Bundesnetzagentur 52 Prozent der deutschen Gasimporte, 2022 fielen die Lieferungen über Nord Stream 1 bis September auf null, und der Großhandelspreis vervielfachte sich.', 'https://www.bundesnetzagentur.de/SharedDocs/Pressemitteilungen/DE/2023/20230106_RueckblickGasversorgung.html'),
  (19, 'ja', 'Wer den Euro behalten will, nennt geringere Kosten im internationalen Handel und den Schutz vor starken Wechselkursschwankungen (Bertelsmann Stiftung, Policy Brief 2013).', 'https://www.bertelsmann-stiftung.de/en/publications/publication/did/wirtschaftliche-vorteile-der-euro-mitgliedschaft-fuer-deutschland'),
  (19, 'nein', 'Wer den Euro nicht behalten will, nennt den Verlust der eigenen Geldpolitik: Im einheitlichen Währungsraum kann sie nur einen Zins setzen.', 'https://www.bpb.de/shop/zeitschriften/apuz/32445/der-euro-als-vorteil-und-nachteil-fuer-deutschland/'),
  (20, 'ja', 'Wer Solaranlagen auf Ackerflächen zulassen will, nennt den hohen Stromertrag je Fläche: Neue Photovoltaikanlagen erzeugen pro Hektar und Jahr rund 800 MWh, Mais-Biogasanlagen im Mittel 20 MWh.', 'https://www.umweltbundesamt.de/themen/klima-energie/erneuerbare-energien/photovoltaik/photovoltaik-freiflaechenanlagen'),
  (20, 'nein', 'Wer Solaranlagen auf Ackerflächen begrenzen will, nennt die Nahrungsmittelproduktion: Ackerflächen mit hoher Bodengüte sollten in der Regel nicht für Freiflächenanlagen genutzt werden.', 'https://www.umweltbundesamt.de/themen/klima-energie/erneuerbare-energien/photovoltaik/photovoltaik-freiflaechenanlagen'),
  (21, 'ja', 'Wer ein dauerhaftes Bleiberecht für gut Integrierte will, nennt den Anreiz zur Klärung der Identität: Nach dem Chancen-Aufenthaltsrecht war die Rate der Identitätsklärung laut BAMF-Kurzanalyse (2025) deutlich höher als bei vergleichbaren Geduldeten ohne diesen Titel.', 'https://www.bamf.de/SharedDocs/Anlagen/DE/Forschung/Kurzanalysen/kurzanalyse3-2025-chancen-aufenthaltsrecht.html?nn=282388'),
  (21, 'nein', 'Wer ein solches Bleiberecht ablehnt, nennt die Sorge vor falschen Signalen: In der Bundestagsanhörung zum Chancen-Aufenthaltsrecht (2022) warnte ein Vertreter des Bayerischen Landesamts für Asyl, es könne das Signal senden, dass sich fehlende Mitwirkung bei der Identitätsklärung lohne.', 'https://www.bundestag.de/dokumente/textarchiv/2022/kw48-pa-inneres-chancen-aufenthaltsrechts-921220'),
  (22, 'ja', 'Wer Kirchenasyl weiter möglich halten will, nennt den humanitären Auftrag der Kirchen, Menschen in Not zu helfen, und sieht es als zeitlich befristetes letztes Mittel für einzelne, eng begrenzte Härtefälle.', 'https://www.experteninitiative-religionspolitik.de/blog/kirchenasyl-fluechtlingsschutz-zwischen-glaube-und-recht/'),
  (22, 'nein', 'Wer Kirchenasyl ablehnt, nennt, dass es selten zu geänderten Entscheidungen führt: 2024 reichten die Kirchen 1.878 Härtefall-Dossiers ein, das BAMF nahm seine Entscheidung in einem Fall zurück (2023: in neun Fällen).', 'https://mediendienst-integration.de/fluechtlinge/asylrecht/kirchenasyl-zahlen-und-rechtslage/'),
  (22, 'nein', 'Wer Kirchenasyl ablehnt, nennt auch die fehlende gesetzliche Grundlage: Das Kirchengelände ist kein rechtsfreier Raum, die Behörden könnten jederzeit zugreifen, und Helfende mussten sich schon wegen Beihilfe zum unerlaubten Aufenthalt vor Gericht verantworten.', 'https://www.experteninitiative-religionspolitik.de/blog/kirchenasyl-fluechtlingsschutz-zwischen-glaube-und-recht/'),
  (23, 'ja', 'Wer Hausunterricht erlauben will, nennt, dass Eltern ihn für die beste Lernumgebung ihrer Kinder halten und dass andere europäische Länder ihn freier zulassen als Deutschland.', 'https://deutsches-schulportal.de/bildungswesen/homeschooling-schulverweigerer-scheitern-vor-menschenrechtsgericht/'),
  (23, 'nein', 'Wer an der Schulpflicht festhält, nennt, dass sich soziale Kompetenz im Umgang mit Andersdenkenden besser einüben lässt, wenn Kontakte mit der Gesellschaft zur Alltagserfahrung des regelmäßigen Schulbesuchs gehören (Bundesverfassungsgericht, 2006).', 'https://www.bundesverfassungsgericht.de/SharedDocs/Entscheidungen/DE/2006/05/rk20060531_2bvr169304.html'),
  (24, 'ja', 'Wer die Mitgliedschaft behalten will, nennt den Handel im Binnenmarkt: 2024 gingen deutsche Waren im Wert von 847,7 Mrd. Euro in EU-Staaten, bei einer Gesamtausfuhr von 1.559,7 Mrd. Euro.', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/02/PD25_048_51.html'),
  (24, 'ja', 'Wer die Mitgliedschaft behalten will, nennt auch die Folgen eines Austritts: Nach einer Modellrechnung des Instituts der deutschen Wirtschaft (2024, angelehnt an den Brexit) würde die Wirtschaftsleistung nach fünf Jahren um schätzungsweise 5,6 Prozent geringer ausfallen.', 'https://www.iwkoeln.de/presse/pressemitteilungen/hubertus-bardt-lennart-bolwin-berthold-busch-juergen-matthes-dexit-wuerde-690-milliarden-euro-kosten.html'),
  (24, 'nein', 'Wer die Mitgliedschaft ablehnt oder nur in anderer Form will, nennt die Kosten: Deutschland zahlte 2022 netto 19,7 Mrd. Euro und 2023 netto 17,4 Mrd. Euro mehr in den EU-Haushalt ein, als es zurückerhielt; 2024 waren es netto rund 157 Euro je Einwohner.', 'https://www.iwkoeln.de/presse/pressemitteilungen/berthold-busch-samina-sultan-bjoern-kauder-deutschland-bleibt-trotz-wirtschaftskrise-groesster-nettozahler.html'),
  (25, 'ja', 'Wer die Erbschaftsteuer abschaffen will, nennt die Steuerplanung rund um die Verschonungsregeln: Nach einem Beitrag im ifo Schnelldienst (2026) führen umfangreiche und komplexe Verschonungsregelungen dazu, dass Rechtsform, Beteiligungsstruktur und Nachfolgeprozesse steuerlich optimiert werden.', 'https://www.ifo.de/publikationen/2026/aufsatz-zeitschrift/erbschaftsteuer-und-unternehmensnachfolge-effizienzrisiken'),
  (25, 'nein', 'Wer sie behalten will, nennt die Einnahmen: Die Finanzverwaltungen setzten 2024 insgesamt 13,3 Mrd. Euro Erbschaft- und Schenkungsteuer fest, davon 8,5 Mrd. Euro Erbschaftsteuer.', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/08/PD25_320_736.html'),
  (26, 'ja', 'Wer den Abbruch in den ersten zwölf Wochen rechtmäßig stellen will, verweist auf die Empfehlung der Kommission zur reproduktiven Selbstbestimmung (2024): Schwangerschaftsabbrüche in der Frühphase der Schwangerschaft sollten rechtmäßig sein.', 'https://www.bmbfsfj.bund.de/bmbfsfj/aktuelles/pressemitteilungen/kommission-zur-reproduktiven-selbstbestimmung-und-fortpflanzungsmedizin-legt-abschlussbericht-vor-238414'),
  (26, 'ja', 'Wer die Rechtslage ändern will, nennt außerdem, dass Recht und Praxis auseinanderfallen: 2025 wurden 106.000 Abbrüche gemeldet, 96 Prozent davon nach der Beratungsregelung, die den Abbruch rechtswidrig, aber unter Bedingungen straffrei lässt.', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/04/PD26_147_233.html'),
  (26, 'nein', 'Wer die Rechtmäßigkeit ablehnt, nennt den Schutz des ungeborenen Lebens: Laut Bundesverfassungsgericht (1993) ist der Abbruch für die gesamte Dauer der Schwangerschaft grundsätzlich als Unrecht anzusehen und rechtlich verboten (Leitsatz 4, amtliche englische Übersetzung).', 'https://www.bundesverfassungsgericht.de/SharedDocs/Entscheidungen/EN/1993/05/fs19930528_2bvf000290en.html'),
  (27, 'ja', 'Wer eine gezielte Förderung will, nennt die niedrige Geburtenziffer: 2025 lag die zusammengefasste Geburtenziffer bei 1,32 Kindern je Frau, 2,7 Prozent niedriger als im Vorjahr (1,35).', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/07/PD26_230_12.html'),
  (27, 'nein', 'Wer ein gezieltes Geburtenziel ablehnt, nennt, dass sich die Geburtenrate nicht direkt steuern lässt: Familienpolitik beeinflusst die Entscheidung für Kinder, steuert die Geburtenrate aber nicht direkt (Martin Bujard, 2015).', 'https://www.bpb.de/politik/innenpolitik/familienpolitik/211417/wirkt-familienpolitik-auf-die-geburtenrate?p=all'),
  (28, 'ja', 'Wer das Ende des Schutzes an die Sicherheitslage knüpfen will, nennt den vorübergehenden Charakter des Status: Die EU-Kommission sprach 2025 von einer „schrittweisen Rückkehr und nachhaltigen Wiedereingliederung in der Ukraine“.', 'https://germany.representation.ec.europa.eu/nachrichten-und-veranstaltungen/pressemitteilungen/kriegsfluchtlinge-aus-der-ukraine-eu-kommission-schlagt-verlangerung-des-schutzstatus-um-ein-jahr-2025-06-04_de'),
  (28, 'nein', 'Wer ein Ende allein nach der Sicherheitslage ablehnt, nennt die Integration der Betroffenen: Laut einer Befragung (Januar bis März 2023) gingen 18 Prozent der 18- bis 64-Jährigen aus der Ukraine einer Beschäftigung nach, mit steigender Tendenz.', 'https://idw-online.de/de/news817718'),
  (29, 'ja', 'Wer verbindliche Mitsprache vor Ort will, nennt, dass bei der Planung von Windenergieanlagen Kommunen und Anwohnende häufig außen vor sind und die Zustimmung dramatisch sinkt, wenn konkret vor Ort geplant wird (Umweltbundesamt).', 'https://stories.umweltbundesamt.de/energiewende-vor-ort'),
  (29, 'nein', 'Wer ein verbindliches Mitentscheidungsrecht ablehnt, nennt die Flächenziele: Das Windenergieflächenbedarfsgesetz verankert, dass bis 2032 2 Prozent der Fläche Deutschlands für Windenergie auszuweisen sind; Ende 2021 waren erst 0,79 Prozent der Bundesfläche rechtskräftig ausgewiesen.', 'https://www.umweltbundesamt.de/themen/ausbau-der-windenergie-an-land-2-prozent-ziel'),
  (30, 'ja', 'Wer Gebühren befürwortet, nennt die Erfahrung mit den Gebühren von 2006/07: An Universitäten mit Studiengebühren (meist 500 Euro je Semester) schlossen etwa zehn Prozentpunkte mehr Studierende ihr Studium innerhalb von sechs Jahren ab.', 'https://www.diw.de/de/diw_01.c.815790.de/publikationen/wochenberichte/2021_15_1/temporaere_erhebung_allgemeiner_studiengebuehren__mehr_studi___chlossen_ihr_studium_ab__aber_weniger_schrieben_sich_neu_ein.html'),
  (30, 'nein', 'Wer Studiengebühren ablehnt, nennt den Zugang zum Studium: Nach der Einführung der Gebühren in sieben Ländern sank der Anteil der Studienberechtigten, die ein Studium aufnahmen, um 3,9 Prozentpunkte.', 'https://www.diw.de/de/diw_01.c.815790.de/publikationen/wochenberichte/2021_15_1/temporaere_erhebung_allgemeiner_studiengebuehren__mehr_studi___chlossen_ihr_studium_ab__aber_weniger_schrieben_sich_neu_ein.html'),
  (31, 'ja', 'Wer die Förderung fortsetzen will, nennt den Aufbau dauerhafter Strukturen: Nach der Evaluation des Deutschen Jugendinstituts (Förderperiode 2020 bis 2024) ist es mit Hilfe des Programms gelungen, lokale und überregionale Strukturen der Demokratieförderung zu stabilisieren und weiterzuentwickeln.', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1637-zentrale-ergebnisse-zu-wirkung-und-weiterentwicklung-von-demokratiefoerderung-extremismuspraevention-und-vielfaltgestaltung.html'),
  (31, 'nein', 'Wer die Bundesmittel kürzen oder beenden will, verweist auf die Höhe der Ausgaben: Der Haushalt 2027 sieht für „Demokratie leben!“ rund 167,4 Millionen Euro vor; die Mittel für Demokratiebildung und Extremismusprävention insgesamt sinken von 204,5 auf 170,1 Millionen Euro.', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1205456'),
  (32, 'ja', 'Wer höhere Verteidigungsausgaben befürwortet, nennt den Ausbau militärischer Fähigkeiten und den Schutz vor militärischen Bedrohungen als Ziele.', 'https://www.kielinstitut.de/publications/time-to-spend-smart-19558/'),
  (32, 'nein', 'Wer höhere Verteidigungsausgaben ablehnt, nennt den Erhalt finanzieller Spielräume für andere öffentliche Aufgaben und die Vermeidung sozialer Folgekosten als Ziele.', 'https://www.sipri.org/media/press-release/2025/unprecedented-rise-global-military-expenditure-european-and-middle-east-spending-surges'),
  (33, 'ja', 'Wer solche Kürzungen befürwortet, nennt verbindliche Mitwirkung und die eigenständige Sicherung des Lebensunterhalts als Ziele.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Entscheidungen/DE/2019/11/ls20191105_1bvl000716.html'),
  (33, 'ja', 'Wer solche Kürzungen befürwortet, nennt eine schnellere Arbeitsaufnahme; der IAB-Forschungsüberblick von 2025 berichtet entsprechende Befunde für Sanktionsregeln vor 2019.', 'https://iab-forum.de/sanktionen-in-der-grundsicherung-ausgewaehlte-forschungsergebnisse-aus-veroeffentlichungen-der-jahre-2021-bis-2024-im-ueberblick/'),
  (33, 'nein', 'Wer solche Kürzungen ablehnt, nennt die Sicherung notwendiger Alltagsbedarfe auch bei einer Pflichtverletzung.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Entscheidungen/DE/2019/11/ls20191105_1bvl000716.html'),
  (33, 'nein', 'Wer solche Kürzungen ablehnt, nennt nachhaltige statt nur schnelle Arbeitsaufnahme; der IAB-Forschungsüberblick von 2025 berichtet für Sanktionen vor 2019 längerfristige Nachteile bei Beschäftigungsstabilität und Beschäftigungsqualität.', 'https://iab-forum.de/sanktionen-in-der-grundsicherung-ausgewaehlte-forschungsergebnisse-aus-veroeffentlichungen-der-jahre-2021-bis-2024-im-ueberblick/'),
  (34, 'ja', 'Wer die Wiedervernässung befürwortet, nennt den Klimaschutz durch geringere Emissionen aus entwässerten Torfböden und den Schutz moortypischer Lebensräume.', 'https://www.greifswaldmoor.de/moore.html'),
  (34, 'nein', 'Wer die Wiedervernässung ablehnt, nennt den Erhalt der bisherigen landwirtschaftlichen Nutzung, die auf abgesenkten Wasserständen beruht und bei nasser Bewirtschaftung verändert werden müsste.', 'https://www.greifswaldmoor.de/moore.html'),
  (34, 'ja', 'Wer die Wiedervernässung befürwortet, nennt auch die Möglichkeit, Moorflächen weiterhin landwirtschaftlich zu nutzen, etwa durch den Anbau von Schilf oder Rohrkolben unter nassen Bedingungen.', 'https://www.moorwissen.de/paludikultur.html'),
  (35, 'ja', 'Wer die Förderung erlauben will, nennt heimische Gasvorkommen als Möglichkeit, die Versorgung abzusichern und die Importabhängigkeit zu verringern; wie viel sie dazu beitragen könnten, ist umstritten.', 'https://www.umweltbundesamt.de/publikationen/fracking-zur-schiefergasfoerderung-in-deutschland'),
  (35, 'nein', 'Wer das Verbot beibehalten will, nennt den Schutz des Trinkwassers vor möglichen Grundwasserverunreinigungen durch Chemikalien und anfallendes Abwasser.', 'https://www.umweltbundesamt.de/themen/wasser/gewaesser/grundwasser/nutzung-belastungen/fracking'),
  (35, 'nein', 'Wer die Förderung ablehnt, nennt mögliche ausgelöste Erdbeben und den Klimaschutz als Gründe, heimische fossile Gasvorkommen nicht zusätzlich zu erschließen.', 'https://www.umweltbundesamt.de/themen/wasser/gewaesser/grundwasser/nutzung-belastungen/fracking'),
  (36, 'ja', 'Wer die Förderung will, nennt die Abhängigkeit von Importen. Laut SIPRI kamen 2021–25 58 Prozent der Rüstungsimporte der europäischen NATO-Staaten aus den USA, und diese Importe stiegen gegenüber 2016–20 um 143 Prozent.', 'https://www.sipri.org/media/press-release/2026/global-arms-flows-jump-nearly-10-cent-european-demand-soars'),
  (36, 'ja', 'Wer die Förderung will, nennt auch mögliche Wachstums- und Innovationseffekte, vor allem bei Technik mit ziviler und militärischer Nutzung. Laut einer DIW-Ökonomin (2026) fließen in Deutschland nur rund 0,05 Prozent des BIP in militärische Forschung und Entwicklung.', 'https://www.bpb.de/themen/wirtschaft/europa-wirtschaft/579463/aufruestung-und-wachstum-worauf-es-wirklich-ankommt/'),
  (36, 'nein', 'Wer die Förderung ablehnt, nennt geringen Ertrag und fehlendes Geld für andere Aufgaben: Der Fiskalmultiplikator von Militärausgaben liegt in Deutschland bei höchstens 0,5, bei Bildung, Infrastruktur oder Kinderbetreuung beim Zwei- bis Dreifachen (Universität Mannheim, 2025).', 'https://www.uni-mannheim.de/newsroom/presse/pressemitteilungen/2025/juni/ruestung-ohne-rendite/'),
  (36, 'nein', 'Wer die Förderung ablehnt, nennt die Sorge vor wachsenden Rüstungsexporten außerhalb Europas. Deutschland war 2021–25 mit 5,7 Prozent der weltweiten Exporte viertgrößter Rüstungsexporteur. Die größten europäischen Lieferanten lieferten den Großteil ihrer Exporte außerhalb Europas.', 'https://www.sipri.org/media/press-release/2026/global-arms-flows-jump-nearly-10-cent-european-demand-soars'),
  (37, 'ja', 'Wer die Stationierung will, nennt die Abschreckung Russlands: Laut Stiftung Wissenschaft und Politik (2024) reichen heutige landgestützte Systeme in Europa nicht tief genug nach Russland. Das Risiko für Deutschland sei moderat, abzuwägen gegen das Risiko des Nichthandelns.', 'https://www.swp-berlin.org/publikation/gewichtig-und-richtig-weitreichende-us-mittelstreckenwaffen-in-deutschland'),
  (37, 'nein', 'Wer sie ablehnt, nennt die Eskalationsgefahr: Laut Leibniz-Institut für Friedens- und Konfliktforschung (PRIF, 2024) können solche Militäraktivitäten selbst einen Konflikt auslösen; bei Angriffen auf seine Luftverteidigung im Krieg könnte Russland zu Atomwaffen greifen.', 'https://blog.prif.org/2024/11/08/mehr-als-nur-abschreckung-mittelstreckenwaffen-und-multi-domain-operationen-in-europa/'),
  (37, 'nein', 'Wer sie ablehnt, nennt außerdem einen neuen Rüstungswettlauf: Laut IFSH Hamburg (2024) ist mit einer russischen Reaktion zu rechnen; fraglich sei, ob die Stationierung wie der NATO-Doppelbeschluss von 1979 in ein Rüstungskontrollabkommen mündet.', 'https://www.ifsh.de/news-detail/moegliche-folgen-der-stationierung-von-us-mittelstreckenwaffen-in-europa'),
  (38, 'ja', 'Wer an der Teilhabe festhalten will, nennt, dass sie die USA an die Sicherheit Europas bindet. Vor allem die Partner in Mittel- und Osteuropa sehen in den stationierten US-Atomwaffen einen Schutz (SWP 2020).', 'https://www.swp-berlin.org/10.18449/2020A48/'),
  (38, 'ja', 'Wer an der Teilhabe festhalten will, nennt auch, dass eine europäische Alternative auf absehbare Zeit kaum trägt. Frankreich hat rund 300 Sprengköpfe, und eine glaubwürdige erweiterte französische Abschreckung wäre zeitaufwendig und teuer (SWP 2023).', 'https://www.swp-berlin.org/10.18449/2023A07/'),
  (38, 'nein', 'Wer die Teilhabe ablehnt, nennt die wachsenden atomaren Risiken. Anfang 2026 gab es weltweit rund 12.187 Sprengköpfe, und seit dem Auslaufen von New START im Februar 2026 fehlt eine zentrale Begrenzung (SIPRI 2026).', 'https://www.sipri.org/media/press-release/2026/increasing-focus-nuclear-weapons-amid-heightened-escalation-risks-new-sipri-yearbook-out-now'),
  (38, 'nein', 'Wer die Teilhabe ablehnt, nennt auch, dass Deutschland bei der Atomwaffenpolitik der USA nicht mitbestimmt. Außerdem schließt die Teilhabe einen Beitritt zum Atomwaffenverbotsvertrag aus (SWP 2020).', 'https://www.swp-berlin.org/10.18449/2020A48/'),
  (39, 'ja', 'Wer die Sanktionen lockern will, nennt die Einbußen im Handel: Deutschland exportierte 2024 Waren für 7,6 Mrd. Euro nach Russland, 2021 waren es noch 26,6 Mrd. Euro (Destatis, 2025).', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/06/PD25_N032_51.html'),
  (39, 'ja', 'Wer die Sanktionen lockern will, nennt außerdem, dass sie Russlands Fähigkeit zur Kriegführung laut einem Forschungsprojekt von vier Instituten bisher kaum beeinträchtigt haben (2024).', 'https://www.ifo.de/en/press-release/2024-07-08/sanctions-barely-affecting-russias-ability-wage-war'),
  (39, 'nein', 'Wer die Sanktionen beibehalten will, nennt, dass sie Russlands Einnahmen aus Energieexporten seit 2023 schmälern und den Bau neuer Rüstungsanlagen erschweren (SWP, 2024).', 'https://www.swp-berlin.org/10.18449/2024A59/'),
  (39, 'nein', 'Wer sie nicht lockern will, nennt auch, dass Sanktionen einen Krieg zwar nicht unmittelbar stoppen, aber in Gesprächen als Verhandlungsmasse dienen können (ifo Schnelldienst, 2023).', 'https://www.ifo.de/en/publications/2023/article-journal/sanktionen-gegen-russland'),
  (40, 'ja', 'Wer militärische Forschung an Hochschulen zulassen will, nennt die Synergien zwischen ziviler und militärischer Forschung. Mitglieder der Expertenkommission Forschung und Innovation empfahlen 2024, die Trennung beider Bereiche aufzugeben und die Zivilklauseln vieler Universitäten zu überdenken.', 'https://reference-global.com/article/10.2478/wd-2024-0175'),
  (40, 'nein', 'Wer sie ablehnt, nennt die Gefahr, dass Wissenschaft politischen Zwecken untergeordnet wird und internationale Forschungskooperationen eingeschränkt werden. Auf dieses Spannungsfeld wies der Gemeinsame Ausschuss von Leopoldina und DFG 2024 hin.', 'https://idw-online.de/de/news842828'),
  (41, 'ja', 'Wer am Ziel 2045 festhalten will, nennt die Freiheit künftiger Generationen: Das Bundesverfassungsgericht entschied 2021, dass hohe Minderungslasten nicht unumkehrbar in die Zeit nach 2030 verschoben werden dürfen.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2021/bvg21-031.html'),
  (41, 'ja', 'Wer am Ziel 2045 festhalten will, nennt die Folgekosten des Klimawandels: Das Umweltbundesamt setzt für Treibhausgase, die 2026 ausgestoßen werden, 350 bis 1.000 Euro Schaden je Tonne CO2 an. Die deutschen Emissionen von 2024 verursachen danach weltweit Wohlfahrtsverluste von 647 Milliarden Euro.', 'https://www.umweltbundesamt.de/daten/umwelt-wirtschaft/gesellschaftliche-kosten-von-umweltbelastungen'),
  (41, 'nein', 'Wer das Ziel verschieben oder aufgeben will, nennt die Kosten: KfW Research schätzte 2021 den Investitionsbedarf bis 2045 auf rund 5 Billionen Euro, davon 1,9 Billionen Euro an Mehrinvestitionen allein wegen des Klimaschutzes (im Schnitt 72 Milliarden Euro pro Jahr).', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_673344.html'),
  (41, 'nein', 'Wer das Ziel verschieben will, nennt den Gleichlauf mit Europa: Das Europäische Klimagesetz von 2021 verlangt Klimaneutralität in der EU erst bis spätestens 2050, also fünf Jahre später als das deutsche Ziel.', 'https://eur-lex.europa.eu/legal-content/DE/TXT/?uri=CELEX:32021R1119'),
  (42, 'ja', 'Wer den Ausstieg verschieben oder aufheben will, nennt die Versorgungssicherheit: Laut Bundesnetzagentur ist die Stromversorgung nur dann gesichert, wenn bis 2035 zusätzliche steuerbare Kraftwerke mit 22,4 bis 35,5 Gigawatt Leistung gebaut werden (Monitoring 2025).', 'https://www.bundesnetzagentur.de/SharedDocs/Pressemitteilungen/DE/2025/20250903_Versorgungsmonitoring.html'),
  (42, 'ja', 'Wer den Ausstieg verschieben will, nennt gut bezahlte Arbeitsplätze in den Revieren: In der Lausitz arbeiteten etwa 1,7 % aller Erwerbstätigen in der Braunkohlenwirtschaft, und ein Beschäftigter dort verdiente 2014 im Schnitt rund doppelt so viel wie im Bundesdurchschnitt (IWH 2019).', 'https://www.iwh-halle.de/en/publications/detail/zu-den-effekten-eines-beschleunigten-braunkohleausstiegs-auf-beschaeftigung-und-regionale-arbeitnehmerentgelte'),
  (42, 'nein', 'Wer am Ausstieg festhält, nennt den Klimaschutz: Die Emissionen der deutschen Energieanlagen im Emissionshandel sanken 2024 um 9,5 % auf 171 Mio. t CO2-Äquivalente, ein Hauptgrund war die geringere Stromerzeugung aus Stein- und Braunkohle (DEHSt 2025).', 'https://www.dehst.de/SharedDocs/Pressemitteilungen/DE/2025-029-VET.html'),
  (42, 'nein', 'Wer am Ausstieg festhält, nennt die Planungssicherheit für die Reviere: Der Bund gewährt bis 2038 bis zu 14 Mrd. Euro Finanzhilfen, um den Strukturwandel beim Ausstieg aus der Braunkohle zu bewältigen (§ 1 InvKG).', 'https://www.gesetze-im-internet.de/invkg/__1.html'),
  (43, 'ja', 'Wer Verbotsanträge will, nennt den vorbeugenden Schutz der freiheitlichen demokratischen Grundordnung: Laut Bundesverfassungsgericht (Urteil vom 17. Januar 2017) dient das Verbot dem präventiven Schutz der Verfassung und setzt voraus, dass ein Erfolg der Partei zumindest möglich erscheint.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2017/bvg17-004.html'),
  (43, 'ja', 'Wer Verbotsanträge will, nennt die Wirkung eines Verbots: Das Gericht löst die Partei auf, untersagt Ersatzorganisationen und kann ihr Vermögen einziehen.', 'https://www.bundesverfassungsgericht.de/DE/DasBundesverfassungsgericht/Verfahrensarten/Parteiverbotsverfahren/parteiverbotsverfahren_node.html'),
  (43, 'nein', 'Wer Verbotsanträge ablehnt, nennt den schweren Eingriff in den offenen politischen Wettbewerb: Das Bundesverfassungsgericht nennt das Parteiverbot 2017 die „schärfste und überdies zweischneidige Waffe“ des demokratischen Rechtsstaats.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Entscheidungen/DE/2017/01/bs20170117_2bvb000113.html'),
  (43, 'nein', 'Wer Verbotsanträge ablehnt, nennt die hohen Hürden und das Risiko des Scheiterns: Ein Verbot braucht eine Zweidrittelmehrheit im Senat, und die beiden letzten Verfahren endeten 2003 mit einer Einstellung und 2017 ohne Verbot.', 'https://www.bundesverfassungsgericht.de/DE/DasBundesverfassungsgericht/Verfahrensarten/Parteiverbotsverfahren/parteiverbotsverfahren_node.html'),
  (44, 'ja', 'Wer die Hürde beibehalten will, nennt die Arbeitsfähigkeit des Parlaments: Laut Bundesverfassungsgericht (2024) verhindert eine Sperrklausel, dass sich der Bundestag in viele kleine Gruppen zersplittert.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2024/bvg24-064.html'),
  (44, 'nein', 'Wer die Hürde ändern oder abschaffen will, nennt die Stimmen ohne Wirkung auf die Sitzverteilung: Bei der Bundestagswahl 2025 gingen rund 6,8 Millionen gültige Zweitstimmen an Parteien ohne Sitze, das sind etwa 13,7 Prozent (eigene Rechnung aus dem amtlichen Endergebnis).', 'https://www.bundeswahlleiterin.de/bundestagswahlen/2025/ergebnisse/bund-99.html'),
  (44, 'nein', 'Wer die Hürde ablehnt, nennt außerdem die Wahlgleichheit: Das Bundesverfassungsgericht stellte 2024 fest, dass die Klausel Stimmen ungleich behandelt und unter den damaligen Bedingungen nicht in vollem Umfang erforderlich war.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2024/bvg24-064.html'),
  (45, 'ja', 'Wer das Wahlalter senken will, nennt die alternde Wählerschaft: Bei der Bundestagswahl 2025 waren 42,6 Prozent der Wahlberechtigten 60 Jahre oder älter und 13,0 Prozent jünger als 30.', 'https://www.bpb.de/kurz-knapp/zahlen-und-fakten/bundestagswahlen/564029/wahlberechtigte/'),
  (45, 'ja', 'Wer das Wahlalter senken will, nennt Befunde aus Österreich: Bei der Europawahl 2009 passte die Wahlentscheidung der unter 18-Jährigen nicht schlechter zu ihren eigenen Positionen als die älterer Wählerinnen und Wähler (Wagner, Johann, Kritzinger 2012).', 'https://www.ebi.ac.uk/europepmc/webservices/rest/PMC4020373/fullTextXML'),
  (45, 'nein', 'Wer beim Wahlalter 18 bleiben will, nennt die politische Reife: Eine Auswertung repräsentativer Befragungen kam 2006 zu dem Schluss, dass junge Menschen politisch deutlich weniger reif sind als Ältere (Chan, Clayton 2006).', 'https://ideas.repec.org/a/bla/polstu/v54y2006i3p533-558.html'),
  (45, 'nein', 'Wer beim Wahlalter 18 bleiben will, nennt auch die geringere Beteiligung der Jüngsten: Bei der Europawahl 2024, der ersten bundesweiten Wahl ab 16, gingen 60,3 Prozent der 16- bis 20-Jährigen wählen.', 'https://bundeswahlleiterin.de/info/presse/mitteilungen/europawahl-2024/07_25_ergebnisse-rws.html'),
  (46, 'ja', 'Wer die Pflicht will, nennt die verfestigte Langzeitarbeitslosigkeit: Im November 2025 waren rund eine Million Menschen langzeitarbeitslos, 55 Prozent davon zwei Jahre und länger.', 'https://www.bundestag.de/presse/hib/kurzmeldungen-1136124'),
  (46, 'ja', 'Wer die Pflicht will, nennt außerdem eine IAB-Auswertung (2023): Ein-Euro-Jobs wirken leicht positiv für Menschen mit geringen Chancen, etwa nach mehr als einem Jahr Erwerbslosigkeit, und die Teilnehmenden sind während der Förderung zufriedener mit ihrem Leben.', 'https://iab-forum.de/ein-euro-jobs-wirken-aber-nur-unter-bestimmten-bedingungen/'),
  (46, 'nein', 'Wer sie ablehnt, nennt den Lock-in-Effekt: Während der Maßnahme nehmen Teilnehmende seltener eine reguläre Stelle an. Außerdem kostete ein Fördermonat 2021 rund 600 Euro, und manche Teilnehmende empfinden die Arbeit als entwürdigend (IAB 2023).', 'https://iab-forum.de/ein-euro-jobs-wirken-aber-nur-unter-bestimmten-bedingungen/'),
  (46, 'nein', 'Wer sie ablehnt, nennt auch die Gefahr, dass reguläre Stellen verdrängt werden. Deshalb erlaubt das Gesetz nur Arbeiten, die zusätzlich und wettbewerbsneutral sind und im öffentlichen Interesse liegen (§ 16d SGB II).', 'https://www.gesetze-im-internet.de/sgb_2/__16d.html'),
  (47, 'ja', 'Wer die automatisierte Auswertung will, nennt das Erkennen schwerer Straftaten in großen Datenbeständen: In Hessen wurde die Analyseplattform laut Bundesverfassungsgericht jährlich tausendfach genutzt (Stand 2023), weil sich solche Hinweise unter Zeitdruck kaum von Hand finden lassen.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2023/bvg23-018.html'),
  (47, 'ja', 'Wer sie will, nennt außerdem die stark wachsenden Mengen an sichergestellten Daten: Bundeskriminalamt und Polizei nannten deren technische Auswertung in der Bundestagsanhörung vom September 2026 unverzichtbar.', 'https://www.bundestag.de/dokumente/textarchiv/2026/kw39-pa-inneres-1206160'),
  (47, 'nein', 'Wer sie ablehnt, nennt den Schutz der informationellen Selbstbestimmung: Laut Bundesverfassungsgericht (2023) kann Software mit einem Klick Profile von Personen, Gruppen und Milieus erstellen und viele Unbeteiligte erfassen; Fehler- und Diskriminierungsanfälligkeit verschärfen den Eingriff.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2023/bvg23-018.html'),
  (47, 'nein', 'Wer sie ablehnt, nennt außerdem, dass neben Beschuldigten auch Zeugen erfasst werden und Bewegungs- und Kontaktprofile möglich sind. So äußerten sich Sachverständige in der Bundestagsanhörung vom September 2026.', 'https://www.bundestag.de/dokumente/textarchiv/2026/kw39-pa-inneres-1206160'),
  (48, 'ja', 'Wer längeres gemeinsames Lernen will, nennt bessere Leistungen schwächerer Kinder: Eine begutachtete Studie (Matthewes 2021) fand bei zwei weiteren gemeinsamen Schuljahren bessere Werte in Mathematik und Lesen, fast nur bei leistungsschwächeren Kindern; bei leistungsstarken kein Effekt.', 'https://ideas.repec.org/a/oup/econjl/v131y2021i635p1269-1307..html'),
  (48, 'ja', 'Wer längeres gemeinsames Lernen will, nennt außerdem den Zusammenhang mit der Herkunft: 2019 hatten 67,1 Prozent der Eltern von Gymnasiasten Abitur oder Fachabitur, bei Hauptschülern waren es 16,3 Prozent (Statistisches Bundesamt, aufbereitet von der Bundeszentrale für politische Bildung).', 'https://www.bpb.de/kurz-knapp/zahlen-und-fakten/soziale-situation-in-deutschland/183038/schueler-nach-schulabschluss-der-eltern/'),
  (48, 'nein', 'Wer die Aufteilung beibehalten will, nennt Unterricht passend zum Leistungsniveau und spätere Wechsel: Laut einer begutachteten Studie (Dustmann u. a. 2017) hatten Kinder an der Grenze zweier Schulformen langfristig keinen Vorteil durch die anspruchsvollere, weil später Wechsel möglich sind.', 'https://ideas.repec.org/a/wly/econjl/v127y2017i603p1348-1380.html'),
  (49, 'ja', 'Wer das Thema im Unterricht will, nennt Ausgrenzung an Schulen: In einer EU-weiten Erhebung von 2023 gaben 67 % der befragten LGBTIQ-Personen an, in ihrer Schulzeit deswegen gemobbt, verspottet oder bedroht worden zu sein.', 'https://fra.europa.eu/en/publication/2024/lgbtiq-crossroads-progress-and-challenges'),
  (49, 'ja', 'Wer das Thema im Unterricht will, nennt außerdem, dass viele sich in der Schule verstecken: Laut derselben Erhebung (2023) verbergen 64 % dort, dass sie LGBTIQ sind.', 'https://fra.europa.eu/en/publication/2024/lgbtiq-crossroads-progress-and-challenges'),
  (49, 'nein', 'Wer es ablehnt, nennt das Erziehungsrecht der Eltern: Nach dem Bundesverfassungsgericht (1977) gehört die individuelle Sexualerziehung in erster Linie zu den Eltern (Art. 6 Abs. 2 GG).', 'https://www.servat.unibe.ch/dfr/bv047046.html'),
  (49, 'nein', 'Wer es ablehnt, nennt außerdem das Gebot der Zurückhaltung: Nach demselben Urteil (1977) muss die Schule offen für verschiedene Wertvorstellungen sein und darf kein bestimmtes Sexualverhalten befürworten oder ablehnen.', 'https://www.servat.unibe.ch/dfr/bv047046.html'),
  (50, 'ja', 'Wer Tempo 30 auf mehr Straßen will, nennt die Verkehrssicherheit: 2024 starben innerorts 915 Menschen bei Verkehrsunfällen, 62 % von ihnen waren zu Fuß oder mit dem Fahrrad unterwegs (Statistisches Bundesamt, 2025).', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2025/07/PD25_248_46241.html'),
  (50, 'ja', 'Wer es befürwortet, nennt auch weniger Unfälle und Lärm: Eine Übersichtsstudie zu 40 europäischen Städten fand nach Einführung von Tempo 30 im Mittel 37 % weniger Verkehrstote und 2,5 dB weniger Lärm (Yannis/Michelaraki, Sustainability, 2024).', 'https://ideas.repec.org/a/gam/jsusta/v16y2024i11p4382-d1399519.html'),
  (50, 'nein', 'Wer es ablehnt, nennt längere Fahrzeiten: Nachdem Wales 20 mph (rund 32 km/h) zur Regel gemacht hatte, stieg die mittlere Fahrzeit auf 57 von 60 untersuchten Strecken, meist um höchstens zwei Minuten (Transport for Wales, 2025).', 'https://tfw.wales/national-monitoring-report-july-2025'),
  (50, 'nein', 'Wer es ablehnt, nennt auch Kosten für Bus und Bahn: Wo der Nahverkehr nicht auf eine eigene Fahrbahn ausweichen kann, entstehen durch die Temporeduktion laut Stadt Zürich Mehrkosten (2021).', 'https://www.stadt-zuerich.ch/de/aktuell/medienmitteilungen/2021/12/211215a3.html'),
  (51, 'ja', 'Wer die Vorgaben lockern will, nennt den Rückgang der Betriebe: Im Mai 2026 hielten noch rund 14 700 Betriebe Schweine, 40 % weniger als 2016.', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2026/06/PD26_221_413.html'),
  (51, 'ja', 'Wer die Vorgaben lockern will, nennt den Anpassungsdruck durch neue Gesetze: Eine begutachtete Befragung von 346 Schweinehaltern fand 2023 großes Interesse an einem staatlichen Ausstiegsprogramm.', 'https://ideas.repec.org/a/eee/ecolec/v209y2023ics0921800923001167.html'),
  (51, 'nein', 'Wer die Vorgaben beibehalten oder verschärfen will, nennt das Tierwohl: 2020 lebten 79 % der Schweine auf Vollspaltenboden.', 'https://www.destatis.de/DE/Presse/Pressemitteilungen/2021/08/PD21_N051_41.html'),
  (51, 'nein', 'Wer die Vorgaben beibehalten oder verschärfen will, nennt den Umweltschutz: Rund 92 % der Ammoniak-Emissionen stammen aus der Landwirtschaft, vor allem aus der Tierhaltung. Das EU-Ziel, bis 2030 29 % weniger als 2005 auszustoßen, ist noch nicht erreicht (Daten bis 2024).', 'https://www.umweltbundesamt.de/daten/umweltzustand-trends/luft/luftschadstoff-emissionen-in-deutschland/ammoniak-emissionen'),
  (52, 'ja', 'Wer die Impfpflicht beibehalten will, nennt den Gemeinschaftsschutz: Er entsteht laut Robert Koch-Institut erst ab 95 % Immunität und schützt auch Ungeimpfte wie Säuglinge unter 9 Monaten. 2024 gab es in Deutschland 560 Masernfälle (Stand 30. 9. 2024), 2023 waren es 79.', 'https://www.rki.de/DE/Aktuelles/Publikationen/RKI-Ratgeber/Ratgeber/Ratgeber_Masern.html'),
  (52, 'ja', 'Wer die Impfpflicht beibehalten will, nennt auch das Urteil des Bundesverfassungsgerichts von 2022. Danach durfte der Gesetzgeber den Schutz gefährdeter Menschen über die Interessen der klagenden Eltern und Kinder stellen.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2022/bvg22-072.html'),
  (52, 'nein', 'Wer die Impfpflicht ablehnt, nennt den Eingriff in das Elternrecht und in die körperliche Unversehrtheit der Kinder. Auch das Bundesverfassungsgericht wertete diesen Eingriff 2022 als nicht unerheblich, weil Kinder ohne Nachweis faktisch keinen Kita-Platz bekommen.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2022/bvg22-072.html'),
  (52, 'nein', 'Wer die Impfpflicht für Kinder ablehnt, nennt den Deutschen Ethikrat (2019): Bei Kindern seien die Impfquoten hoch, die größere Lücke liege bei ungeimpften Erwachsenen. Er empfahl Beratung, Impfaktionen und eine Pflicht nur für Personal in Gesundheit, Sozialwesen und Bildung.', 'https://www.ethikrat.org/mitteilungen/mitteilungen/2019/deutscher-ethikrat-massnahmenbuendel-zur-erhoehung-der-masernimpfquote-statt-allgemeiner-impfpflicht/'),
  (53, 'ja', 'Wer die Beitragsfinanzierung beibehalten will, nennt die Vielfalt: Laut Bundesverfassungsgericht (2018) rechtfertigt sich der Beitrag durch einen Anbieter, der nicht allein dem wirtschaftlichen Wettbewerb unterliegt und sorgfältig recherchierte Informationen als Orientierung bietet.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2018/bvg18-059.html'),
  (53, 'ja', 'Wer den Beitrag beibehalten will, nennt die Unabhängigkeit von der Politik: Das Bundesverfassungsgericht verlangt (2021), dass die Beitragshöhe frei von medienpolitischen Zwecken festgesetzt wird, damit niemand über das Geld mittelbar auf das Programm Einfluss nimmt.', 'https://www.bundesverfassungsgericht.de/SharedDocs/Pressemitteilungen/DE/2021/bvg21-069.html'),
  (53, 'nein', 'Wer den Beitrag ablehnt, nennt Gerechtigkeit und Kosten: Eine Analyse im Wirtschaftsdienst (2014) hält Steuern für sozial gerechter, weil sie sich nach der Leistungsfähigkeit richten statt nach einem gleichen Betrag je Wohnung, und erwartet ohne eigene Abgabe geringere Erhebungskosten.', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2014/heft/3/beitrag/alternativen-zur-gegenwaertigen-finanzierung-des-oeffentlich-rechtlichen-rundfunks.html'),
  (53, 'nein', 'Wer den Beitrag ablehnt, nennt die Belastung: Die KEF hat für 2025 bis 2028 einen Gesamtaufwand von ARD, ZDF und Deutschlandradio von rund 42,0 Mrd. € festgestellt; 2026 beträgt der Beitrag 18,36 € im Monat je Wohnung.', 'https://kef-online.de/presse/detail/kef-empfiehlt-deutlich-geringere-anhebung-des-rundfunkbeitrags');
insert into public.haltung_positionen (haltung_id, partei_id, land, position, kurzfassung, zitat, beleg_programm_url, begruendung, stand, ki_entwurf) values
  (1, 11, null, 'nein', 'Lehnt ein generelles Tempolimit auf deutschen Autobahnen ab.', 'Anti-Auto-Haltung, Fahrverbote für Innenstädte, das Umwidmen von Parkplätzen und ein generelles Tempolimit auf deutschen Autobahnen lehnen wir ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, '2026-10-04', false),
  (1, 12, null, 'ja', 'Will ein Tempolimit von 130 km/h auf Bundesautobahnen einführen.', 'Wir wollen ein Tempolimit von 130 km/h auf Bundesautobahnen einführen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, '2026-10-04', false),
  (1, 13, null, 'ja', 'Hält ein generelles Tempolimit von 130 km/h auf Autobahnen für überfällig.', 'Ein Sicherheitstempo von 130 km/h auf Autobahnen als generelles Tempolimit ist deshalb überfällig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=48', null, '2026-10-04', false),
  (1, 14, null, 'nein', 'Lehnt ein generelles Tempolimit auf Autobahnen ab.', 'Wir Freie Demokraten lehnen ein generelles Tempolimit auf Autobahnen ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=41', null, '2026-10-04', false),
  (1, 15, null, 'nein', 'Lehnt ein generelles Tempolimit auf Bundesautobahnen strikt ab.', 'Die AfD lehnt ein generelles Tempolimit auf Bundesautobahnen strikt ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=45', null, '2026-10-04', false),
  (1, 16, null, 'ja', 'Will ein Tempolimit von 120 km/h auf Autobahnen und innerorts Tempo 30.', 'Um Menschen und Klima zu schützen, brauchen wir endlich ein Tempolimit von 120 km/h auf Autobahnen und innerorts Tempo 30 – außer auf Hauptverkehrsachsen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, '2026-10-04', false),
  (1, 17, null, 'keine_aussage', null, null, null, 'Programm auf Tempolimit, Höchstgeschwindigkeit, Geschwindigkeitsbegrenzung, Geschwindigkeitsbeschränkung, Tempo 130, Tempo 120, freie Fahrt, Geschwindigkeit, Tempo, Autobahn und Rasen durchsucht; Verkehrskapitel (S. 29–30) gelesen – keine Aussage zu einem Tempolimit gefunden.', '2026-10-04', false),
  (1, 18, null, 'ja', 'Will bundesweit Tempo 120 auf Autobahnen, Tempo 80 auf Landstraßen und Tempo 30 innerorts.', 'Bundesweite Tempolimits: Tempo 120 auf Autobahnen, Tempo 80 auf Landstraßen und Tempo 30 innerorts erhöhen die Verkehrssicherheit, reduzieren CO₂-Emissionen, schützen schwächere Verkehrsteilnehmende und reduzieren die Lärmbelastung.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', null, '2026-10-07', true),
  (2, 11, null, 'teils', 'Gewährt Schutzbedürftigen Aufnahme im Rahmen einer Kontingentlösung und trennt humanitäre Aufnahme von der Einwanderung von Fachkräften.', 'Unserer humanitären Verantwortung werden wir weiterhin gerecht und gewähren schutzbedürftigen Menschen auch in Zukunft im Rahmen einer Kontingentlösung Schutz und Aufenthalt in Deutschland. Dabei trennen wir wieder klar zwischen humanitärer Aufnahme und der Einwanderung von Fachkräften.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=44', null, '2026-10-04', false),
  (2, 12, null, 'teils', 'Will geordnete Migration auf den Arbeitsmarkt und eine bessere Kontrolle der Fluchtmigration.', 'Wir haben für neue Klarheit in der Migrationspolitik gesorgt – für einen Paradigmenwechsel hin zu einer geordneten Migration auf den Arbeitsmarkt und eine bessere Kontrolle der Fluchtmigration.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, '2026-10-04', false),
  (2, 13, null, 'nein', 'Lehnt Verschärfungen des Asylrechts ab, die zulasten Schutzsuchender gehen und Integration behindern.', 'Wir stellen uns gegen reine Symbolpolitik und einen Kurs der Asylrechtsverschärfungen, die nur zulasten der Schutzsuchenden gehen und Integration behindern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=129', null, '2026-10-04', false),
  (2, 14, null, 'teils', 'Will mehr Einwanderung in den Arbeitsmarkt, aber keine in die sozialen Sicherungssysteme.', 'Wir wollen Einwanderung in den Arbeitsmarkt, nicht in die sozialen Sicherungssysteme.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=27', null, '2026-10-04', false),
  (2, 15, null, 'ja', 'Will eine Kehrtwende in der Migrationspolitik: Grenzen wieder kontrollieren, einreisen darf nur, wem es erlaubt ist.', 'Die AfD wird eine deutliche Kehrtwende in der bisherigen Migrationspolitik einleiten und die Staatsgrenzen wieder kontrollieren. Die Freizügigkeitsregelungen innerhalb der EU bleiben davon unberührt. Einreisen darf künftig nur noch, wem dies erlaubt ist.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=101', null, '2026-10-04', false),
  (2, 16, null, 'nein', 'Will Visa liberalisieren und ein offenes Einwanderungsrecht, das nicht nach Herkunft oder Verwertbarkeit unterscheidet.', 'Wir setzen uns für eine umfassende Visaliberalisierung sowie für ein offenes und solidarisches Einwanderungsrecht ein, das sich nicht mehr am Maßstab Herkunft oder ökonomische Verwertbarkeit orientiert, sondern Teilhabe und Partizipation für alle ermöglicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=54', null, '2026-10-04', false),
  (2, 17, null, 'teils', 'Verteidigt das Asylrecht für wirklich Schutzbedürftige und will die unkontrollierte Einwanderung beenden.', 'Wir verteidigen das Grundrecht auf Asyl für wirklich Schutzbedürftige. Gleichzeitig wollen wir die unkontrollierte Einwanderung beenden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, '2026-10-04', false),
  (2, 18, null, 'teils', 'Will ein effizienteres Zuwanderungssystem gegen den Fachkräftemangel und für den Arbeitsstandort.', 'Ein effizienteres Zuwanderungssystem ist entscheidend, um dem Fachkräftemangel zu begegnen und Deutschland als attraktiven Arbeitsstandort zu stärken.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=50', null, '2026-10-07', true),
  (4, 11, null, 'ja', 'Will den zielgerichteten weiteren Ausbau aller Erneuerbaren, ausdrücklich auch der Windenergie an Land.', 'Wir bringen alle Kapazitäten ans Netz, die klimafreundlich und systemdienlich sind, angefangen bei einem zielgerichteten weiteren Ausbau der Erneuerbaren Energien. Wir nutzen die Erneuerbaren konsequent, und zwar alle: Windenergie an Land und auf See, Solarenergie, Geothermie, Wasserkraft, Bioenergie und den nachwachsenden Rohstoff Holz.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=21', null, '2026-10-08', true),
  (4, 12, null, 'ja', 'Will Windkraft und Fotovoltaik konsequent ausbauen und Speicher einbinden.', 'Windkraft und Fotovoltaik sind schon heute die günstigste Form der Stromproduktion. Ihr konsequenter Ausbau und die Einbindung von Speichern macht unsere Energieversorgung sicher und dauerhaft bezahlbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, '2026-10-08', true),
  (4, 13, null, 'ja', 'Will das erreichte Rekord-Ausbautempo der Erneuerbaren halten und die Infrastruktur ausbauen.', 'Wir halten Kurs beim erreichten Rekord-Ausbautempo und bauen die Infrastruktur so aus, dass sie sicher vor Angriffen ist und der günstige Strom bei Menschen und Unternehmen ankommt. Die Zukunft gehört den erneuerbaren Energien – in Form von Strom, Wärme und Wasserstoff.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=41', null, '2026-10-08', true),
  (4, 14, null, 'teils', 'Will Windkraftanlagen über Marktvergütung nur bei ausreichend Netzen und Speichern; lehnt gesetzliche Ausbaupfade und garantierte Abnahmepreise ab.', 'Eine Vergütung am Markt würde auch gewährleisten, dass Photovoltaik- und Windkraftanlagen nur gebaut werden, wenn ausreichend Netze und Speicher vorhanden sind, um die Nutzung des produzierten Stroms sicherzustellen. Wir lehnen gesetzlich vorgegebene Ausbaupfade für einzelne Technologien genauso ab, wie staatlich garantierter Abnahmepreise.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, '2026-10-08', true),
  (4, 15, null, 'nein', 'Lehnt den weiteren Ausbau der Windenergie ab, um weitere Schädigungen der Natur zu verhindern.', 'Weitere Schädigungen unserer Natur im Namen eines vermeintlichen Klimaschutzes müssen unter allen Umständen verhindert werden. [...] Deshalb lehnen wir den weiteren Ausbau der Windenergie ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=81', null, '2026-10-08', true),
  (4, 16, null, 'ja', 'Will Kommunen einen Bonus von 25 000 Euro je Megawatt gebauter Windräder oder PV-Großflächenanlagen zahlen, auch bei Repowering.', 'Energiewende für die Menschen vor Ort: Kommunen bekommen einen Bonus von 25 000 Euro pro 1 Megawatt-Leistung eines gebauten Windrades oder gebauter PV-Großflächenanlage. Dieser fließt direkt in die Gemeindekasse und kann für Neuanlagen als auch für Repowering genutzt werden. So profitiert die lokale Bevölkerung direkt vom Ausbau der erneuerbaren Energien.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, '2026-10-08', true),
  (4, 17, null, 'teils', 'Will ein Repowering-Programm: alte Windanlagen an vorhandenen Standorten durch neue ersetzen, ohne neue Eingriffe in die Natur.', 'Im Bereich der Erneuerbaren Energien fordern wir ein „Repowering“-Programm. Alte Windanlagen wollen wir durch neue ersetzen. So können wir an vorhandenen Standorten ohne neue Eingriffe in die Natur den Stromertrag erhöhen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, '2026-10-08', true),
  (4, 18, null, 'ja', 'Will erneuerbare Energien konsequent ausbauen, sodass 2035 durchgehend 100 % des Strombedarfs erneuerbar gedeckt sind.', 'Konsequenter Ausbau von erneuerbarer Energie: Im Jahr 2035 werden durchgehend 100 % des Strombedarfs aus erneuerbaren Energien gedeckt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=66', null, '2026-10-08', true),
  (5, 11, null, 'teils', 'Setzt auf Forschung zu neuen Reaktortypen und Fusion und will prüfen, ob die zuletzt abgeschalteten Kernkraftwerke wieder in Betrieb gehen können.', 'Dabei setzen wir auf die Forschung zu Kernenergie der vierten und fünften Generation, Small Modular Reactors und Fusionskraftwerken. Gleichzeitig streben wir schnellstmöglich eine fachliche Bestandsaufnahme an, ob angesichts des jeweiligen Rückbaustadiums eine Wiederaufnahme des Betriebs der zuletzt abgeschalteten Kernkraftwerke unter vertretbarem technischem und finanziellem Aufwand noch möglich ist.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, '2026-10-08', true),
  (5, 12, null, 'nein', 'Begrüßt die Stilllegung der Atomkraft und fordert die sichere Endlagerung der radioaktiven Stoffe.', 'Die Atomkraft in Deutschland ist stillgelegt und das ist gut so. Jetzt braucht es die sichere Endlagerung der radioaktiven Stoffe.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=53', null, '2026-10-08', true),
  (5, 13, null, 'nein', 'Lehnt eine Rückkehr zur Atomkraft ab, wegen ungeklärter Endlagerfrage, Kosten und Verbreitungsgefahr; hält sie für Klima und Versorgung nicht notwendig.', 'Eine Rückkehr zur Hochrisikotechnologie Atomkraft ist weder für das Erreichen der Klimaziele noch für die Versorgungssicherheit notwendig und für uns aufgrund der ungeklärten Endlagerfrage, der Kosten und der Gefahr der Verbreitung von atomwaffenfähigem Material […]', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', null, '2026-10-08', true),
  (5, 14, null, 'ja', 'Will den rechtssicheren Bau neuer Reaktortypen und die Wiederinbetriebnahme vorhandener Kernkraftwerke rechtlich ermöglichen, Entscheidung bei den Betreibern.', 'Unser Ziel ist, dass Kernkraftwerke der neuen Generation, etwa Dual-Fluid-Reaktoren, Thorium-Flüssigsalzreaktoren oder Small Modular Reactors in Deutschland rechtssicher gebaut werden können. [...] Wir wollen die Wiederinbetriebnahme der vorhandenen Kernkraftwerke rechtlich ermöglichen und die Entscheidung darüber den Betreibern überlassen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, '2026-10-08', true),
  (5, 15, null, 'ja', 'Plant den Wiedereinstieg in die Kernenergie; bestehende Kraftwerke sollen so schnell wie möglich wieder in Betrieb gehen.', 'Neben dem kurzfristig notwendigen Ausbau von Kohlekraftwerken planen wir den Wiedereinstieg in die Kernenergie. Dabei sollen bestehende Konzepte wieder aufgegriffen und neue Entwicklungen berücksichtigt werden. Bestehende Kraftwerke sollen so schnell wie möglich wieder in Betrieb genommen werden.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=42', null, '2026-10-08', true),
  (5, 16, null, 'nein', 'Will den Atomausstieg im Grundgesetz festschreiben und die Fertigung von Uranbrennstoff in Gronau und Lingen beenden.', 'Kein Rollback, sondern Atomausstieg sofort: Wir wollen den Ausstieg aus der Atomkraft im Grundgesetz festschreiben und die Fertigung von Uranbrennstoff in den Atomfabriken in Gronau und Lingen beenden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, '2026-10-08', true),
  (5, 17, null, 'nein', 'Lehnt den Neubau konventioneller Atomkraftwerke und derzeit auch Mini-Kraftwerke (SMR) ab.', 'Den Neubau konventioneller Atomkraftwerke lehnen wir ab. Dasselbe gilt derzeit für Mini-Kraftwerke (SMR), deren Betrieb bis zu 30-mal mehr radioaktive Abfälle erzeugt als konventionelle Reaktoren.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, '2026-10-08', true),
  (5, 18, null, 'keine_aussage', null, null, null, 'Kapitel Erneuerbare Energien (S. 65–68) gelesen; Suche nach Atom, Kernenergie, Kernkraft, Kernfusion, Reaktor: nichts. Das Programm spricht nur vom Ausstieg aus Fossilen.', '2026-10-08', true),
  (7, 11, null, 'ja', 'Unterstützt die Ukraine mit diplomatischen, finanziellen und humanitären Mitteln sowie mit Waffenlieferungen.', 'Die Ukraine verteidigt auch uns. Denn fällt die Ukraine, droht der Angriff auf ein weiteres europäisches Land. Daher unterstützen wir die Ukraine mit allen erforderlichen diplomatischen, finanziellen und humanitären Mitteln sowie mit Waffenlieferungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=47', null, '2026-10-08', true),
  (7, 12, null, 'ja', 'Unterstützt Ausbildung ukrainischer Streitkräfte und Lieferung von Waffen und Ausrüstung mit Besonnenheit; Deutschland und NATO sollen nicht Kriegspartei werden.', 'Zur Verteidigung der Ukraine und zur Sicherung des Friedens in Europa unterstützt die SPD die Ausbildung der ukrainischen Streitkräfte und die Lieferung von Waffen und Ausrüstung mit Besonnenheit und Augenmaß. Denn für uns gilt, dass Deutschland und die NATO nicht selbst zur Kriegspartei werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=58', null, '2026-10-08', true),
  (7, 13, null, 'ja', 'Will die Ukraine weiter in ihrem Recht auf Selbstverteidigung deutlich stärken und ihre Verteidigungsfähigkeit verbessern.', 'Die Ukraine muss in der Lage sein, sich zu verteidigen und eine starke Position für einen möglichen Friedensprozess sicherzustellen. Dafür wollen wir sie auch weiter in ihrem Recht auf Selbstverteidigung deutlich stärken und ihre Verteidigungsfähigkeit verbessern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=142', null, '2026-10-08', true),
  (7, 14, null, 'ja', 'Will, dass die Verteidigung der Ukraine nicht an Geld und Waffen scheitert, und fordert die unverzügliche Lieferung des Marschflugkörpers Taurus.', 'Für uns Freie Demokraten steht fest, dass die Verteidigung der Ukraine nicht am Geld und an Waffenlieferungen scheitern darf, da ein russischer Sieg teurer sein wird und in der Ukraine auch unsere Freiheit verteidigt wird. […] Daher fordern wir die unverzügliche Lieferung des Marschflugkörper Taurus.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=47', null, '2026-10-08', true),
  (7, 15, null, 'keine_aussage', null, null, null, 'Fundstelle S. 89 äußert laut Einordnung ohne Parteinamen keine erkennbare Haltung zur Frage: Beschreibt nur den Zustand der Bundeswehr, auch infolge der Abgaben an die Ukraine, ohne Forderung zu künftigen Lieferungen.', '2026-10-08', true),
  (7, 16, null, 'nein', 'Lehnt Waffenlieferungen in Kriegs- und Krisengebiete ab und setzt auf Friedensinitiativen, Verhandlungen und gezielte Sanktionen.', 'Um endlich einen Friedensprozess für die Ukraine zu ermöglichen, muss die Bundesregierung Friedensinitiativen wie die von China und Brasilien endlich aufgreifen und sich aktiv für eine gemeinsame diplomatische Verhandlungsoffensive einsetzen, unterstützt durch gezielte Sanktionen, die nicht gegen die allgemeine Bevölkerung gerichtet sind. […] Wir lehnen Waffenlieferungen in Kriegs- und Krisengebiete ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=23', null, '2026-10-08', true),
  (7, 17, null, 'nein', 'Will kein weiteres deutsches Steuergeld für die Verlängerung des Krieges; hält Waffenlieferungen für ungeeignet, das Sterben zu beenden.', 'Selbst wenn eine Ausweitung des Krieges abgewendet werden kann: Waffenlieferungen werden das Sterben nicht beenden. […] Wir wollen, dass kein weiteres deutsches Steuergeld bereitgestellt wird, um diesen sinnlosen Krieg zu verlängern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=7', null, '2026-10-08', true),
  (7, 18, null, 'ja', 'Will ein gemeinsames Konzept zur Militärhilfe, alle erforderlichen Waffen liefern und deren uneingeschränkte Nutzung ermöglichen.', 'Koordinierte Militärhilfe: Deutschland entwickelt gemeinsam mit der Ukraine und seinen Partnern ein strategisches Konzept zur militärischen Unterstützung, liefert alle erforderlichen Waffen und ermöglicht deren uneingeschränkte Nutzung.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=45', null, '2026-10-08', true),
  (8, 11, null, 'nein', 'Will individuelle Bildungsmöglichkeiten und sieht neben Inklusionsangeboten auch Förderschulen als Bestandteil der Bildungswelt.', 'Wir sorgen für individuelle Bildungsmöglichkeiten für Schülerinnen und Schüler mit Behinderungen und sehen neben Inklusionsangeboten auch Förderschulen als Bestandteil der Bildungswelt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=62', null, '2026-10-08', true),
  (8, 12, null, 'keine_aussage', null, null, null, 'Kapitel 4 Bildung (S. 15-17), Familien (S. 1040ff.), Teilhabe/Behinderung (Abschnitt inklusive Gesellschaft) gelesen; Suche nach Inklusion, Förderschule, Förderbedarf, sonderpäd, gemeinsames Lernen, Behinderung: Inklusion nur bei Sport/Kultur und allgemein Barrierefreiheit/Arbeitsmarkt, nichts zur Schulform.', '2026-10-08', true),
  (8, 13, null, 'ja', 'Will Inklusion aller Schülerinnen und Schüler gemäß UN-Behindertenrechtskonvention an allen Schulen zur gelebten Realität machen.', 'Wir bauen die Angebote der Mental Health Coaches an Schulen aus und wir setzen uns dafür ein, dass Inklusion aller Schüler*innen gemäß der UN-Behindertenrechtskonvention an allen Schulen zur gelebten Realität wird.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, '2026-10-08', true),
  (8, 14, null, 'teils', 'Will ein inklusives Bildungssystem von der Kita bis zur Ausbildung, hält Förderschulen aber für unverzichtbar.', 'Zudem fordern wir ein inklusives Bildungssystem von der Kita bis zur Berufsausbildung, indem sonderpädagogische Inhalte in die pädagogische Grundausbildung integriert werden. Wegen der unterschiedlichen Ausprägung von Behinderungen halten wir aber die Förderschulen für unverzichtbar, um allen individuellen Notwendigkeiten der Förderung gerecht zu werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=25', null, '2026-10-08', true),
  (8, 15, null, 'nein', 'Will die Förderschulen erhalten und wieder zum Regelfall für Kinder mit sonderpädagogischem Förderbedarf machen.', 'Die AfD setzt sich deshalb für den Erhalt der Förderschulen ein. Die Förderschule sollte wieder zum Regelfall für Schüler mit sonderpädagogischem Förderbedarf werden.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=161', null, '2026-10-08', true),
  (8, 16, null, 'ja', 'Will inklusives Lernen in allen Bildungseinrichtungen, Förderschulen umstrukturieren und sonderpädagogisches Personal an allen Regelschulen einstellen.', 'Bildung inklusiv machen – inklusives Lernen in allen Bildungseinrichtungen: Die Förderschulen müssen umstrukturiert werden, an allen Regelschulen sollte sonderpädagogisches Personal eingestellt werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=54', null, '2026-10-08', true),
  (8, 17, null, 'keine_aussage', null, null, null, 'Bildungskapitel (S. 23-26) gelesen; Suche nach Inklusion, inklusiv, Förderschule, Behinderung, Sonderpädagog: nur Lehrkräftemangel, ''längeres gemeinsames Lernen'' (Schulstruktur) und UN-BRK allgemein (S. 22); nichts zu Förderschulen oder Inklusion in Schulen.', '2026-10-08', true),
  (8, 18, null, 'ja', 'Will Förderschulen nur als Übergangslösung in Kooperation mit Regelschulen betreiben, bis das Ziel „Eine Schule für alle“ erreicht ist.', 'Förderschulen als Übergangslösung: Förderschulen werden in enger Kooperation mit Regelschulen betrieben, bis das Ziel „Eine Schule für alle“ erreicht ist.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=112', null, '2026-10-08', true),
  (9, 11, null, 'ja', 'Will auf die Stoffstrombilanz im Düngerecht verzichten, ein EU-Bodengesetz abwenden und die EU-Taxonomie für Land- und Forstwirtschaft entschärfen.', 'Konkret wollen wir auf die Stoffstrombilanz im Düngerecht verzichten, ein EU-Bodengesetz dauerhaft abwenden und die EU-Taxonomie auch für die Land- und Forstwirtschaft entschärfen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=36', null, '2026-10-08', true),
  (9, 12, null, 'keine_aussage', null, null, null, 'Landwirtschaftsabschnitt (S. 52-54) gelesen; Suche nach Düng, Nitrat, Gülle, Grundwasser, Pflanzenschutz: nichts. Nur allgemein bürokratiearme Landwirtschaft und GAP-Vereinfachung, keine Aussage zu Düngeregeln.', '2026-10-08', true),
  (9, 13, null, 'nein', 'Will sparsamen Einsatz von Pestiziden und Düngemitteln und eine Nährstoffbilanz einführen, um den Düngereinsatz gezielter zu machen und zu senken.', 'Landwirtschaft und Umwelt brauchen einen möglichst sparsamen und bedachten Einsatz von Pestiziden und Düngemitteln. Die Einführung einer Nährstoffbilanz unterstützt den gezielteren Düngereinsatz und kann helfen, ihn zu senken.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=59', null, '2026-10-08', true),
  (9, 14, null, 'teils', 'Will zwecklose und unverhältnismäßige Dokumentationspflichten und Auflagen abschaffen und auf EU-Ebene bremsende Regulierung zurücknehmen.', 'Zwecklose und unverhältnismäßige Dokumentationspflichten und Auflagen schaffen wir ab. Auf EU-Ebene drängen wir weiter auf die Rücknahme bremsender Regulierung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', null, '2026-10-08', true),
  (9, 15, null, 'ja', 'Will bedarfsgerechte Düngung nach guter fachlicher Praxis wieder ermöglichen und den bürokratischen Aufwand auf das notwendige Minimum beschränken.', 'Die derzeitigen Düngeregeln verursachen erhebliche Ertrags- und Qualitätseinbußen sowie massive ökologische Probleme, darunter der Verlust von Bodenfruchtbarkeit und Humus. Die AfD wird deshalb die bedarfsgerechte Nährstoffversorgung von Kulturpflanzen nach guter fachlicher Praxis wieder ermöglichen und den bürokratischen Aufwand auf das absolut notwendige Minimum beschränken.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=76', null, '2026-10-08', true),
  (9, 16, null, 'keine_aussage', null, null, null, 'Landwirtschaftskapitel (S. 41–43) gelesen; Suche nach Düngung, Dünge, Nitrat, Gülle, Grundwasser, Pestizid: nur Düngemittelalternativen und weniger Überdüngung durch geringere Viehbestände (S. 42) sowie Vereinfachung von Förderanträgen, nichts zu Düngeverordnung oder Düngeregeln.', '2026-10-08', true),
  (9, 17, null, 'keine_aussage', null, null, null, 'Agrarabschnitt (S. 19-20) gelesen; Suche nach Dünge, Nitrat, Gülle, Grundwasser: nichts. Nur allgemein ''unnötige Bürokratie abbauen'' und Umweltauflagen mit Übergangszeiten, ohne Bezug zu Düngeregeln.', '2026-10-08', true),
  (9, 18, null, 'nein', 'Will Gewässerbelastungen durch Spurenstoffe, Düngemittel und industrielle Einleitungen durch gezielte Maßnahmen reduzieren.', 'Um die Gewässerverschmutzung zu reduzieren und die Qualität der aquatischen Ökosysteme zu sichern, werden die Belastungen durch Spurenstoffe, Düngemittel und industrielle Einleitungen durch gezielte Maßnahmen reduziert', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=77', null, '2026-10-08', true),
  (10, 11, null, 'nein', 'Lehnt eine Vermögensteuer ab und will stattdessen alle beim Aufbau eigenen Vermögens unterstützen.', 'Keine Vermögensteuer. Wir wollen Menschen, die sich etwas erarbeitet und aufgebaut haben, nicht bestrafen. Stattdessen wollen wir alle Menschen beim Aufbau eines eigenen Vermögens unterstützen. Eine Vermögensteuer lehnen wir ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=34', null, '2026-10-08', true),
  (10, 12, null, 'ja', 'Will die ausgesetzte Vermögensteuer für sehr hohe Vermögen wiederbeleben.', 'Die ausgesetzte Vermögensteuer wollen wir für sehr hohe Vermögen revitalisieren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', null, '2026-10-08', true),
  (10, 13, null, 'ja', 'Nennt als mögliche Ansätze eine globale Milliardärssteuer, fairere Erbschaftsteuer, Immobilienbesteuerung ohne Schlupflöcher und eine nationale Vermögensteuer auf sehr hohe Vermögen.', 'Zu möglichen Ansätzen gehören: eine globale Milliardärssteuer, eine fairere Erbschaftssteuer, eine gerechte Immobilienbesteuerung ohne Schlupflöcher und eine nationale Vermögenssteuer auf sehr hohe Vermögen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', null, '2026-10-08', true),
  (10, 14, null, 'nein', 'Lehnt jede Form einer Vermögensteuer oder Vermögensabgabe ab.', 'Wir lehnen jede Form einer Vermögensteuer oder Vermögensabgabe ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, '2026-10-08', true),
  (10, 15, null, 'nein', 'Will die ausgesetzte Vermögensteuer sowie die Erbschaftsteuer abschaffen.', 'Die AfD will die derzeit zur Erhebung ausgesetzte Vermögensteuer sowie die Erbschaftssteuer abschaffen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=61', null, '2026-10-08', true),
  (10, 16, null, 'ja', 'Will die Vermögensteuer wieder einführen, mit einem Freibetrag von einer Million Euro je Person, sodass nur die reichsten 2,5 Prozent belastet werden.', 'Die Linke fordert, dass die Vermögensteuer wieder eingeführt wird. Damit wir nur die reichsten 2,5 Prozent unserer Gesellschaft belasten, fordern wir einen Freibetrag für Privatvermögen von einer Million Euro pro Person (abzüglich aller Schulden, wie zum Beispiel Hypotheken auf ein Eigenheim).', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=10', null, '2026-10-08', true),
  (10, 17, null, 'ja', 'Will die Vermögensteuer ab 25 Millionen Euro mit 1 Prozent reaktivieren, steigend auf 2 Prozent ab 100 Millionen und 3 Prozent ab 1 Milliarde.', 'Die Vermögenssteuer wollen wir für Vermögen ab 25 Millionen Euro mit einem Steuersatz von 1 Prozent reaktivieren, der ab 100 Millionen Euro Vermögen auf 2 Prozent und ab 1 Mrd. Euro auf 3 Prozent steigt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, '2026-10-08', true),
  (10, 18, null, 'ja', 'Sieht in einer progressiven Vermögensteuer zusätzliche Mittel für Klimaschutz, Bildung und den Abbau sozialer Ungleichheit.', 'Eine progressive Vermögensteuer kann diese Herausforderungen adressieren und zugleich zusätzliche Mittel zur Bewältigung zentraler gesellschaftlicher Herausforderungen wie dem Klimawandel, der Bildungsfinanzierung und der sozialen Ungleichheit bereitstellen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=100', null, '2026-10-08', true),
  (11, 11, null, 'ja', 'Will eine aufwachsende Wehrpflicht einführen und perspektivisch ein verpflichtendes Gesellschaftsjahr; einberufen werden benötigte Taugliche, die Bereitschaft signalisiert haben.', 'Aufwachsende Wehrpflicht einführen. Wir setzen perspektivisch auf ein verpflichtendes Gesellschaftsjahr, das wir mit der aufwachsenden Wehrpflicht zusammendenken. […] Aus dem Kreis der Gemusterten sollen diejenigen benötigten Tauglichen kontingentiert und zum Grundwehrdienst einberufen werden, die ihre Bereitschaft zum Wehrdienst signalisiert haben.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=52', null, '2026-10-08', true),
  (11, 12, null, 'nein', 'Plant einen neuen, flexiblen Wehrdienst auf Basis der Freiwilligkeit nach Bedarf der Bundeswehr und will zügig eine Wehrerfassung schaffen.', 'Angesichts der veränderten sicherheitspolitischen Lage plant die SPD die Einführung eines neuen, flexiblen Wehrdienstes. Der neue Wehrdienst soll auf Freiwilligkeit basieren und sich dabei am Bedarf der Bundeswehr orientieren. Es müssen zügig die Grundlagen für eine Wehrerfassung geschaffen werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=58', null, '2026-10-08', true),
  (11, 13, null, 'nein', 'Will den ausgesetzten Grundwehrdienst nicht wieder einführen, sondern freiwilligen Wehrdienst und Reserve attraktiver machen.', 'Statt den aus guten Gründen seit 2011 ausgesetzten allgemeinen Grundwehrdienst wieder einzuführen, wollen wir den freiwilligen Wehrdienst und die Reserve für eine breite Zielgruppe attraktiver machen', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=154', null, '2026-10-08', true),
  (11, 14, null, 'nein', 'Will eine professionelle Freiwilligenarmee mit starker Reserve und eine Datenbank wehrfähiger Personen; lehnt die allgemeine Wehrpflicht ab.', 'Wir Freie Demokraten setzen uns für eine professionelle Freiwilligenarmee aus Aktiven und einer starken Reserve und für eine nationale Datenbank zur Erfassung wehrfähiger Männer und Frauen ein. Wir orientieren uns hierbei an den Fähigkeitszielen der NATO. Die Wiedereinsetzung der allgemeinen Wehrpflicht lehnen wir ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=48', null, '2026-10-08', true),
  (11, 15, null, 'ja', 'Will die Wehrpflicht wieder einsetzen, einschließlich des Ersatzdienstes nach geltender Gesetzeslage.', 'Daher wollen wir die Wehrpflicht wieder einsetzen. Diese beinhaltet gemäß aktueller Gesetzeslage auch den Ersatzdienst.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=89', null, '2026-10-08', true),
  (11, 16, null, 'nein', 'Lehnt die Wiedereinführung der Wehrpflicht und Werbung der Bundeswehr an Schulen, Messen, Universitäten und per Brief ab.', 'Wir stellen uns gegen eine Militarisierung der Gesellschaft: keine Wiedereinführung der «Wehrpflicht», kein Werben fürs Sterben an Schulen, auf Bildungsmessen, an Universitäten oder per Briefsendungen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=23', null, '2026-10-08', true),
  (11, 17, null, 'nein', 'Lehnt die Wiedereinführung einer Wehrpflicht ab und betont das Prinzip der Freiwilligkeit.', 'Das Prinzip der Freiwilligkeit ist in der beruflichen Orientierungsphase der Heranwachsenden von enormer Bedeutung und darf nicht für Kriegs- und Aufrüstungspolitik außer Kraft gesetzt werden. ✔ Wir lehnen die Wiedereinführung einer Wehrpflicht ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=6', null, '2026-10-08', true),
  (11, 18, null, 'keine_aussage', null, null, null, 'Kapitel Bundeswehr/Europa-Armee (S. 41–42) gelesen; Suche nach Wehrpflicht, Wehrdienst, Dienstpflicht, Zivildienst, Freiwillig: nur Stärkung der Reserve und flexible Personalstrukturen, keine Aussage zu Pflichtdienst.', '2026-10-08', true),
  (12, 11, null, 'ja', 'Steht zum gesetzlichen Mindestlohn und einer unabhängigen Mindestlohnkommission; Lohnfindung soll Sache der Sozialpartner sein.', 'Wir stehen zum gesetzlichen Mindestlohn und einer starken, unabhängigen Mindestlohnkommission. Lohnfindung muss Sache der Sozialpartner sein – im Sinne von Fairness und wirtschaftlicher Vernunft.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=5', null, '2026-10-08', true),
  (12, 12, null, 'ja', 'Will den Mindestlohn an mindestens 60 Prozent des mittleren Einkommens ausrichten, spätestens ab 2026 bei 15 Euro.', 'Die Höhe des gesetzlichen Mindestlohns muss sich an den Empfehlungen der europäischen Richtlinie orientieren, also an mindestens 60 Prozent des mittleren Einkommens in Deutschland. […] Dementsprechend muss der Mindestlohn spätestens ab 2026 bei 15 Euro liegen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, '2026-10-08', true),
  (12, 13, null, 'ja', 'Will einen schrittweise steigenden Mindestlohn von zunächst 15 Euro in 2025, auch für unter 18-Jährige.', 'Faire Löhne verlangen nach einem fairen Mindestlohn, damit Leistung auch anerkannt wird. Um die Inflation der vergangenen Jahre auszugleichen, braucht es jetzt einen schrittweise steigenden Mindestlohn von zunächst 15 Euro in 2025 und das auch für unter 18-Jährige.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=67', null, '2026-10-08', true),
  (12, 14, null, 'teils', 'Will Löhne zwischen Arbeitnehmern und Arbeitgebern aushandeln lassen und lehnt politische Eingriffe in die Mindestlohnkommission ab.', 'Löhne und Gehälter werden in der sozialen Marktwirtschaft zwischen Arbeitnehmern und Arbeitgebern ausgehandelt. Wir respektieren die Tarifautonomie und lehnen politische Eingriffe in die Arbeit der unabhängigen Mindestlohnkommission ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, '2026-10-08', true),
  (12, 15, null, 'keine_aussage', null, null, null, 'Alle Treffer zu Mindestlohn/Lohn/Tarif gelesen (S. 23/24 nur Erhalt des Mindestlohns für Werkstattbeschäftigte per Mittelumschichtung, S. 58 Niedriglohnsektor nur steuerlich, Grundfreibetrag); keine Aussage zu einem allgemeinen gesetzlichen Mindestlohn, Abschaffung oder Tarifautonomie.', '2026-10-08', true),
  (12, 16, null, 'ja', 'Will den gesetzlichen Mindestlohn auf mindestens 15 Euro, spätestens 2026 auf 16 Euro anheben und die Tarifbindung stärken.', 'Der gesetzliche Mindestlohn muss hoch auf mindestens 15 Euro (spätestens 2026 auf 16 Euro) und die Tarifbindung gestärkt werden, damit alle von ihrer Arbeit gut leben können', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', null, '2026-10-08', true),
  (12, 17, null, 'ja', 'Will den gesetzlichen Mindestlohn unverzüglich auf 15 Euro anheben.', 'Wir wollen den gesetzlichen Mindestlohn unverzüglich auf 15 Euro anheben.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, '2026-10-08', true),
  (12, 18, null, 'ja', 'Will den Mindestlohn auf 60 % des Medianbruttolohns erhöhen, derzeit 14,61 Euro, und regelmäßig anpassen.', 'Der Mindestlohn wird auf 60 % des Medianbruttolohns erhöht, was derzeit (Stand 2024) 14,61 Euro entspricht, und regelmäßig angepasst.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=89', null, '2026-10-08', true),
  (13, 11, null, 'ja', 'Will an der grundgesetzlichen Schuldenbremse festhalten, damit Lasten nicht künftigen Generationen aufgebürdet werden.', 'An der grundgesetzlichen Schuldenbremse festhalten. Sie stellt sicher, dass Lasten nicht unseren Kindern und Enkeln aufgebürdet werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', null, '2026-10-08', true),
  (13, 12, null, 'teils', 'Will die Schuldenregel im Grundgesetz so reformieren, dass Zukunftsinvestitionen nicht behindert werden.', 'Die aktuelle Schuldenregel ist nicht auf die Herausforderungen unserer Zeit und der Zukunft ausgelegt. Deshalb wollen wir die Schuldenregel im Grundgesetz so reformieren, dass Investitionen in die Zukunftsfähigkeit unseres Landes und in den Wohlstand nicht behindert werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=17', null, '2026-10-08', true),
  (13, 13, null, 'teils', 'Will die Schuldenbremse im Einklang mit europäischen Regeln reformieren und Kredite im Umfang staatlicher Investitionen erlauben.', 'Um die notwendigen Investitionen in Infrastruktur, in die Dekarbonisierung unseres Landes und in eine starke, zukunftsfähige Wirtschaft zu finanzieren, wollen wir die Schuldenbremse im Einklang mit den europäischen Regeln reformieren. Die Aufnahme von staatlichen Krediten soll dazu in dem Umfang ermöglicht werden, wie vom Staat Investitionen getätigt werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=36', null, '2026-10-08', true),
  (13, 14, null, 'ja', 'Sieht die Einhaltung der Schuldenbremse im Grundgesetz als zentrales Gebot der Generationengerechtigkeit.', 'Daher ist für uns Freie Demokraten die Einhaltung der im Grundgesetz verankerten Schuldenbremse zentrales Gebot der Generationengerechtigkeit.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, '2026-10-08', true),
  (13, 15, null, 'ja', 'Will die Schuldenbremse im Grundgesetz einhalten und lehnt jede Aufweichung entschieden ab.', 'Die im Grundgesetz festgeschriebene Schuldenbremse ist einzuhalten. Die AfD lehnt jedwede Aufweichung der Schuldenbremse entschieden ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=55', null, '2026-10-08', true),
  (13, 16, null, 'nein', 'Fordert die Abschaffung der Schuldenbremse, um Investitionen in Infrastruktur, klimaneutrale Industrie und sozialen Ausgleich über Kredite zu finanzieren.', 'Wir fordern die Abschaffung der Schuldenbremse. Es muss wieder möglich sein, öffentliche Investitionen in die Infrastruktur, eine klimaneutrale Industrie und den sozialen Ausgleich über Kredite zu finanzieren.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', null, '2026-10-08', true),
  (13, 17, null, 'teils', 'Will die Schuldenbremse reformieren und Investitionen in Brücken, Straßen, Schienen, Schulen, Wohnungen und Netze ausklammern.', 'Die Schuldenbremse hat unsolides Haushalten nicht verhindert, sondern ist zur Investitionsbremse geworden. Deshalb muss sie reformiert werden. […] Wir wollen Investitionen in Brücken, Straßen, Schienen, Schulen, Wohnungen und Netze aus der Schuldenbremse ausklammern', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, '2026-10-08', true),
  (13, 18, null, 'teils', 'Will die Schuldenbremse reformieren, weil sie Investitionen in Infrastruktur, Bildung, Klimaschutz und Digitalisierung einschränkt.', 'Die starre deutsche Schuldenbremse schränkt jedoch wichtige Zukunftsinvestitionen in Infrastruktur, Bildung, Klimaschutz und Digitalisierung massiv ein. Eine Reform der Schuldenbremse ermöglicht eine nachhaltige und wirtschaftlich kluge Finanzpolitik, die heutige und künftige Generationen stärkt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=22', null, '2026-10-08', true),
  (14, 11, null, 'nein', 'Will an der bestehenden gesetzlichen Regelung zum Renteneintrittsalter festhalten und Rentenkürzungen verhindern.', 'Wir halten an der bestehenden gesetzlichen Regelung zum Renteneintrittsalter fest. Rentenkürzungen wird es mit uns nicht geben.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=5', null, '2026-10-08', true),
  (14, 12, null, 'nein', 'Will den abschlagsfreien Renteneintritt nach 45 Beitragsjahren zwei Jahre früher erhalten und lehnt eine Anhebung der Regelaltersgrenze ab.', 'Ein abschlagsfreier Renteneintritt nach 45 Beitragsjahren wird mit der SPD auch künftig zwei Jahre früher möglich bleiben. Das haben sich gerade Menschen verdient, die früh begonnen haben zu arbeiten. Eine Anhebung der Regelaltersgrenze lehnen wir ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=25', null, '2026-10-08', true),
  (14, 13, null, 'teils', 'Will an der Rente mit 67 festhalten und Anreize schaffen, freiwillig länger zu arbeiten, auch über die Regelaltersgrenze hinaus.', 'Wir halten an der Rente mit 67 fest. Aber wir schaffen Anreize und machen es den Menschen leichter, länger zu arbeiten, wenn sie dies wollen, auch über die Regelaltersgrenze hinaus.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=98', null, '2026-10-08', true),
  (14, 14, null, 'teils', 'Will einen flexiblen Renteneintritt nach schwedischem Vorbild: Menschen entscheiden selbst, später gehen bringt höhere, früher gehen niedrigere Rente.', 'Wir Freie Demokraten stehen für einen wirklich flexiblen Renteneintritt. Die Menschen sollen nach schwedischem Vorbild künftig selbst entscheiden, wann der Ruhestand beginnt, sofern dann keine Sozialleistungen beantragt werden müssen. Je später jemand in Rente geht, desto höher die Rente - wer früher geht, bekommt eine niedrigere Rente.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, '2026-10-08', true),
  (14, 15, null, 'teils', 'Will Verrentung flexibler gestalten, Anreize für freiwillig längere Lebensarbeitszeit setzen und abschlagsfreien Eintritt nach 45 Arbeitsjahren ermöglichen.', 'Wir wollen der Rentenversicherung mehr Beitragszahler zuführen, die Verrentung flexibler und gerechter gestalten und Anreize für eine freiwillige Verlängerung der Lebensarbeitszeit setzen, indem wir: [...] ein flexibles Renteneintrittsalter, abschlagsfrei nach 45 beitragsberechtigten Arbeitsjahren, ermöglichen', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=19', null, '2026-10-08', true),
  (14, 16, null, 'nein', 'Fordert eine Regelaltersgrenze von 65 Jahren, weil die Rente ab 67 Kürzungen bedeute.', 'Die Rente erst ab 67 bedeutet Rentenkürzungen für alle, insbesondere in Berufen, in denen Erwerbstätige nicht so lange durchhalten können. Wir fordern eine Regelaltersgrenze von 65 Jahren.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, '2026-10-08', true),
  (14, 17, null, 'nein', 'Erteilt Forderungen nach einer weiteren Erhöhung des Renteneintrittsalters eine klare Absage.', 'Forderungen, das Renteneintrittsalter weiter zu erhöhen, erteilen wir eine klare Absage.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=23', null, '2026-10-08', true),
  (14, 18, null, 'ja', 'Will das Renteneintrittsalter an die durchschnittliche Lebenserwartung anpassen.', 'Dynamisches Renteneintrittsalter: Das Renteneintrittsalter wird an die durchschnittliche Lebenserwartung angepasst, um ein faires Verhältnis zwischen Anspar- und Auszahlungsphase zu gewährleisten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=92', null, '2026-10-08', true),
  (15, 11, null, 'nein', 'Setzt auf Ernährungsbildung und Information statt auf Lenkungssteuern und Werbeverbote.', 'Wir setzen auf Ernährungsbildung und gute Information, aber nicht auf unwirksame Werbeverbote oder Lenkungssteuern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=37', null, '2026-10-08', true),
  (15, 12, null, 'ja', 'Will eine Herstellerabgabe für zuckerhaltige Getränke und verbindliche Reduktionsziele für Zucker, Salz und Fett.', 'Um den Zucker-, Salz- und Fettgehalt in unseren Lebensmitteln zu reduzieren, legen wir verbindliche Ziele fest und setzen ökonomische Anreize für weniger gesundheitsschädliche Produkte – über eine Herstellerabgabe für zuckerhaltige Getränke.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', null, '2026-10-08', true),
  (15, 13, null, 'keine_aussage', null, null, null, 'Kapitel Gesundheit/Ernährung (S. 60) gelesen, Suche nach Zucker, Softdrink, Abgabe, Herstellerabgabe, Steuer, Ernährung: nur ''wirksame Maßnahmen zum Senken des Zuckergehalts von Softdrinks'' und Bürgerrat-Empfehlungen, weder Steuer noch Abgabe noch Ablehnung genannt.', '2026-10-08', true),
  (15, 14, null, 'nein', 'Lehnt neue Lenkungsabgaben, etwa auf Zucker, und Eingriffe in Rezepturen ab.', 'Eingriffe in Rezepturen lehnen wir ab, ebenso neue Lenkungsabgaben z. B. auf Zucker.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=46', null, '2026-10-08', true),
  (15, 15, null, 'nein', 'Lehnt jede gesonderte Lebensmittelbesteuerung ab, auch eine Zuckersteuer.', 'Deshalb lehnen wir jede Form der gesonderten Lebensmittelbesteuerung ab, wie z. B. eine Fleisch- oder Zuckersteuer.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=75', null, '2026-10-08', true),
  (15, 16, null, 'keine_aussage', null, null, null, 'Ernährungsabschnitt (S. 6, 42) gelesen; Suche nach Zucker, Softdrink, Getränke, Steuer auf, Abgabe: nur Begrenzung des Zuckergehalts in Softdrinks ohne Steuer oder Abgabe (S. 42), Zuckerfest (S. 50) irrelevant.', '2026-10-08', true),
  (15, 17, null, 'keine_aussage', null, null, null, 'Ernährungsabschnitt (S. 33) gelesen; Suche nach Zucker, Getränk, Softdrink, Abgabe: nichts zu einer Zuckersteuer.', '2026-10-08', true),
  (15, 18, null, 'ja', 'Will eine Lenkungssteuer auf Zucker und Süßungsmittel, 25 Cent auf alkoholfreie Getränke mit mehr als 3 g Zucker pro 100 ml.', 'Steuer auf Zuckerprodukte: Einführung einer gesundheitspolitisch motivierten Steuer auf Zucker, Zuckerersatzstoffe und Süßungsmittel als besondere Verbrauchs- und Lenkungssteuer. […] Die Steuer beträgt 25 Cent auf alkoholfreie Getränke mit mehr als 3 g Zucker pro 100 ml, einschließlich Light- und Zero-Produkte sowie Energydrinks.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=131', null, '2026-10-08', true),
  (16, 11, null, 'ja', 'Steht ohne Wenn und Aber zur NATO als Garant von Frieden, Freiheit und Sicherheit.', 'Wir stehen ohne Wenn und Aber zur transatlantischen Verteidigungsallianz. Sie garantiert der Bundesrepublik seit mehr als 75 Jahren Frieden, Freiheit und Sicherheit. […] Ohne Wenn und Aber zur NATO stehen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=52', null, '2026-10-08', true),
  (16, 12, null, 'ja', 'Hält die NATO für die europäische Sicherheit für unverzichtbar.', 'Die NATO ist ein tragender Pfeiler der transatlantischen Partnerschaft und für die europäische Sicherheit unverzichtbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=57', null, '2026-10-08', true),
  (16, 13, null, 'ja', 'Sieht die eigene Sicherheit in EU und NATO eingebettet, will den europäischen Pfeiler stärken und steht zu Bündnisverpflichtungen.', 'Unsere Sicherheit ist eingebettet in der EU und der NATO. Wir stärken den europäischen Pfeiler der NATO. […] Wir stehen zu unseren Bündnisverpflichtungen und dem damit verbundenen notwendigen Ausbau unserer Fähigkeiten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=152', null, '2026-10-08', true),
  (16, 14, null, 'ja', 'Steht uneingeschränkt zur NATO als Garant der eigenen Sicherheit.', 'Wir Freie Demokraten stehen uneingeschränkt zur NATO als das erfolgreichste Verteidigungsbündnis der Welt und als Garant für unsere Sicherheit.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=48', null, '2026-10-08', true),
  (16, 15, null, 'teils', 'Will die NATO-Mitgliedschaft nur bis zum Aufbau eines unabhängigen europäischen Militärbündnisses beibehalten.', 'Bis zum Aufbau eines unabhängigen und handlungsfähigen europäischen Militärbündnisses bleiben die Mitgliedschaft in der NATO sowie eine aktive Rolle Deutschlands in der Organisation für Sicherheit und Zusammenarbeit in Europa (OSZE) zentrale Elemente', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=88', null, '2026-10-08', true),
  (16, 16, null, 'teils', 'Will eine gesamteuropäische Sicherheitsarchitektur auf Grundlage der KSZE, die die NATO überflüssig macht.', 'Unser Ziel ist eine Sicherheitsarchitektur in Europa, die auf den Prinzipien der friedlichen Koexistenz und den Vereinbarungen der KSZE beruht und alle Länder des Kontinents einbezieht. Eine solche Sicherheitsarchitektur macht die NATO überflüssig und ermöglicht eine Außenpolitik der internationalen Kooperation anstelle von wirtschaftlicher und militärischer Konkurrenz.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=22', null, '2026-10-08', true),
  (16, 17, null, 'teils', 'Will statt eines geopolitischen Machtinstruments ein defensives Verteidigungsbündnis, das Abrüstung anstrebt und Mitglieder auf Augenhöhe stellt.', 'Statt eines Machtinstruments für geopolitische Ziele brauchen wir ein defensiv ausgerichtetes Verteidigungsbündnis, das die Grundsätze der UN-Charta achtet, Abrüstung anstrebt, statt zu Aufrüstung zu verpflichten, und in dem sich die Mitglieder auf Augenhöhe begegnen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=5', null, '2026-10-08', true),
  (16, 18, null, 'teils', 'Will die NATO reformieren, mit qualifizierten Mehrheitsentscheidungen gegen politische Instabilität einzelner Mitglieder.', 'Reform der NATO: Die NATO wird reformiert, um qualifizierte Mehrheitsentscheidungen und Stabilität vor politischer Instabilität einzelner Mitglieder zu gewährleisten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=40', null, '2026-10-08', true),
  (18, 11, null, 'keine_aussage', null, null, null, 'Treffer S. 20, 24, 38, 47, 50, 52 gelesen (Russland nur als Bedrohung/Sicherheitslage), Kapitel Energie (ca. S. 21-23) und Außenwirtschaft gelesen, Suche nach Gas, Erdgas, LNG, Pipeline, Nord Stream, Lieferant, Diversifizierung: keine Aussage zu russischem Gas.', '2026-10-08', true),
  (18, 12, null, 'nein', 'Hebt hervor, Deutschland schnell von russischem Gas unabhängig gemacht zu haben.', 'Die explodierenden Energiepreise infolge des Kriegs gegen die Ukraine haben wir unter Kontrolle gebracht – und Deutschland schnell unabhängig gemacht von russischem Gas.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=4', null, '2026-10-08', true),
  (18, 13, null, 'keine_aussage', null, null, null, 'Energiekapitel (S. 43) und Außenpolitik (S. 104-105, 142-145) gelesen, Suche nach Russland, Gasimport, LNG, Gasunabhängigkeit, Sanktionen: nur Absage an neue Langfristverträge für Gasimport allgemein und Ausweitung der Sanktionen auf die Atomwirtschaft; russisches Erdgas wird nicht ausdrücklich behandelt.', '2026-10-08', true),
  (18, 14, null, 'nein', 'Lehnt eine Rückkehr zur Abhängigkeit von russischer Energie ab und will einen EU-weiten Ausstiegsplan aus russischen Energiekäufen.', 'Es gibt kein Zurück zum Status Quo vor dem Angriffskrieg gegen die Ukraine. Dies betrifft insbesondere die Abhängigkeit von russischer Energie. Wir Freie Demokraten einen EU-weiten Ausstiegsplan aus russischen Energiekäufen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=49', null, '2026-10-08', true),
  (18, 15, null, 'ja', 'Will die Wirtschaftssanktionen gegen Russland sofort aufheben und die Nord-Stream-Leitungen instand setzen.', 'Zur Wiederherstellung des ungestörten Handels mit Russland gehören die sofortige Aufhebung der Wirtschaftssanktionen gegen Russland sowie die Instandsetzung der Nord Stream-Leitungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=93', null, '2026-10-08', true),
  (18, 16, null, 'keine_aussage', null, null, null, 'Kapitel Energie (S. 32–34) und Frieden/Außenpolitik (S. 21–24) gelesen; Suche nach Russland, russisch, Erdgas, LNG, Gasimport, Sanktionen: Erdgasausstieg bis 2035 und kein Fracking-LNG, aber keine Aussage zu Gasbezug aus Russland.', '2026-10-08', true),
  (18, 17, null, 'ja', 'Will mit Russland verhandeln, um über Nord Stream wieder Erdgas zu beziehen, und die zerstörten Stränge wiederherstellen.', 'Die Bundesregierung sollte mit Russland verhandeln, um über den verbliebenen Strang der Nord-Stream-Pipeline wieder günstiges Erdgas zu beziehen. Sie sollte außerdem eine Wiederherstellung der zerstörten Stränge angehen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, '2026-10-08', true),
  (18, 18, null, 'keine_aussage', null, null, null, 'Kapitel Ukraine-Krieg (S. 45–46) und Energie (S. 65–68) gelesen; Suche nach Gas, Erdgas, LNG, Russland, Sanktionen: nur allgemeine Sanktionen gegen Russland, nichts zu Gasimporten.', '2026-10-08', true),
  (19, 11, null, 'ja', 'Will das Euro-Währungssystem stabil halten, Deutschland soll Stabilitätsanker der Euro-Zone bleiben.', 'Wir setzen alles daran, neue Krisen zu vermeiden, unseren Finanzstandort leistungsfähiger zu machen und das Euro-Währungssystem stabil zu halten. Deutschland muss als größte Volkswirtschaft der Euro-Zone deren Stabilitätsanker bleiben.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=78', null, '2026-10-08', true),
  (19, 12, null, 'ja', 'Will eine europäische Arbeitslosenrückversicherung, um die Eurozone vor schweren Krisen zu schützen.', 'Um die Eurozone vor ökonomischen Schocks zu schützen, treten wir für eine europäische Arbeitslosenrückversicherung ein, die in Zeiten schwerer wirtschaftlicher Krisen greift.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', null, '2026-10-08', true),
  (19, 13, null, 'keine_aussage', null, null, null, 'Treffer S. 21, 36, 136 gelesen sowie Suche nach Euro, Währung, Währungsunion, Eurozone, Fiskalregeln: nur beiläufig ''gemeinsame Währung'' und europäische Fiskalregeln, keine Aussage zu Euro behalten oder austreten.', '2026-10-08', true),
  (19, 14, null, 'ja', 'Will strenge Schuldenregeln einhalten, damit die Währungsunion nicht scheitert.', 'Wir haben in der Vergangenheit für strenge Schuldenregeln gekämpft. Wenn wir uns nicht an die Regeln halten, wird die Währungsunion scheitern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=36', null, '2026-10-08', true),
  (19, 15, null, 'nein', 'Will die Transferunion aufkündigen und eine nationale Währung wieder einführen, gegebenenfalls mit parallelem Euro oder ECU-ähnlicher Verrechnungseinheit.', 'Deshalb muss Deutschland diese „Transferunion“ aufkündigen und den Irrweg der Dauerrettung durch Wiedereinführung einer nationalen Währung beenden, ggf. unter paralleler Beibehaltung des Euro oder einer flexiblen ECU-ähnlichen Verrechnungseinheit.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=63', null, '2026-10-08', true),
  (19, 16, null, 'keine_aussage', null, null, null, 'Kapitel Finanzen/EZB (S. 13–14) gelesen; Suche nach Euro, Währung, Währungsunion, Eurozone, EZB: nur Demokratisierung der EZB, digitaler Euro, Währung als staatliche Souveränität; nichts zu Beibehaltung oder Austritt.', '2026-10-08', true),
  (19, 17, null, 'keine_aussage', null, null, null, 'Suche nach Euro, Währung, EZB, Zentralbank, Währungsunion: nur Geldbeträge und Europa/EU-Kritik (S. 12-13), keine Aussage zum Euro als Währung.', '2026-10-08', true),
  (19, 18, null, 'keine_aussage', null, null, null, 'Kapitel Finanzen, EU-Binnenmarkt (S. 58) durchsucht nach Euro, Währung, Eurozone, Zentralbank, Währungsunion: keine Aussage zum Euro als Währung.', '2026-10-08', true),
  (20, 11, null, 'keine_aussage', null, null, null, 'Energiekapitel S. 21 und Landwirtschaft S. 36-37 gelesen, Suche nach Freifläche, Photovoltaik, Agri-PV, Solarpark, Acker, Dachfläche: nur Solarenergie in Aufzählung, Ausverkauf von Ackerland an Investoren und allgemein Mehrfachnutzung von Flächen (S. 26), nichts zu Solaranlagen auf Äckern.', '2026-10-08', true),
  (20, 12, null, 'keine_aussage', null, null, null, 'Energie- und Naturschutzkapitel (S. 33-34, 52-54) gelesen; Suche nach Photovoltaik, Freifläche, Acker, Agri-PV, Solar, Flächenplanung: nur Balkonkraftwerk/Energy Sharing und allgemeine Flächenplanung ohne Aussage zu Solaranlagen auf Äckern.', '2026-10-08', true),
  (20, 13, null, 'teils', 'Will Vorrangflächen für Nahrungsmittelproduktion im Planungsrecht und Agri-Photovoltaik stärken.', 'Wir brauchen auch einen sorgsameren Umgang mit wertvollen Agrarflächen. Daher wollen wir im Planungsrecht Vorrangflächen für die Nahrungsmittelproduktion einführen und Agri-Photovoltaik und weitere Ansätze zu höherer Flächeneffizienz stärken.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=60', null, '2026-10-08', true),
  (20, 14, null, 'keine_aussage', null, null, null, 'Kapitel Energie (S. 17-18) und Unternehmerische Landwirtschaft (S. 45-46) gelesen; Suche nach solar, photovolt, freifl, agri, acker, fläche: nur EEG-Marktintegration von Photovoltaik und Windkraft (S. 18), nichts zu Flächen oder Äckern.', '2026-10-08', true),
  (20, 15, null, 'nein', 'Lehnt den Neubau von Photovoltaik als Agro-PV auf landwirtschaftlichen Nutzflächen wegen hohen Flächenverbrauchs ab.', 'Den Neubau von Photovoltaikanlagen als Agro-PV auf landwirtschaftlichen Nutzflächen lehnen wir aufgrund ihres hohen Flächenverbrauchs ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=81', null, '2026-10-08', true),
  (20, 16, null, 'keine_aussage', null, null, null, 'Kapitel Energie (S. 32–33) gelesen; Suche nach Solar, Photovoltaik, PV, Freifläche, Acker, Agri, Dach: Solarpflicht auf Dächern und Bonus für PV-Großflächenanlagen für Kommunen (S. 33), aber nichts zu Ackerflächen.', '2026-10-08', true),
  (20, 17, null, 'nein', 'Gibt dem Erhalt von Agrarflächen Priorität und will nicht, dass Photovoltaik die agrarische Nutzung verdrängt.', 'Der Erhalt von Agrarflächen hat für uns Priorität. […] Photovoltaikanlagen dürfen die agrarische Nutzung nicht verdrängen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=20', null, '2026-10-08', true),
  (20, 18, null, 'keine_aussage', null, null, null, 'Kapitel Energie (S. 66) und Landwirtschaft (S. 81–82) gelesen; Suche nach Photovoltaik, Freifläche, Agri-PV, Ackerland: nur PV-Pflicht auf Gebäuden, nichts zu Freiflächenanlagen auf Äckern.', '2026-10-08', true),
  (21, 11, null, 'nein', 'Will Ausreisepflicht abgelehnter Asylbewerber staatlich durchsetzen und per Gesetz mehr Rückführungen erreichen.', 'Asylbewerber ohne Schutzberechtigung müssen unser Land wieder verlassen. Wenn dies nicht freiwillig geschieht, muss die Ausreisepflicht staatlich durchgesetzt werden. Wir erarbeiten ein umfassendes Gesetz, um die Zahl der Rückführungen zu steigern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, '2026-10-08', true),
  (21, 12, null, 'teils', 'Will abgelehnten Geflüchteten, die in Arbeitsmarkt und Gesellschaft integriert und straffrei sind, den Spurwechsel in die Fachkräfteeinwanderung ermöglichen.', 'Wer als Geflüchteter keinen Schutzstatus erhalten hat und dennoch Integration in Arbeitsmarkt und Gesellschaft bewältigt und straffrei ist, dem soll der Spurwechsel in die Fachkräfteeinwanderung ermöglicht werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, '2026-10-08', true),
  (21, 13, null, 'teils', 'Sieht das Chancenaufenthaltsrecht als beispielgebend und will weitere Reformen folgen lassen.', 'Mit dem Chancenaufenthaltsrecht haben wir viele gut integrierte Menschen aus der Duldung geholt, ihnen eine echte Bleibeperspektive gegeben und gleichzeitig die Ausländerbehörden stark entlastet. Es ist beispielgebend, weitere Reformen müssen folgen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=127', null, '2026-10-08', true),
  (21, 14, null, 'teils', 'Will gut integrierten Schutzsuchenden einen Spurwechsel in den Arbeitsmarkt ermöglichen, wenn sie mit Familie ohne Transferleistungen leben können.', 'Für gut integrierte Schutzsuchende muss es die Möglichkeit eines Spurwechsels zur Einwanderung in den Arbeitsmarkt geben, wenn sie so qualifiziert sind, dass sie und ihre Familien von eigener Arbeit ohne Transferleistungen leben können.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, '2026-10-08', true),
  (21, 15, null, 'nein', 'Will alle Bleiberechtsregelungen für Ausreisepflichtige abschaffen, auch Ausbildungs-, Beschäftigungsduldung und Chancenaufenthaltsrecht, und die Duldung ersetzen.', 'Abschaffung aller Bleiberechtsregelungen für ausreisepflichtige Personen, insbesondere auch der Ausbildungs- und Beschäftigungsduldung und des Chancenaufenthaltsrechts  Ersatz der Duldung durch eine Bescheinigung über die Ausreisepflicht', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=108', null, '2026-10-08', true),
  (21, 16, null, 'ja', 'Will Legalisierungsmöglichkeiten für Menschen ohne Aufenthaltsstatus und effektive Bleiberechtsregelungen für Menschen in Kettenduldungen.', 'Wir fordern Legalisierungsmöglichkeiten für Menschen ohne Aufenthaltsstatus und effektive Bleiberechtsregelungen für Menschen, die mit einem unsicheren Aufenthaltsstatus oder mit Kettenduldungen leben müssen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, '2026-10-08', true),
  (21, 17, null, 'keine_aussage', null, null, null, 'Migrationskapitel (S. 36-38) gelesen; Suche nach Bleiberecht, Duldung, Geduldete, Stichtag: nur Hinweis, Behörden sollen sich auf nicht integrierte Ausreisepflichtige konzentrieren und Ausreise Nichtberechtigter durchsetzen; kein Bleiberecht für Geduldete.', '2026-10-08', true),
  (21, 18, null, 'ja', 'Will Personen, deren Abschiebung drei Jahre nicht vollzogen wurde, bei Integrationsbereitschaft einen dauerhaften Aufenthaltsstatus ermöglichen.', 'Aufenthaltsstatus nach drei Jahren: Personen, bei denen eine Abschiebung innerhalb von drei Jahren nicht vollzogen wurde, können einen dauerhaften Aufenthaltsstatus erhalten, wenn sie die Abschiebung nicht aktiv verhindert und durch Integrationsmaßnahmen ihre Bereitschaft zur gesellschaftlichen Teilhabe gezeigt haben.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=139', null, '2026-10-08', true),
  (24, 11, null, 'ja', 'Will eine EU, die sich auf besser europäisch lösbare Aufgaben konzentriert und nationalstaatlich getragen ist.', 'Die EU muss sich auf jene Aufgaben konzentrieren, die auf europäischer Ebene besser als auf nationaler erfüllt werden können. Unser Ziel ist ein Europa, das regional verwurzelt, nationalstaatlich getragen und europäisch legitimiert ist.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=54', null, '2026-10-08', true),
  (24, 12, null, 'ja', 'Will die EU schneller und geeinter zu einer starken, solidarischen Gemeinschaft weiterentwickeln.', 'In den kommenden Jahren werden wir diesen wichtigen Motor nutzen, um neue Wege in der EU schneller und geeinter zu beschreiten und die EU zu einer starken und solidarischen Gemeinschaft weiterzuentwickeln.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=60', null, '2026-10-08', true),
  (24, 13, null, 'ja', 'Will per Verfassungskonvent die EU-Verträge ändern, Ziel ist eine Föderale Europäische Republik mit eigener Verfassung.', 'Eine Reihe der Reformvorschläge, für die wir eintreten, bedarf einer Änderung der EU-Verträge. Deswegen wollen wir uns dafür einsetzen, einen Verfassungskonvent einzuberufen. Unsere Vision ist eine Föderale Europäische Republik mit eigener Verfassung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=144', null, '2026-10-08', true),
  (24, 14, null, 'ja', 'Sieht die EU als Erfolgsgeschichte und will sie durch Reformen sichern und fortschreiben.', 'Die Europäische Union ist eine einzigartige Erfolgsgeschichte. Sie hat den Menschen in den Mitgliedstaaten Frieden, Freiheit, Sicherheit, Fortschritt und Wohlstand gebracht. Diese Erfolgsgeschichte müssen wir jetzt durch mutige Reformen sichern und fortschreiben.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=51', null, '2026-10-08', true),
  (24, 15, null, 'nein', 'Will die EU durch einen neu zu gründenden „Bund europäischer Nationen“ mit gewahrter Souveränität der Mitgliedstaaten ersetzen.', 'Daher streben wir einen „Bund europäischer Nationen“ an, eine neu zu gründende europäische Wirtschafts- und Interessengemeinschaft, in der die Souveränität der Mitgliedstaaten gewahrt ist […] Der Übergang von der Europäischen Union in den Bund europäischer Nationen soll entschlossen und planvoll erfolgen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=141', null, '2026-10-08', true),
  (24, 16, null, 'ja', 'Will grundlegende EU-Reform durch neue Verträge, die die Logik des Neoliberalismus hinter sich lassen.', 'Die Reform der EU ist auch eine friedenspolitische Notwendigkeit. Doch die Möglichkeiten einer grundlegenden Reform der EU sind durch die bestehenden Verträge der EU begrenzt. Wir streben deshalb neue Verträge an, die die Logik des Neoliberalismus hinter sich lassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=24', null, '2026-10-08', true),
  (24, 17, null, 'teils', 'Will enge Zusammenarbeit der europäischen Staaten, aber keine tiefere Integration und eine Rückverlagerung von Kompetenzen an die Mitgliedstaaten.', 'Wir stehen für eine enge Zusammenarbeit der europäischen Staaten, aber nicht für eine immer tiefer gehende Integration in Richtung eines europäischen Bundesstaats. […] Wir wollen keine weitere Zentralisierung von Macht bei der EU-Kommission, sondern eine Rückverlagerung von Kompetenzen in die Mitgliedstaaten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=8', null, '2026-10-08', true),
  (24, 18, null, 'ja', 'Will ein starkes, föderales Europa und ist bereit für eine föderale europäische Republik.', 'Auch Deutschland profitiert unmittelbar von einem starken, föderalen Europa, das Stabilität, wirtschaftliche Chancen und Sicherheit garantiert. [...] Wir sind bereit für eine föderale europäische Republik, die nationale Interessen überwindet, die Bürgerschaft stärkt und Demokratie, Rechtsstaatlichkeit sowie Vielfalt schützt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=9', null, '2026-10-08', true),
  (25, 11, null, 'nein', 'Will die Freibeträge bei der Erbschaftsteuer deutlich erhöhen, damit das Eigenheim stärker steuerfrei vererbt werden kann.', 'Eigenheim günstiger vererben. Wir erhöhen die Freibeträge bei der Erbschaftsteuer deutlich. So kann das Eigenheim in höherem Maße steuerfrei vererbt werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=34', null, '2026-10-08', true),
  (25, 12, null, 'nein', 'Will die Privilegierung großer Unternehmensvermögen beenden und eine effektive Mindestbesteuerung für große Betriebsvermögen einführen.', 'Die Erbschaft- und Schenkungsteuer in ihrer heutigen Form ist nicht gerecht, denn die übermäßige Privilegierung großer Unternehmensvermögen führt dazu, dass bei der Übertragung solcher Multimillionen- oder Milliardenvermögen oftmals nur sehr wenig oder gar keine Steuern gezahlt werden. Diese Ungerechtigkeit wollen wir abschaffen. Innerhalb des bestehenden progressiven Steuertarifs führen wir eine effektive Mindestbesteuerung für große Betriebsvermögen ein […]', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', null, '2026-10-08', true),
  (25, 13, null, 'nein', 'Will eine Erbschaftsteuer mit personenbezogenem Lebensfreibetrag, ohne Ausnahmen für sehr große Erbschaften, selbst bewohntes Eigentum befreit.', 'eine Reform der Erbschaftssteuer hin zu einem Modell mit personenbezogenem Lebensfreibetrag, weitgehender Streichung bestehender Ausnahmen für außerordentlich große Erbschaften (selbst bewohntes Eigentum bleibt befreit) und großzügigen Stundungsregelungen', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', null, '2026-10-08', true),
  (25, 14, null, 'nein', 'Will Freibeträge der Erbschaft- und Schenkungsteuer automatisch an die Inflation anpassen; Unternehmen sollen durch sie nicht gefährdet werden.', 'Die Existenz von Unternehmen darf nicht durch die Erbschaft- und Schenkungsteuer gefährdet sein. Wir fordern, dass die Freibeträge automatisch um die Inflationsrate erhöht werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, '2026-10-08', true),
  (25, 15, null, 'ja', 'Will die Erbschaftsteuer und die ausgesetzte Vermögensteuer abschaffen.', 'Die AfD will die derzeit zur Erhebung ausgesetzte Vermögensteuer sowie die Erbschaftssteuer abschaffen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=61', null, '2026-10-08', true),
  (25, 16, null, 'nein', 'Will für Superreiche höhere Steuersätze und niedrigere Freibeträge bei Erbschaften und Schenkungen, einheitlich 200.000 Euro Freibetrag.', 'Für diese Superreichen sollen die Steuersätze für Erbschaften und Schenkungen erhöht und die persönlichen Freibeträge heruntergesetzt werden. [...] Wir fordern einheitliche Freibeträge von 200.000 Euro.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, '2026-10-08', true),
  (25, 17, null, 'nein', 'Will alle vererbten Vermögen oberhalb der Freibeträge gleich besteuern.', 'Das wollen wir verändern und alle vererbten Vermögen oberhalb der Freibeträge gleich besteuern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, '2026-10-08', true),
  (25, 18, null, 'nein', 'Will die Zehnjahresfrist abschaffen und Erbschaften und Schenkungen über die Zeit aufsummiert progressiv besteuern.', 'Eine gerechtere Ausgestaltung der Erbschaft- und Schenkungsteuer reduziert die extreme Konzentration von Vermögen und generiert ein höheres Steueraufkommen. [...] Aufsummierte Besteuerung: Die Zehnjahresfrist wird abgeschafft, sodass Erbschaften und Schenkungen über die Zeit hinweg aufsummiert und progressiv besteuert werden.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=100', null, '2026-10-08', true),
  (26, 11, null, 'nein', 'Will § 218 beibehalten und steht zur geltenden Rechtslage als gesellschaftlichem Kompromiss.', 'Paragraf 218 bleibt. Die geltende Rechtslage zum Schwangerschaftsabbruch bildet einen mühsam gefundenen gesellschaftlichen Kompromiss ab, der das Selbstbestimmungsrecht der Frau und den Schutz des ungeborenen Kindes berücksichtigt. Zu dieser Rechtslage stehen wir.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=64', null, '2026-10-08', true),
  (26, 12, null, 'ja', 'Will Schwangerschaftsabbrüche entkriminalisieren, außerhalb des Strafrechts regeln und zur medizinischen Grundversorgung machen.', 'Wir werden Schwangerschaftsabbrüche entkriminalisieren und außerhalb des Strafrechts regeln – außer wenn sie gegen oder ohne den Willen der Schwangeren erfolgen. Wir wollen Schwangerschaftsabbrüche zu einem Teil der medizinischen Grundversorgung machen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, '2026-10-08', true),
  (26, 13, null, 'ja', 'Will Abbrüche außerhalb des Strafrechts regeln, in der Frühphase rechtmäßig stellen und für die mittlere Phase einen gesetzlichen Rahmen schaffen.', 'Wir wollen, dass selbstbestimmte Schwangerschaftsabbrüche nicht mehr in § 218 des Strafgesetzbuches kriminalisiert, sondern grundsätzlich außerhalb des Strafrechts geregelt werden. Entsprechend den Empfehlungen der Fachkommission zur reproduktiven Selbstbestimmung, soll in der Frühphase einer Schwangerschaft der Abbruch rechtmäßig sein und für die mittlere Phase ein gesetzlicher Rahmen geschaffen werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=120', null, '2026-10-08', true),
  (26, 14, null, 'teils', 'Will eine Reform von §§ 218, 218a StGB über fraktionsübergreifende Gruppenanträge mit Gewissensfreiheit im Bundestag beraten lassen.', 'Eine Reform der Regelungen zum Schwangerschaftsabbruch (§§218, 218a StGB) soll im Wege von sog. fraktionsübergreifenden Gruppenanträgen mit Gewissensfreiheit für jede Abgeordnete und jeden Abgeordneten im nächsten Bundestag beraten werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', null, '2026-10-08', true),
  (26, 15, null, 'nein', 'Hält §§ 218 ff. StGB für ausgewogen, will keine Änderung, nur konsequente Umsetzung samt Pflichtberatung.', 'Aus Sicht der AfD sind die Regelungen der §218 ff StGB ausgewogen und bedürfen keiner Änderung, lediglich einer konsequenten Umsetzung. Insbesondere ist vor der Abtreibung eine rechtskonforme Beratung lt. §219 StGB erforderlich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=150', null, '2026-10-08', true),
  (26, 16, null, 'ja', 'Will § 218 StGB ersatzlos streichen, die Versorgung ungewollt Schwangerer verbessern und Beratung freiwillig statt verpflichtend machen.', '§ 218 StGB muss ersatzlos gestrichen werden. Die Versorgungslage ungewollt Schwangerer muss deutschlandweit verbessert werden. Beratungsangebote müssen freiwillig statt verpflichtend sein.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=46', null, '2026-10-08', true),
  (26, 17, null, 'teils', 'Fordert grundsätzliche Straffreiheit des Schwangerschaftsabbruchs bis zur 12. Woche.', 'Das BSW fordert die grundsätzliche Straffreiheit des „Schwangerschaftsabbruchs“ bis zur 12. Woche.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=34', null, '2026-10-08', true),
  (26, 18, null, 'ja', 'Will § 218 StGB streichen, Abbrüche bis zur 18. Woche vollständig entkriminalisieren und als medizinische Regelversorgung anerkennen.', 'Streichung des §218 StGB: Schwangerschaftsabbrüche bis zur 18. Schwangerschaftswoche werden vollständig entkriminalisiert und als medizinische Dienstleistung im Rahmen der regulären Gesundheitsversorgung anerkannt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=153', null, '2026-10-08', true),
  (31, 11, null, 'teils', 'Will staatliche Förderung an ein Bekenntnis zur freiheitlich-demokratischen Grundordnung und eine Erklärung gegen Antisemitismus binden; „Demokratie leben“ ins Innenministerium verlagern.', 'Alle Einrichtungen, die Geld vom Staat erhalten wollen, müssen sich zur freiheitlich-demokratischen Grundordnung bekennen und eine Erklärung gegen Antisemitismus abgeben. Das Bundesprogramm „Demokratie leben“ siedeln wir künftig im Bundesinnenministerium an.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, '2026-10-08', true),
  (31, 12, null, 'ja', 'Will zivilgesellschaftliche Initiativen aus „Demokratie leben!“ mit einem Demokratiefördergesetz nachhaltig unterstützen.', 'Eine lebendige Zivilgesellschaft ist das Rückgrat unserer Demokratie. Mit dem Demokratiefördergesetz schaffen wir die Grundlage, zivilgesellschaftliche Initiativen, die durch Programme wie das Bundesprogramm „Demokratie leben!“ gefördert werden, nachhaltig zu unterstützen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, '2026-10-08', true),
  (31, 13, null, 'ja', 'Will Programme wie „Demokratie leben!“ finanziell stärken und mit einem Demokratiefördergesetz dauerhaft absichern.', 'Deswegen wollen wir Programme wie „Demokratie leben!“ finanziell stärken und dauerhaft mit einem Demokratiefördergesetz absichern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=109', null, '2026-10-08', true),
  (31, 14, null, 'teils', 'Will alle bestehenden Präventions- und Deradikalisierungsprogramme auf ihre Effektivität überprüfen.', 'Alle bestehenden Präventions- und Deradikalisierungsprogramme müssen auf ihre Effektivität hin überprüft werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, '2026-10-08', true),
  (31, 15, null, 'teils', 'Will vom Bund geförderte NGOs und ihre Projekte prüfen, um unnötige und ideologiebasierte Ausgaben einzusparen.', 'Laut Information der Bundesregierung werden über 500 in Deutschland ansässige oder aktive Nichtregierungsorganisationen (NGOs) direkt sowie mittelbar durch mehrheitlich im Eigentum des Bundes befindliche Unternehmen finanziell unterstützt. Im Rahmen der Haushaltskonsolidierung fordern wir eine detaillierte Prüfung dieser Organisationen und deren Projekte, mit dem Ziel, unnötige und ideologiebasierte Ausgaben einzusparen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=56', null, '2026-10-08', true),
  (31, 16, null, 'ja', 'Will mobile Beratung gegen Rechtsextremismus, Opferberatung, Demokratiebündnisse und weitere Initiativen per Demokratiefördergesetz stärker und langfristig fördern.', 'Projekte der mobilen Beratung gegen Rechtsextremismus, Opferberatungen und zivilgesellschaftliche Demokratiebündnisse, Migrant*innen-Selbstorganisationen sowie Antifa-Initiativen müssen mit einem echten, wirksamen Demokratiefördergesetz stärker unterstützt und langfristig finanziell abgesichert werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', null, '2026-10-08', true),
  (31, 17, null, 'nein', 'Will die Finanzierung von Projekten beenden, die den öffentlichen Diskurs beeinflussen sollen, und lehnt ein Demokratiefördergesetz ab.', 'Wir fordern die Beendigung der Finanzierung von Projekten, Programmen und Organisationen, die den öffentlichen Diskurs beeinflussen sollen und für bestimmte politische Meinungen stehen. Ein sogenanntes Demokratiefördergesetz lehnen wir ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=39', null, '2026-10-08', true),
  (31, 18, null, 'ja', 'Will Initiativen wie „Demokratie leben“ unterstützen und zivilgesellschaftliches Engagement fördern.', 'Stärkung von Demokratieprojekten: Initiativen, wie „Demokratie leben“, werden unterstützt und zivilgesellschaftliches Engagement wird gefördert.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=142', null, '2026-10-08', true),
  (32, 11, null, 'ja', 'Sieht das Zwei-Prozent-Ziel der NATO als Untergrenze der Verteidigungsausgaben, um die Bundeswehr personell und materiell voll auszustatten.', 'Wir verstehen das aktuelle Zwei-Prozent-Ziel der NATO als Untergrenze unserer Verteidigungsausgaben, um eine vollständig einsatzbereite Bundeswehr mit einer personellen und materiellen Vollausstattung zu ermöglichen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=52', null, '2026-10-08', true),
  (32, 12, null, 'ja', 'Will mehr Geld für Sicherheit ausgeben und dauerhaft mindestens zwei Prozent des BIP für Verteidigung.', 'Wir werden mehr Geld für unsere Sicherheit ausgeben. Das Sondervermögen für die Bundeswehr war ein erster wichtiger Schritt. […] Wir setzen uns daher auch zukünftig für eine nachhaltige Verteidigungsfinanzierung von mindestens zwei Prozent des BIP ein.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=57', null, '2026-10-08', true),
  (32, 13, null, 'ja', 'Will einen Verteidigungsetat von dauerhaft deutlich mehr als 2 Prozent des BIP.', 'Dafür braucht es verlässliche Finanzierung mit einem Verteidigungsetat, der dauerhaft die in der NATO vereinbarten und auch national definierten Ziele und Bedarfe erfüllt und dafür dauerhaft deutlich mehr als 2 Prozent des Bruttoinlandsprodukts in unsere Sicherheit und Verteidigungsfähigkeit investiert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=152', null, '2026-10-08', true),
  (32, 14, null, 'ja', 'Will die Bundeswehr zur stärksten konventionellen Streitkraft Europas machen, mit besserer Finanzierung und Ausstattung.', 'Wir wollen die Bundeswehr zur stärksten konventionellen Streitkraft in Europa machen. [...] Dazu braucht die Bundeswehr eine bessere Finanzierung und Ausstattung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=48', null, '2026-10-08', true),
  (32, 15, null, 'keine_aussage', null, null, null, 'Kapitel Verteidigungspolitik (S. 89-90) gelesen, Suche nach Verteidigungsausgaben, Bundeswehr, BIP, Prozent, Sondervermögen, Etat: nur Unterfinanzierung beklagt und ''finanziell gut ausgestattet'', keine ausdrückliche Erhöhung der Gesamtausgaben oder Ablehnung.', '2026-10-08', true),
  (32, 16, null, 'nein', 'Will Rüstungsausgaben drastisch senken, stattdessen in Bildung, Soziales und Gesundheit investieren; lehnt das Zwei-Prozent-Ziel ab.', 'Wir wollen die Rüstungsausgaben drastisch senken und stattdessen Investitionen in Bildung, Soziales, Gesundheit und eine gerechte Transformation. Das Aufrüstungsziel der NATO auf 2 Prozent des BIP oder noch mehr lehnen wir ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=23', null, '2026-10-08', true),
  (32, 17, null, 'nein', 'Lehnt höhere Militärausgaben, das Zwei-Prozent-Ziel und weitere Sondervermögen für Aufrüstung oder Militärhilfen ab.', 'Wir lehnen höhere Militärausgaben ab, die Erfüllung des Zwei-Prozent-Zieles der NATO oder gar höhere Ausgaben ebenso wie weitere Sondervermögen bzw. Schuldenfonds für die Aufrüstung der Bundeswehr oder Militärhilfen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=6', null, '2026-10-08', true),
  (32, 18, null, 'ja', 'Will die Verteidigungsausgaben auf mindestens 3 Prozent des BIP erhöhen.', 'Erhöhung der Verteidigungsausgaben: Deutschland erhöht seine Verteidigungsausgaben auf mindestens 3 % des BIP, um Modernisierung und gleichberechtigte Partnerschaft innerhalb der EU und NATO zu fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=41', null, '2026-10-08', true),
  (33, 11, null, 'ja', 'Will die Grundsicherung komplett streichen, wenn jemand grundsätzlich nicht bereit ist, Arbeit anzunehmen.', 'Wenn jemand grundsätzlich nicht bereit ist, Arbeit anzunehmen, muss der Staat davon ausgehen, dass er nicht bedürftig ist. Dann muss die Grundsicherung komplett gestrichen werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=31', null, '2026-10-08', true),
  (33, 12, null, 'ja', 'Will am Prinzip des Forderns im Bürgergeld festhalten, Mitwirkung soll eingefordert werden.', 'Das Bürgergeld ist eine steuerfinanzierte Grundsicherung und kein bedingungsloses Grundeinkommen. Deswegen wird zu Recht Mitwirkung eingefordert. An diesem Prinzip des Forderns halten wir fest.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=14', null, '2026-10-08', true),
  (33, 13, null, 'keine_aussage', null, null, null, 'Kapitel soziale Sicherung (S. 99-100) und S. 128 gelesen, Suche nach Sanktion, Kürzung, Mitwirkung, Pflichtverletzung, Bürgergeld, Regelsatz, zumutbar: nur Zusagen zum Existenzminimum und zur Anpassung des Bürgergelds, keine Aussage zu Kürzungen bei Ablehnung zumutbarer Arbeit.', '2026-10-08', true),
  (33, 14, null, 'ja', 'Will Sozialleistungen bei fehlender Initiative schrittweise reduzieren und Sanktionen wirksamer gestalten.', 'Bei fehlender Initiative sollen die Sozialleistungen Stück für Stück reduziert werden. Dazu wollen wir die Sanktionen wirksamer gestalten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=19', null, '2026-10-08', true),
  (33, 15, null, 'ja', 'Kritisiert, dass Jobcenter Pflichtverletzungen wie die Ablehnung zumutbarer Arbeit oft nicht ausreichend sanktionieren.', 'Jobcenter können in vielen Fällen von Pflichtverletzungen nicht ausreichend sanktionieren oder wenden mögliche Sanktionen nicht an, etwa wenn eine zumutbare angebotene Arbeit nicht angenommen wird.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=25', null, '2026-10-08', true),
  (33, 16, null, 'nein', 'Will das Bürgergeld zu einer sanktionsfreien individuellen Mindestsicherung umbauen.', 'Wir wollen das Bürgergeld zu einer sanktionsfreien individuellen Mindestsicherung umbauen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, '2026-10-08', true),
  (33, 17, null, 'ja', 'Hält Mitwirkungspflichten bei Qualifizierung für notwendig; wer Maßnahmen ohne triftigen Grund ablehnt, muss mit Konsequenzen rechnen.', 'Mitwirkungspflichten bei Qualifizierungsangeboten sind notwendig, um Perspektiven zu schaffen. Wer Maßnahmen ohne triftige Gründe ablehnt, muss mit Konsequenzen rechnen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', null, '2026-10-08', true),
  (33, 18, null, 'keine_aussage', null, null, null, 'Kapitel Arbeitsmarkt (S. 88–89) und Treffer zu Sanktion/Grundsicherung gelesen; Suche nach Bürgergeld, Mitwirkungspflicht, Kürzung, Jobcenter: Sanktionen nur gegen Russland und Drogenpolitik, nichts zu Leistungskürzungen.', '2026-10-08', true);
